window.__BOOK__ = {"meta":{"title_ar":"الأمير الصغير","title_zh":"小王子","author_ar":"أنطوان دو سانت إكزوبيري","author_zh":"安托万·德·圣埃克苏佩里","voice":"ar-AE-FatimaNeural (edge-tts)","ipa_note":"阿拉伯语读音为拉丁转写，供参考。","n_chapters":28,"n_paras":762,"n_sents":1635,"audio_paras":762},"chapters":[{"id":"ch00","title_ar":"إلى ليون وورث","title_en":"To Leon Werth","title_zh":"献词","paras":[{"id":"ch00p00","audio":"ch00p00.mp3","sents":[{"ar":"يرجى الأطفال العفو عن تخصيص هذا الكتاب لراشد","zh":"请孩子们原谅我把这本书献给一位大人。","t":[103,3629]},{"ar":"إنه أفضل صديقي في هذا العالم","zh":"他是我世间最好的朋友。","t":[3629,6155]},{"ar":"هذا الراشد يفهم كل شيء، حتى كتب الأطفال","zh":"这位大人洞察一切，即便是对孩子的书也能心领神会。","t":[6155,9855]},{"ar":"يقطن في فرنسا ويجوع ويصاب بالبرد","zh":"他住在法国，忍饥受寒。","t":[9855,12829]},{"ar":"يحتاج إلى بعض الراحة","zh":"他亟需慰藉。","t":[12829,14500]},{"ar":"إذا كانت هذه الأسباب لا تكفي، سأقدم هذا الكتاب لطفل هذا الراشد","zh":"若这些理由仍不足够，我便将此书献予那位成人曾是的孩童。","t":[14500,19987]},{"ar":"كل الأطفال الكبار كانوا أطفالًا في يوم من الأيام - رغم أن القليل منهم يتذكرون ذلك","zh":"所有大人曾经都是孩子——尽管他们中的许多人已不记得。","t":[19987,26868]},{"ar":"لذا، سأصحح تخصيصي: تخصيص للصغير ليون وورث","zh":"因此，我将献词更正：献予列翁·维尔特，他曾是孩童时。","t":[26868,31842]}]}]},{"id":"ch01","title_ar":"الفصل الأول","title_en":"Chapter I","title_zh":"第 1 章","paras":[{"id":"ch01p00","audio":"ch01p00.mp3","sents":[{"ar":"في السادسة من عمري، رأيت صورة جميلة في كتاب عن الغابات البرية، يُدعى «معجزات الطبيعة»، قد أظهر ثعبانًا يبتلع حيوانًا.","zh":"六岁那年，我在一本名为《自然奇观》的书里，瞥见了一幅描绘原始森林的壮丽图画。","t":[103,11868]},{"ar":"هذه صورة الثعبان يبتلع الحيوان.","zh":"这是一幅蟒蛇正在吞食动物的图画。","t":[11868,15776]},{"ar":"هذه نسخة من الصورة.","zh":"这是这幅画的复印件。","t":[15776,17763]}]},{"id":"ch01p01","audio":"ch01p01.mp3","sents":[{"ar":"كتب في الكتاب: «الثعبان يبتلع الفريسة كاملة دون أن يلعقها، ثم لا يستطيع الحركة والنوم لمدة ستة أشهر وهو يهضمها».","zh":"书中记载：“蟒蛇将猎物整个吞下，不嚼就吞。”","t":[103,11803]},{"ar":"بعد ذلك، فكرت مليًا في مغامرات الغابات، وبالتالي نجحت في رسم أول رسم لي بقلم الرسم بالألوان.","zh":"它们便无法动弹，需在消化过程中沉睡六个月。","t":[11803,20553]}]},{"id":"ch01p02","audio":"ch01p02.mp3","sents":[{"ar":"رسمي الأول.","zh":"我沉思良久，对丛林奇遇心生遐想。","t":[103,2237]},{"ar":"هذا ما يبدو عليه.","zh":"经过一番用彩色铅笔的练习，我终于完成了我的第一幅画。","t":[2237,4711]},{"ar":"عرضت عملي على الكبار وسألتهم إن كان رسمي يخيفهم.","zh":"我的第一幅画。","t":[4711,10079]},{"ar":"ماذا يخيف أي شخص من قبعة؟!","zh":"它看起来是这样的：","t":[10079,12631]}]},{"id":"ch01p03","audio":"ch01p03.mp3","sents":[{"ar":"ليس رسمي قبعة، بل كان من المفترض أن يكون ثعبانًا يبتلع فيلاً.","zh":"我把我的杰作展示给大人看，问他们这幅画是否吓到了他们。","t":[103,5773]}]},{"id":"ch01p04","audio":"ch01p04.mp3","sents":[{"ar":"لكن الكبار لم يتمكنوا من فهمها، لذا رسمت رسمًا آخر عن داخل الثعبان لكي يتمكن الكبار من فهمها.","zh":"吓什么？","t":[103,9618]},{"ar":"هم دائمًا يحتاجون إلى تفسيرات.","zh":"帽子有什么好怕的？","t":[9618,12197]}]},{"id":"ch01p05","audio":"ch01p05.mp3","sents":[{"ar":"رسمي الثاني يبدو هكذا.","zh":"我的画作并非帽子图。","t":[103,3092]},{"ar":"الكبار نصحني بترك رسم الثعبان، سواء من الداخل أو من الخارج، وأن أكرس نفسي بدلاً من ذلك للجغرافيا والتاريخ والرياضيات وعلوم النحو.","zh":"这是一幅蟒蛇消化大象的图画。","t":[3092,15868]},{"ar":"في السادسة من عمري، تخليت عن مهنة رسام رائعة.","zh":"但既然大人们无法理解，我便又画了一张：我画了蟒蛇的内部，好让大人们能看得一清二楚。","t":[15868,21316]},{"ar":"فشل رسمي الأول ورسمي الثاني، وغلب علي الإحباط.","zh":"他们总需要有人给他们解释。","t":[21316,27132]},{"ar":"الكبار لا يفهمون أنفسهم، وإنه أمر صعب على الأطفال تفسير الأشياء لهم مرارًا وتكرارًا.","zh":"我的第二号画看起来是这样的：","t":[27132,34856]}]},{"id":"ch01p06","audio":"ch01p06.mp3","sents":[{"ar":"لذا اخترت مهنة أخرى، وتعلمت قيادة الطائرات.","zh":"大人们这次则劝我放下对蟒蛇的描绘，无论是从内部还是外部，转而投身于地理、历史、算术和语法的学习。","t":[103,5408]},{"ar":"قمت بقيادة الطائرة فوق كل أنحاء العالم تقريبًا.","zh":"六岁那年，我便放弃了可能成为辉煌画家的生涯。","t":[5408,10408]},{"ar":"بالطبع، الجغرافيا كانت مفيدة جدًا لي، يمكنني تمييز الصين وأريزونا بلمسة واحدة.","zh":"我的第一幅画和第二幅画均以失败告终，令我心灰意冷。","t":[10408,18987]},{"ar":"وهذه المعرفة مفيدة جدًا إذا تم ضياع المرء في الليل.","zh":"大人自己永远不懂，孩子们总是不断地向他们解释，这实在令人厌烦。","t":[18987,23514]}]},{"id":"ch01p07","audio":"ch01p07.mp3","sents":[{"ar":"في هذه الحياة الطويلة، التقيت بكل أنواع الناس الذين يهتمون بالأمور الكبرى.","zh":"于是，我选择了另一门职业，学会了驾驶飞机。","t":[103,7461]},{"ar":"قضيت وقتًا طويلاً في عالم الكبار، رأيتهم عن قرب جدًا، وأخشى القول إن رأيي فيهم لم يتغير كثيرًا.","zh":"我驾驶飞机飞越了世界的各个角落；确实，地理学对我帮助极大。","t":[7461,16908]},{"ar":"كلما التقيت بشخص بدا لي صحيح التفكير، أظهرت له رسمي الأول، الذي احتفظت به، كتجربة.","zh":"一目了然，便能分辨出中国与亚利桑那。","t":[16908,25895]},{"ar":"أردت معرفة إن كان هو أو هي، فهيمًا حقًا.","zh":"若夜航迷失，此等知识便显宝贵。","t":[25895,29934]}]},{"id":"ch01p08","audio":"ch01p08.mp3","sents":[{"ar":"لكن الجواب كان دائمًا: «هذه قبعة.»، لذا تخليت عن ذكر الثعبان أو الغابات البرية أو النجوم.","zh":"在这漫长的人生旅程中，我与众多关注重大事务的人们有过无数次的相遇。","t":[103,9855]},{"ar":"لم أنزل نفسي إلى مستواهم وأتحدث عن البوكر والجولف والسياسة وربطات العنق.","zh":"我在成人世界中度过许多时光。","t":[9855,17355]},{"ar":"الكبار سيفخرون كثيرًا بلقاء مثل هذا الشخص الواعي.","zh":"我近距离地与他们亲密接触。","t":[17355,22474]},{"ar":"لم يتحسن رأيي فيهما كثيرًا","zh":"我对他们的看法并未有多大改观。","t":[22474,25065]}]},{"id":"ch01p09","audio":"ch01p09.mp3","sents":[{"ar":"كلما التقيت بشخص بدا لي صائب التفكير، أُظهر له رسمي رقم ١، الذي احتفظت به، على سبيل التجربة","zh":"每当我遇到一个在我看来还算有洞察力的大人，我便尝试向他展示我始终保留的那幅《第一号画》。","t":[103,9326]},{"ar":"حاولت معرفة إن كان هو أو هي، فهيمًا حقًّا","zh":"我试图探查，看这究竟是否是一个真正懂得理解的人。","t":[9326,13208]},{"ar":"لكن أيًا كان، كان يقول دائمًا: « إنها قبعة. »","zh":"但无论他是谁，他或她总是会说：“那是一顶帽子。”","t":[13208,17474]}]},{"id":"ch01p10","audio":"ch01p10.mp3","sents":[{"ar":"لذلك، لم أعد أتحدث معه عن الثعابين أو الغابات البدائية أو النجوم","zh":"于是，我便不再与那个人谈论蟒蛇、原始森林或星星。","t":[103,6053]},{"ar":"لأنني أقلل من كرامتي لأتكيف معه","zh":"我降低自己的身份以适应他。","t":[6053,9474]},{"ar":"أنا أتحدث معه عن البريدج والغولف والسياسة وربطات العنق","zh":"我与他说起桥牌、高尔夫、政治和领带。","t":[9474,14553]},{"ar":"وكان هذا الرجل السعيد جدًا بلقاء شخص فهمه","zh":"这位大人对结识如此明理的人感到非常满意。","t":[14553,18671]}]}]},{"id":"ch02","title_ar":"الفصل الثاني","title_en":"Chapter II","title_zh":"第 2 章","paras":[{"id":"ch02p00","audio":"ch02p00.mp3","sents":[{"ar":"ثم، عشت وحيدًا، لا يوجد أحد أستطيع التحدث إليه حقًا، حتى قبل ست سنوات عندما تعرضت طائراتي لحادث في صحراء الساحل.","zh":"于是，我独自一人生活，无人可倾诉衷肠，直至六年前，我的飞机在撒哈拉沙漠遭遇事故。","t":[103,12355]},{"ar":"محركي أُصاب بانهيار.","zh":"发动机里出了故障。","t":[12355,15211]},{"ar":"لذلك، لا يوجد ميكانيكي ولا مسافر معي، فأنا أحاول بنفسي إصلاح صعب.","zh":"于是，身边既无机械师，又无乘客相伴，我便孤身一人尝试着艰难地修理。","t":[15211,22921]},{"ar":"الشأن حياتي أو موتي، الماء الذي أملكه يكفي ليسبوع فقط.","zh":"生死攸关，我仅有的饮用水只够维持一周。","t":[22921,29184]},{"ar":"ليلة أولى، نمت على الرمال بعيدًا عن أي مكان مأهول بآلاف الأميال.","zh":"那第一夜，我便在千里之外、人迹罕至的沙地上安睡。","t":[29184,35974]},{"ar":"أنا أكثر وحيدًا من ربان سفينة غرق في عرض البحر.","zh":"我比孤舟在茫茫大海中的遇险者还要孤独。","t":[35974,41105]},{"ar":"فجر الشمس، صوت الغريب الصغير أستيقظني، دهشت.","zh":"晨曦初露，那奇异的细小声音将我惊醒，我惊愕不已。","t":[41105,46513]},{"ar":"قال:","zh":"它说：","t":[46513,47026]}]},{"id":"ch02p01","audio":"ch02p01.mp3","sents":[{"ar":"يرجى رسم خروفًا لي.","zh":"请给我画一只绵羊吧！","t":[103,1879]}]},{"id":"ch02p02","audio":"ch02p02.mp3","sents":[{"ar":"ماذا؟","zh":"什么！","t":[103,682]}]},{"id":"ch02p03","audio":"ch02p03.mp3","sents":[{"ar":"رسمي خروفًا.","zh":"画只绵羊吧！","t":[103,1603]}]},{"id":"ch02p04","audio":"ch02p04.mp3","sents":[{"ar":"تردديت من شدة الدهشة كأنني تلقيت صاعقة.","zh":"我惊得跳了起来，如遭雷击。","t":[103,5013]},{"ar":"أغلق عيني وأغلقها بقوة وأغلقها.","zh":"我紧闭双眼，用力眨动。","t":[5013,9316]},{"ar":"أنا أنظر حولي بعناية.","zh":"我环顾四周，仔细打量。","t":[9316,12316]},{"ar":"رأيت رجلاً غريباً يحدق في بالغ جدية.","zh":"我瞥见一个极为奇特的小人儿，他正一本正经地打量着我。","t":[12316,16855]},{"ar":"هنا يمكنكم رؤية الصورة التي رسمتها له لاحقًا بنجاح.","zh":"这里可见我后来为他画的最成功的肖像。","t":[16855,22658]},{"ar":"لكن رسمي بالطبع ليس بنصف روعة شخصه.","zh":"但我的画作显然远不及它的原型迷人。","t":[22658,26053]}]},{"id":"ch02p05","audio":"ch02p05.mp3","sents":[{"ar":"ليس خطأي.","zh":"这并非我的过错。","t":[103,2171]},{"ar":"في السادسة من عمري، قتل الأكبر مني حلمي كرسام، لم أتعلم رسم أي شيء، سوى التنانين من الخارج والتنانين من الداخل.","zh":"六岁那年，大人们便扼杀了我的画家梦想，我从未学会画任何东西，除了从外面看的蟒蛇和从里面看的蟒蛇。","t":[2171,12737]}]},{"id":"ch02p06","audio":"ch02p06.mp3","sents":[{"ar":"أدهشني بصورة لا تصدق، وفتحت عيني بعمق، وأنا أحدق في هذا الشبح المفاجئ بلا انقطاع.","zh":"我惊愕地瞪大了眼睛，几乎要目不转睛地凝视着这个突如其来的身影。","t":[103,8908]},{"ar":"تذكر، كنت في صحراء نائية، بعيدة آلاف الأميال عن أي مكان مأهول.","zh":"记得，我在人烟稀少的沙漠中，千里之外遭遇了坠机。","t":[8908,16092]},{"ar":"يبدو أنه ليس محبوسًا في الرمال، ولا مغمورًا بالضجر أو الجوع أو العطش أو الخوف.","zh":"他似乎既不是在沙中迷失方向，也不是因疲惫、饥饿、口渴或恐惧而昏倒。","t":[16092,23763]},{"ar":"لم يكن عليه أي أثر من فقدان الطريق في الصحراء أو الابتعاد عن البشرية بألف ميل.","zh":"他身上丝毫没有在沙漠中迷失方向、远离人烟千里的孩子的痕迹。","t":[23763,31118]},{"ar":"أخيرًا، بدأت الحديث، قلت له:","zh":"终于开口说话，我对他说：","t":[31118,34092]}]},{"id":"ch02p07","audio":"ch02p07.mp3","sents":[{"ar":"لكن – ماذا تفعل هنا؟","zh":"但——你在此做什么？","t":[103,2024]}]},{"id":"ch02p08","audio":"ch02p08.mp3","sents":[{"ar":"يستجيب ببطء، وكأنه يتحدث عن أمر هام جدًا:","zh":"他缓缓地回答，仿佛在谈论一件极重要的事情：","t":[103,4668]}]},{"id":"ch02p09","audio":"ch02p09.mp3","sents":[{"ar":"يرجى رسم خروفًا لي...","zh":"请给我画一只羊吧……","t":[103,1826]}]},{"id":"ch02p10","audio":"ch02p10.mp3","sents":[{"ar":"عندما تُغلب القوى الغامضة، لا يجرؤ أحد على التمرد.","zh":"当神秘的力量压倒一切，人不敢违抗。","t":[103,5618]},{"ar":"مضحك للغاية، بعيدًا عن البشر مئات الأميال، في أشد لحظات الخطر، سحبت ورقة وقلمًا من جيبي.","zh":"荒诞至极，远离人烟千里，生死攸关之际，我还是从口袋里掏出了一张纸和一支钢笔。","t":[5618,15539]},{"ar":"ومع ذلك، تذكرت أن دراستي كانت مركزية في الجغرافيا والتاريخ والرياضيات والنحو، فشعرت ببعض الإحباط وأخبرت الطفل الصغير، لن أستطيع الرسم.","zh":"然而，我回想起我的学业专注于地理、历史、算术和语法，便有些不悦地对那个小家伙说，我不会画画。","t":[15539,28684]},{"ar":"قال:","zh":"他回答道：","t":[28684,29197]}]},{"id":"ch02p11","audio":"ch02p11.mp3","sents":[{"ar":"لا مشكلة.","zh":"这无妨。","t":[103,2013]},{"ar":"رسم لي خروفًا...","zh":"画一只羊吧……","t":[2013,3527]}]},{"id":"ch02p12","audio":"ch02p12.mp3","sents":[{"ar":"لم أرسم قط خروفًا.","zh":"但我从未画过羊。","t":[103,3026]},{"ar":"لذلك، رسمت له واحدة من الرسومات التي أرسمها عادة.","zh":"于是，我为他画出了我常画的其中一幅。","t":[3026,8987]},{"ar":"هذا هو الثعبان من الخارج","zh":"这是从外面看的蟒蛇。","t":[8987,10908]},{"ar":"أدهشني سماع الطفل يقول لها:","zh":"我惊愕地听见那小家伙对它说：","t":[10908,13316]}]},{"id":"ch02p13","audio":"ch02p13.mp3","sents":[{"ar":"لا! لا! لا!","zh":"不！不！不！","t":[103,3934]},{"ar":"لا أريد أن يكون لدي فهد في بطن التنين.","zh":"我不想在蟒蛇肚子里有一只大象。","t":[3934,8408]},{"ar":"التمساح خطير للغاية، والأفريقية ثقيلة جدًا.","zh":"蟒蛇极为危险，而大象又非常笨重。","t":[8408,13829]},{"ar":"في مكان عيشي، كل شيء صغير جدًا.","zh":"在我居住的地方，一切都极小。","t":[13829,18132]},{"ar":"أحتاج إلى خروف.","zh":"我需要的是一只羊。","t":[18132,20632]},{"ar":"رسم لي خروفًا.","zh":"画一只羊吧。","t":[20632,22171]}]},{"id":"ch02p14","audio":"ch02p14.mp3","sents":[{"ar":"لذلك، رسمت صورة.","zh":"于是，我画了一幅画。","t":[103,2155]}]},{"id":"ch02p15","audio":"ch02p15.mp3","sents":[{"ar":"يحدق بحذر، ويقول:","zh":"他仔细端详着，然后说道：","t":[103,2590]}]},{"id":"ch02p16","audio":"ch02p16.mp3","sents":[{"ar":"لا!","zh":"不！","t":[103,1382]},{"ar":"الشاة أصبحت مريضة جدًا.","zh":"这羊已经病得很重了。","t":[1382,4697]},{"ar":"أرسم لي خروفًا.","zh":"再给我画一个。","t":[4697,6237]}]},{"id":"ch02p17","audio":"ch02p17.mp3","sents":[{"ar":"ثم، رسمت أخرى.","zh":"于是，我又画了一张。","t":[103,1957]}]},{"id":"ch02p18","audio":"ch02p18.mp3","sents":[{"ar":"صديقي يضحك بابتسامة، بلطف وروحانية.","zh":"我的朋友微笑着，既温柔又宽容。","t":[103,3905]}]},{"id":"ch02p19","audio":"ch02p19.mp3","sents":[{"ar":"هذا بالتأكيد ليس خروفًا.","zh":"这显然不是一只羊。","t":[103,3263]},{"ar":"هذا خروف ذكر.","zh":"这是一只公羊。","t":[3263,5737]},{"ar":"إنه يمتلك رؤوسًا.","zh":"它长着角哩。","t":[5737,7632]}]},{"id":"ch02p20","audio":"ch02p20.mp3","sents":[{"ar":"ثم، رسمت مجددًا.","zh":"于是，我又重新画了一次。","t":[103,2248]}]},{"id":"ch02p21","audio":"ch02p21.mp3","sents":[{"ar":"لكن هذا اللوحة تم رفضها، كغيرها من اللوحات الأخرى.","zh":"但这幅画也被拒绝了，就像其他那些一样。","t":[103,4734]}]},{"id":"ch02p22","audio":"ch02p22.mp3","sents":[{"ar":"هذا قد أصبح قديمًا جدًا.","zh":"这只太老了。","t":[103,3395]},{"ar":"أريد خروفًا يعيش وقتًا طويلاً","zh":"我要一只能活很久的羊。","t":[3395,6145]}]},{"id":"ch02p23","audio":"ch02p23.mp3","sents":[{"ar":"أفقد صبري وأنا أتلهف على فكك محركي بأسرع وقت ممكن","zh":"我的耐心已耗尽，急于开始拆卸我的发动机。","t":[103,5418]}]},{"id":"ch02p24","audio":"ch02p24.mp3","sents":[{"ar":"لذلك رسمت هذه اللوحة بسرعة","zh":"于是，我草草地画了这幅画。","t":[103,2734]},{"ar":"فشرحت ذلك عفوًا","zh":"于是，我随口解释道。","t":[2734,4406]}]},{"id":"ch02p25","audio":"ch02p25.mp3","sents":[{"ar":"ذلك ليس سوى صندوق","zh":"这不过是他的一只箱子。","t":[103,1761]},{"ar":"الخروف الذي طلبته يوجد بداخله","zh":"那你要的绵羊就在里面。","t":[1761,4497]}]},{"id":"ch02p26","audio":"ch02p26.mp3","sents":[{"ar":"أدهشني أن أرى وجه القاضي الصغير يتألق","zh":"我惊讶地看到，我的这位小法官脸上露出了光芒：","t":[103,3314]}]},{"id":"ch02p27","audio":"ch02p27.mp3","sents":[{"ar":"هذا تمامًا ما أردته","zh":"这正是我想要的！","t":[103,1800]},{"ar":"هل تحتاج هذه الشاة إلى الكثير من العشب؟","zh":"这只绵羊需要很多草吗？","t":[1800,5050]}]},{"id":"ch02p28","audio":"ch02p28.mp3","sents":[{"ar":"لماذا؟","zh":"为什么？","t":[103,866]}]},{"id":"ch02p29","audio":"ch02p29.mp3","sents":[{"ar":"لأن في مكان عيشي كل شيء صغير جدًا","zh":"因为在我住的地方，一切都极小。","t":[103,3445]}]},{"id":"ch02p30","audio":"ch02p30.mp3","sents":[{"ar":"أقول: 'بالطبع، يكفي'","zh":"我说：“肯定够了。”","t":[103,2405]},{"ar":"أعطيتك شاة صغيرة جدًا","zh":"我给你的是一只很小很小的绵羊。","t":[2405,4879]}]},{"id":"ch02p31","audio":"ch02p31.mp3","sents":[{"ar":"فانحنى فوق اللوحة و نظر","zh":"他俯身细看那幅画。","t":[103,2313]}]},{"id":"ch02p32","audio":"ch02p32.mp3","sents":[{"ar":"هذا صغير جدًا، انظروا! لقد غاب عن وعيه","zh":"如此小巧，看哪！","t":[103,4921]},{"ar":"لقد غاب عن وعيه...","zh":"它已经入睡……","t":[4921,6276]}]},{"id":"ch02p33","audio":"ch02p33.mp3","sents":[{"ar":"وهكذا التقيت بأمير الصغير","zh":"就这样，我结识了小王子。","t":[103,2616]}]}]},{"id":"ch03","title_ar":"الفصل الثالث","title_en":"Chapter III","title_zh":"第 3 章","paras":[{"id":"ch03p00","audio":"ch03p00.mp3","sents":[{"ar":"استغرقت وقتًا طويلًا لأكتشف من أين أتى.","zh":"我费了好长时间才弄清他来自何方。","t":[103,4434]},{"ar":"الأمير الصغير سألني الكثير من الأسئلة، ولكن يبدو أنه لا يسمع أسئلتي.","zh":"小王子虽向我提问无数，却似乎对我的问题充耳不闻。","t":[4434,11921]},{"ar":"الكلمات العفوية، تدريجيًا كشفت لي عن كل الأسرار.","zh":"偶然间的话语，渐渐向我揭示了所有真相。","t":[11921,16474]}]},{"id":"ch03p01","audio":"ch03p01.mp3","sents":[{"ar":"مثلاً، عندما رآني طائري لأول مرة (لن أرسم طائري؛ إن ذلك معقد جدًا بالنسبة لي)، سألني:","zh":"例如，他头一回见到我的飞机时（我不愿画飞机，那太复杂了），便问我：","t":[103,9313]}]},{"id":"ch03p02","audio":"ch03p02.mp3","sents":[{"ar":"ما هذا الشئ؟","zh":"那是什么玩意儿？","t":[103,1076]}]},{"id":"ch03p03","audio":"ch03p03.mp3","sents":[{"ar":"ذلك ليس شيء.","zh":"那不是玩意儿。","t":[103,2500]},{"ar":"هي تطير.","zh":"它会飞。","t":[2500,4342]},{"ar":"هذه هي الطائرة.","zh":"这是飞机。","t":[4342,6803]},{"ar":"هذه هي طائرتي.","zh":"这是我的飞机。","t":[6803,8421]}]},{"id":"ch03p04","audio":"ch03p04.mp3","sents":[{"ar":"أنا فخور بأنه يعلم أنني أستطيع الطيران.","zh":"我为他能知道我会飞而自豪。","t":[103,3747]}]},{"id":"ch03p05","audio":"ch03p05.mp3","sents":[{"ar":"هذا فجأة صرخت:","zh":"他突然喊道：","t":[103,1879]}]},{"id":"ch03p06","audio":"ch03p06.mp3","sents":[{"ar":"كيف؟","zh":"怎么！","t":[103,1566]},{"ar":"هل أنت من السماء أنت؟","zh":"你是从天上掉下来的吗？","t":[1566,3448]}]},{"id":"ch03p07","audio":"ch03p07.mp3","sents":[{"ar":"نعم، أجبت بتبجيل.","zh":"是的，我谦逊地回答。","t":[103,2208]}]},{"id":"ch03p08","audio":"ch03p08.mp3","sents":[{"ar":"أوه!","zh":"啊！","t":[103,1526]},{"ar":"هذا مضحك!","zh":"这倒有趣！","t":[1526,2632]}]},{"id":"ch03p09","audio":"ch03p09.mp3","sents":[{"ar":"أنفجرالأمير الصغير في ضحك ناعم، مما أزعجني كثيرًا.","zh":"那小王子突然发出一阵清脆的笑声，这笑声让我非常恼火。","t":[103,5803]},{"ar":"أود أن يتم التعامل مع مصائبي على محمل الجد.","zh":"我愿我的不幸得到认真对待。","t":[5803,9684]}]},{"id":"ch03p10","audio":"ch03p10.mp3","sents":[{"ar":"هذا ما قال بعد ذلك:","zh":"他接着又说：","t":[103,1918]}]},{"id":"ch03p11","audio":"ch03p11.mp3","sents":[{"ar":"أنتم أيضًا من السماء جئتم!","zh":"你们也是从天上来的！","t":[103,3434]},{"ar":"هل هذا كوكبك؟","zh":"这是你的星球吗？","t":[3434,4750]}]},{"id":"ch03p12","audio":"ch03p12.mp3","sents":[{"ar":"في تلك اللحظة، لاحظت ضوءا في ظلال شخصيته الغامضة؛ فسألت بغتة:","zh":"那一刻，我瞥见了他神秘身影中的光芒；于是，我突兀地问道：","t":[103,6037]}]},{"id":"ch03p13","audio":"ch03p13.mp3","sents":[{"ar":"هل أنتم أيضًا من كوكب آخر؟","zh":"你们也是从另一个星球来的吗？","t":[103,2510]}]},{"id":"ch03p14","audio":"ch03p14.mp3","sents":[{"ar":"لم يجيب.","zh":"他并未回答。","t":[103,1829]},{"ar":"كان يرتجف رأسه ببطء، والنظر لم يفتر عن طائرتي.","zh":"他轻轻摇晃着头，目光未离我的飞机。","t":[1829,6552]}]},{"id":"ch03p15","audio":"ch03p15.mp3","sents":[{"ar":"بالطبع، لا يمكنك أن تأتي من مكان بعيد جدًا هنا……","zh":"那确实，你不可能从很远处来到这里……","t":[103,4629]}]},{"id":"ch03p16","audio":"ch03p16.mp3","sents":[{"ar":"هو غرق في التأمل، ولم يستطع الخروج منه لفترة طويلة.","zh":"他陷入沉思，久久未能自拔。","t":[103,6276]},{"ar":"استخرجت خروفك، فغرق في تأمل مادته المحبوبة.","zh":"他掏出我的绵羊，便沉浸在心爱宝物的沉思之中。","t":[6276,10671]}]},{"id":"ch03p17","audio":"ch03p17.mp3","sents":[{"ar":"استثار فضولي قلبي هذا النصف من الشك فيما يتعلق بالكواكب الأخرى، لذا حاولت أن أستكشف المزيد عن هذا الموضوع.","zh":"我好奇之心被他对“其他星球”的这种半信半疑所激起，因此我竭力想了解更多关于这个话题。","t":[103,9102]}]},{"id":"ch03p18","audio":"ch03p18.mp3","sents":[{"ar":"يا صغيري، من أين أنت جئت؟","zh":"我的小家伙，你从哪里来？","t":[103,3632]},{"ar":"ماذا تعني بكلمة 'أنا أعيش هنا' التي تتحدث عنها؟","zh":"这“我住在哪里”，你所说的那是什么意思？","t":[3632,9289]},{"ar":"أين تريد أن تأخذ شعيرتك إلى هناك؟","zh":"你打算把你的绵羊带到哪里去？","t":[9289,12500]}]},{"id":"ch03p19","audio":"ch03p19.mp3","sents":[{"ar":"بعد تفكير قليل، أجاب:","zh":"沉思片刻后，他回答道：","t":[103,2589]}]},{"id":"ch03p20","audio":"ch03p20.mp3","sents":[{"ar":"ما أعجبني في هذا الصندوق الذي أعطيتني إياه أنه يمكن أن يستخدمه كمنزل ليلاً.","zh":"这箱子你送给我真是太好了，夜里他可以用它做屋子。","t":[103,6656]}]},{"id":"ch03p21","audio":"ch03p21.mp3","sents":[{"ar":"بالطبع.","zh":"这倒是。","t":[103,1816]},{"ar":"إذا كنت صالحًا، سأعطيك حبلاً لتربط به في النهار، وأعطيك عمودًا لتربطه به.","zh":"若你听话，我还会给你一根绳子，白天用来拴住它，再给你一个桩子。","t":[1816,9000]}]},{"id":"ch03p22","audio":"ch03p22.mp3","sents":[{"ar":"بدى الأمير الصغير مذهولًا من هذا العرض:","zh":"小王子对这个提议似乎感到震惊：","t":[103,2971]}]},{"id":"ch03p23","audio":"ch03p23.mp3","sents":[{"ar":"تربعه!","zh":"拴住他！","t":[103,1868]},{"ar":"فكرة مضحكة!","zh":"真是个古怪的主意！","t":[1868,3316]}]},{"id":"ch03p24","audio":"ch03p24.mp3","sents":[{"ar":"لكن، إذا لم تربعه، سيذهب إلى كل مكان وسيضيع.","zh":"“可是，如果你不拴住他，”我说，“他会到处乱跑，然后走失的。”","t":[103,5261]}]},{"id":"ch03p25","audio":"ch03p25.mp3","sents":[{"ar":"ابتسم صديقي مرة أخرى وقال:","zh":"我的朋友又爆发出一阵笑声：","t":[103,2852]}]},{"id":"ch03p26","audio":"ch03p26.mp3","sents":[{"ar":"إلى أين يعتقد أن شعيرته سيذهب؟","zh":"他以为它会跑到哪里去呢？","t":[103,3168]}]},{"id":"ch03p27","audio":"ch03p27.mp3","sents":[{"ar":"أينما أراد.","zh":"无论哪里。","t":[103,2171]},{"ar":"إلى الأمام، أمام عينيه.","zh":"前方，就在他面前。","t":[2171,4395]}]},{"id":"ch03p28","audio":"ch03p28.mp3","sents":[{"ar":"قال الأمير الصغير بجدية:","zh":"小王子认真地说：","t":[103,2221]}]},{"id":"ch03p29","audio":"ch03p29.mp3","sents":[{"ar":"لا يهم.","zh":"那无关紧要。","t":[103,1868]},{"ar":"كل شيء صغير جدًا في المكان الذي أعيش فيه.","zh":"我所在之处的万物都如此渺小。","t":[1868,5434]}]},{"id":"ch03p30","audio":"ch03p30.mp3","sents":[{"ar":"بإضافة بعض الحزن، قال:","zh":"带着一丝忧伤，他补充道：","t":[103,2563]}]},{"id":"ch03p31","audio":"ch03p31.mp3","sents":[{"ar":"إلى الأمام، لا أحد يمكنه الذهاب بعيدًا هناك.","zh":"前方，无人能走得太远……","t":[103,4194]}]}]},{"id":"ch04","title_ar":"الفصل الرابع","title_en":"Chapter IV","title_zh":"第 4 章","paras":[{"id":"ch04p00","audio":"ch04p00.mp3","sents":[{"ar":"أعلمتني بذلك حقيقة أخرى مهمة؛ إن كوكب الأمير الصغير هو كوكب صغير الحجم لا يتجاوز حجم بيت.","zh":"我因此得知了第二个重要的事实：小王子来自的星球，其大小不过是一座房子的规模。","t":[103,8866]}]},{"id":"ch04p01","audio":"ch04p01.mp3","sents":[{"ar":"لم يكن هذا يثير دهشتي حقًا.","zh":"但这并未真正让我感到惊讶。","t":[103,3592]},{"ar":"إضافة إلى الكواكب الكبيرة التي أعطيناها أسماء، مثل الأرض واليوروبا والمريخ وفينوس، هناك مئات من الكواكب الأخرى، بعضها صغير جدًا حتى يصعب رؤيته بالتلسكوب.","zh":"除了那些被我们命名的巨大行星——如地球、木星、火星、金星——之外，还有数百颗其他行星，其中一些小得连望远镜都难以辨认。","t":[3592,18868]},{"ar":"عندما يكتشف علماء الفلك هذه النوعية من الكواكب، لا يمنحونها أسماء، بل يمنحونها أرقامًا فقط.","zh":"天文学家发现这类星球时，并不赋予它们名字，而只赋予它们编号。","t":[18868,28592]},{"ar":"ربما يسميه “كويكب 325”.","zh":"他或许会称之为“小行星325号”。","t":[28592,32868]}]},{"id":"ch04p02","audio":"ch04p02.mp3","sents":[{"ar":"لدي أسباب جدية لأعتقد أن كوكب الأمير الصغير هو الكوكب المعروف باسم ب-٦١٢.","zh":"我有充分的理由相信，小王子来自的星球是B-612号小行星。","t":[103,8234]}]},{"id":"ch04p03","audio":"ch04p03.mp3","sents":[{"ar":"هذا الكويكب تم رصده مرة واحدة فقط من خلال التلسكوب.","zh":"这颗小行星仅被望远镜观测过一次。","t":[103,5908]},{"ar":"عالم الفلك التركي هو من قام بمراقبة ذلك في عام 1909.","zh":"那是一位土耳其天文学家在1909年观测到的。","t":[5908,11947]}]},{"id":"ch04p04","audio":"ch04p04.mp3","sents":[{"ar":"عندما اكتشفه الفلكي، قام بعرض كبير في مؤتمر علم الفلك العالمي.","zh":"天文学家在发现之际，曾于国际天文大会上作了一场盛大的演示。","t":[103,6829]},{"ar":"لكن كان يرتدي ثوبًا تركيًا، فلم يؤمن به أحد.","zh":"但他身着土耳其服装，因此无人相信他的话。","t":[6829,11145]}]},{"id":"ch04p05","audio":"ch04p05.mp3","sents":[{"ar":"البالغون يتصرفون هكذا...","zh":"大人就是这样……","t":[103,2405]}]},{"id":"ch04p06","audio":"ch04p06.mp3","sents":[{"ar":"لحسن الحظ، من أجل سمعته، أصدر الزعيم التركي مرسوماً يلزم فيه المواطنين بالتغيير إلى لباس أوروبي، ويُعاقب المخالفون بالاعدام.","zh":"幸而，为了B-612小行星的声誉，土耳其独裁者颁布了一道法令，规定臣民必须改穿欧洲服装，违者处以死刑。","t":[103,12487]},{"ar":"ثم، في عام 1920، أظهر ذلك الفلكي عرضه مرة أخرى، مرتديًا ثوبًا راقيًا، متألقًا في جماله.","zh":"于是，1920年，这位天文学家再次身着考究的服饰，仪态万方地展示了他的演示。","t":[12487,24066]},{"ar":"هذا المرة، قبلوه الجميع.","zh":"这一次，众人都接受了他的报告。","t":[24066,26619]}]},{"id":"ch04p07","audio":"ch04p07.mp3","sents":[{"ar":"إذا لم يكن من أجل هؤلاء الكبار وأساليبهم، لن أستعرض لكم تفاصيل هذا النجم الصغير وأكتب رقمه.","zh":"若非为了这些大人及其习性，我才不会向你们详述这颗小行星的细节，并记下它的编号。","t":[103,9013]},{"ar":"ليسألوا عن أي أمر أساسي.","zh":"告诉他们你交了一个新朋友，他们从不询问任何重要的事情。","t":[9013,12158]},{"ar":"لن يسألواك أبدًا: « كيف صوته؟ »","zh":"他们从不会问你：“他的嗓音是怎样的？”","t":[12158,15158]},{"ar":"ما هو اللعبة التي يحبها أكثر؟","zh":"他最喜欢玩什么游戏？","t":[15158,18632]},{"ar":"هل يجمع فراشاته؟","zh":"他是否采集蝴蝶标本？","t":[18632,21145]},{"ar":"كم عدد إخوته؟","zh":"他有多少个兄弟？","t":[21145,23263]},{"ar":"كم يبلغ وزنه؟","zh":"他体重多少？","t":[23263,25474]},{"ar":"هم يعتقدون أنهم يعرفونه من خلال هذه الأرقام فقط.","zh":"他们只从这些数字中认为他们已经了解了他。","t":[25474,29973]}]},{"id":"ch04p08","audio":"ch04p08.mp3","sents":[{"ar":"إذا أخبرت الكبار: \"رأيت بيتًا جميلًا مبنى من الطوب الأحمر، ينمو على حواف نوافذه زهور البرتقال، ويحط على سطحه حمامات...\" فإنهم لن يستطيعوا تخيل شكل هذا البيت.","zh":"若你对大人说：“我看见一幢红砖砌成的美丽房子，窗台上种着天竺葵，屋顶栖息着鸽子，”他们便无法想象这房子的模样。","t":[103,16342]},{"ar":"أقول لهم: “رأيت بيتًا يساوي عشرة آلاف فرنك.” سيشعرون بالدهشة ويقولون: “أوها! ما هذا البيت الجميل!”","zh":"你们得对他们说：“我看见一幢价值两万法郎的房子。”他们就会惊叹：“哦，多美的房子啊！”","t":[16342,27408]}]},{"id":"ch04p09","audio":"ch04p09.mp3","sents":[{"ar":"الأمير الصغير دليل وجوده هو سلوكه اللطيف وضحكه العذب، وهو في طلب للخروف.","zh":"小王子存在的证据，便是他风度翩翩、笑声朗朗，且在寻找一只绵羊。","t":[103,8079]},{"ar":"إذا كان يريد شخص ما شاة، فهذا هو دليل وجوده. ما الفائدة من إخبارهم بهذا؟","zh":"若有人想要一只绵羊，这便是他存在的证明。告诉他们这些又有什么用呢？","t":[8079,16579]},{"ar":"يبركون كتفاً، ويجعلونك كطفل.","zh":"他们耸耸肩，把你当做个孩子。","t":[16579,20789]},{"ar":"إذا قلت لهم: \"يأتي من كوكبه ب-612\"، سيؤمنون بهذا وسيتركوك وشأنك.","zh":"若你对他们说：“他来自的星球是B-612号小行星，”他们便会信服，不再对你纠缠不休。","t":[20789,28895]}]},{"id":"ch04p10","audio":"ch04p10.mp3","sents":[{"ar":"هم يفعلون هكذا","zh":"他们就是这样。","t":[103,1511]},{"ar":"لا يمكننا إلقاء اللوم عليهم لذلك","zh":"不可因此而怪罪他们。","t":[1511,4208]},{"ar":"يجب أن يكون لدى الأطفال تهاون كبير تجاه الكبار","zh":"孩子们理应对大人怀有极大的宽容。","t":[4208,8432]}]},{"id":"ch04p11","audio":"ch04p11.mp3","sents":[{"ar":"لكن، بالنسبة لنا الذين نفهم الحياة، فإن الأرقام ليست أكثر من مجرد أشياء تافهة","zh":"然而，对于我们这些懂得生活的人来说，数字不过是无关紧要之物。","t":[103,7553]},{"ar":"كنت أرغب في بدء هذه القصة بأسلوب الأساطير","zh":"我本想以童话的形式开始这个故事。","t":[7553,10908]},{"ar":"في يوم من الأيام كان هناك أمير صغير يعيش على كوكب صغير جدًا لا يتجاوز حجمه، وكان يحتاج إلى خروف","zh":"从前有个小王子，他住在一颗比他自己大不了多少的星球上，需要一只绵羊。","t":[10908,20158]}]},{"id":"ch04p12","audio":"ch04p12.mp3","sents":[{"ar":"وهذا سيجعل قصتي تبدو أكثر واقعية للذين يفهمون الحياة","zh":"这会让我的故事显得更加真实，对于那些懂得生活的人来说。","t":[103,5222]}]},{"id":"ch04p13","audio":"ch04p13.mp3","sents":[{"ar":"لا أريد أن يقرأ أحد الكتاب بلادة","zh":"我不愿有人漫不经心地读我的书。","t":[103,3037]},{"ar":"أكتب هذه الذكريات وأنا أعاني من حزن شديد","zh":"我记录这些回忆，心中满是哀伤。","t":[3037,6826]},{"ar":"منذ ست سنوات، غادرني صديقي الصغير ومعه خروفي","zh":"六年来，我的朋友带着他的羊离我远去。","t":[6826,11458]},{"ar":"إذا حاولت أن أصفه هنا، فإن ذلك لكي لا أنسى","zh":"若我尝试在此描述他，那是为了确保我不会忘记他。","t":[11458,15553]},{"ar":"نسيان الأصدقاء يُسبب الحزن","zh":"遗忘朋友是可悲的。","t":[15553,17750]},{"ar":"ليس الجميع يمتلك صديقًا في حياته","zh":"并非人人都有过朋友。","t":[17750,20776]},{"ar":"إذا نسيتُه، قد أصبحتُ مثل البالغين الذين يهتمون فقط بالأرقام...","zh":"若我忘记了他，我或许会变成那些只对数字感兴趣的成年人……","t":[20776,26447]}]},{"id":"ch04p14","audio":"ch04p14.mp3","sents":[{"ar":"لذلك، اشتريت مرة أخرى صندوقًا من الألوان وبعض القلموطين","zh":"为此，我又买了一盒颜料和几支铅笔。","t":[103,5247]},{"ar":"في هذا العمر إعادة بدء الرسم بالنسبة لي أمر صعب، منذ أن رسمت في السادسة من عمري ثعبانًا يُرى من الخارج وثعبانًا يُرى من الداخل لم أرسم شيئًا آخر بعد ذلك","zh":"在这个年纪重拾绘画，对我而言实属不易，自从六岁那年画过一条从外面看的蟒蛇和一条从里面看的蟒蛇后，我从未再画过其他图画。","t":[5247,18105]},{"ar":"سأبذل قصارى جهدي لجعل رسوماتي تبدو واقعية قدر الإمكان","zh":"我将尽力让我的肖像画尽可能逼真。","t":[18105,23092]},{"ar":"لكنني لست واثقاً من أنني سأنجح","zh":"但我并不确信能成功。","t":[23092,26197]},{"ar":"الواحدة جيدة في رسمها، والآخرى بعيدة عن النموذج الأصلي","zh":"一幅画得还可以，另一幅却与原型相差甚远。","t":[26197,31421]},{"ar":"أخطأت في رسم طول أمير الصغير: أحياناً أرسمه طويلاً، وأحياناً قصيراً","zh":"我描绘小王子的身高时，也犯了一些错误：有时他画得太高，有时又太矮。","t":[31421,37737]},{"ar":"أنا لدي بعض الشكوك حول لون ملابسه","zh":"我对他的服装颜色也有些疑虑。","t":[37737,40895]},{"ar":"أنا أتردد في السير، أحياناً أكون جيداً، وأحياناً سيئاً، آمل أن أكون جيداً بشكل عام","zh":"我笨拙地摸索前行，时而出色，时而糟糕，但愿总体上还能过得去。","t":[40895,50447]}]},{"id":"ch04p15","audio":"ch04p15.mp3","sents":[{"ar":"في بعض التفاصيل الأكثر أهمية، لا أستطيع تجنب الأخطاء دائمًا","zh":"在某些更为重要的细节上，我也难免出错。","t":[103,5168]},{"ar":"لكن هذا ليس خطأي","zh":"但这并非是我的过错。","t":[5168,6695]},{"ar":"صديقي لا يفسر لي أي شيء أبداً","zh":"我的朋友从不向我解释任何事。","t":[6695,9550]},{"ar":"ربما يعتقد أنه يشبهني","zh":"他或许以为我与他相似。","t":[9550,11839]},{"ar":"لكن، آسف، لا أعلم كيف أرى الأغنام عبر جدران الصندوق","zh":"然而，唉，我不知如何透过箱子的墙壁看到绵羊。","t":[11839,16776]},{"ar":"ربما أنا أشبه الكبار قليلاً","zh":"或许我也有点像大人了。","t":[16776,19171]},{"ar":"أُضطرت إلى أن أتقدم في السن","zh":"我不得不变老。","t":[19171,21606]}]}]},{"id":"ch05","title_ar":"الفصل الخامس","title_en":"Chapter V","title_zh":"第 5 章","paras":[{"id":"ch05p00","audio":"ch05p00.mp3","sents":[{"ar":"يومًا بعد يوم، في خلال محادثاتي معه، تعرفت شيئًا فشيئًا على كوكب الأمير الصغير، وعلى سبب رحيله، وعلى رحلته.","zh":"随着日复一日，在与他的交谈中，我逐渐了解了小王子的星球、他离开那里的经过以及他的旅行。","t":[103,11237]},{"ar":"المعلومات تأتي ببطء كأنها تنساب من تفكيره العفوي","zh":"信息缓缓而来，如同偶然自他思绪中飘落。","t":[11237,15434]},{"ar":"وهكذا، في اليوم الثالث، سمعت عن كارثة أشجار الباوباب.","zh":"就这样，第三天，我听说了猴面包树的灾难。","t":[15434,20460]}]},{"id":"ch05p01","audio":"ch05p01.mp3","sents":[{"ar":"هذا المرة، كانت الخروف هي التي جعلتني أعرف.","zh":"这次，又是绵羊让我得以知晓。","t":[103,5118]},{"ar":"الأمير الصغير فجأةً سألني بجدية: \"هل تأكل الأغنام الشجيرات الصغيرة حقًا؟\"","zh":"小王子突然严肃地问我：“羊真的会吃小灌木吗？”","t":[5118,11631]}]},{"id":"ch05p02","audio":"ch05p02.mp3","sents":[{"ar":"نعم، هذا صحيح.","zh":"是的，千真万确。","t":[103,1813]}]},{"id":"ch05p03","audio":"ch05p03.mp3","sents":[{"ar":"آه!","zh":"啊！","t":[103,1421]},{"ar":"أوه! يسرني ذلك!","zh":"啊，太好了！","t":[1421,4132]}]},{"id":"ch05p04","audio":"ch05p04.mp3","sents":[{"ar":"لا أفهم لماذا يأكل الأغنام تلك الشجيرات الصغيرة بأهمية كبيرة.","zh":"我不懂羊儿为何要吃那些小灌木如此重要。","t":[103,6579]},{"ar":"الأمير الصغير يستمر في القول:","zh":"小王子接着说：","t":[6579,9119]}]},{"id":"ch05p05","audio":"ch05p05.mp3","sents":[{"ar":"هل ستأكلون أيضًا شجر الباباوباب؟","zh":"那么，它们也会吃猴面包树吗？","t":[103,2800]}]},{"id":"ch05p06","audio":"ch05p06.mp3","sents":[{"ar":"أشير إلى الأمير الصغير بأن شجيرات الباباوب ليست شجيرات صغيرة، بل هي أشجار ضخمة كالمعابد، وأنه حتى إذا أخذ معه قطيعًا من الفيلة، فإن القطيع لن يستطيع أكل شجرة واحدة من الباباوب.","zh":"我向小王子指出，猴面包树并非小灌木，相反，它们是像城堡一般巨大的树木；即便他带上一群大象，那群大象也无法吃掉一棵猴面包树。","t":[103,16605]}]},{"id":"ch05p07","audio":"ch05p07.mp3","sents":[{"ar":"هذه الفكرة عن فيلة الأمير الصغير جعلت الأطفال يضحكون.","zh":"那群大象的念头让小王子忍不住笑了。","t":[103,4721]}]},{"id":"ch05p08","audio":"ch05p08.mp3","sents":[{"ar":"عليهم أن يتدرجوا واحداً فوق الآخر.","zh":"它们必须得一个挨一个地叠上去。","t":[103,3168]}]},{"id":"ch05p09","audio":"ch05p09.mp3","sents":[{"ar":"لكن قال كلامًا حكيمًا:","zh":"但他却说了句明智的话：","t":[103,2234]}]},{"id":"ch05p10","audio":"ch05p10.mp3","sents":[{"ar":"قبل أن تنمو كبيرة، تكون شجيرات المونوبيري صغيرة.","zh":"在它们长得太大之前，猴面包树起初只是小小的。","t":[103,4655]}]},{"id":"ch05p11","audio":"ch05p11.mp3","sents":[{"ar":"ذلك تمامًا صحيح.","zh":"那完全正确。","t":[103,2750]},{"ar":"لماذا تُدعِي الغنم إلى أكل شتلات النخيل الصغيرة؟","zh":"可你为何要让羊儿吃掉那些小猴面包树苗呢？","t":[2750,6592]}]},{"id":"ch05p12","audio":"ch05p12.mp3","sents":[{"ar":"إذاً، أجاب مباشرة: \"أوه، أوه، بالتأكيد!\" وكأنه يتحدث عن أمر لا يحتاج إلى تفسير.","zh":"他立刻回答道：“哦，哦，当然啦！”仿佛在谈论一件不言而喻的事。","t":[103,9566]},{"ar":"لابد أن أحل هذه المشكلة بكل جهد، دون أي مساعدة.","zh":"我不得不竭尽全力去解决这个问题，毫无助力。","t":[9566,14513]}]},{"id":"ch05p13","audio":"ch05p13.mp3","sents":[{"ar":"بالطبع، كما أعرف، على كوكب الأمير الصغير - كجميع الكواكب - هناك نباتات صالحة ونباتات سيئة.","zh":"确实，正如我所了解的，小王子居住的星球上——就像所有星球一样——既有好植物也有坏植物。","t":[103,10184]},{"ar":"لذلك، هناك من البذور الصالحة من النباتات الصالحة، ومن البذور السيئة من النباتات السيئة.","zh":"因此，既有来自好植物的良种，也有来自坏植物的恶种。","t":[10184,18961]},{"ar":"البذور غير منظورة.","zh":"种子是看不见的。","t":[18961,21763]},{"ar":"هم في أعماق الظلام على الأرض يغفون حتى يتم استيقاظ رغبة واحدة منهم.","zh":"它们在地球黑暗的深处沉睡，直至其中一颗被唤醒的欲望所攫获。","t":[21763,28289]},{"ar":"هذا البذرة الصغيرة ستقوم بتمديد نفسها، في البداية بتهدئة، وتبدأ في دفع غصين رقيق وجذاب نحو الشمس.","zh":"这颗小小的种子将伸展身躯，起初是胆怯地，开始向上向太阳推送一根迷人的小嫩枝。","t":[28289,38658]},{"ar":"إذا كان مجرد نبتة خيار أو غصن ورد، فتركه ينمو حيث يريد.","zh":"若它只是一株萝卜苗或玫瑰枝，便任其生长，无论它愿往何处。","t":[38658,45461]},{"ar":"لكن إذا كانت نبتة شريرة، يجب أن تُزال حالما تُتعرف عليها، لا يجوز التأخير.","zh":"但若是恶草，一经辨认，便须立即铲除，绝不可拖延。","t":[45461,52671]}]},{"id":"ch05p14","audio":"ch05p14.mp3","sents":[{"ar":"هذه النجمة تنبت فيها بذور مخيفة، وهي بذور الشجرة المونوباد.","zh":"这颗星球上长着可怕的种子，那是猴面包树的种子。","t":[103,6474]},{"ar":"تمتد جذورها فوق الكوكب بأسره","zh":"那颗星球的土壤被它们侵扰。","t":[6474,9197]},{"ar":"إذا كنت تأخرت في ملاحظتها، فإنك لن تستطيع أبدًا التخلص منها","zh":"若你晚些时候才留意，那猴面包树你将永远无法摆脱。","t":[9197,14895]},{"ar":"يغطيها بالكامل","zh":"它覆盖了整个星球。","t":[14895,16224]},{"ar":"تصل إلى أسفله","zh":"根须将它彻底穿透。","t":[16224,17500]},{"ar":"إذا كان الكوكب صغيرًا جدًا، فإنها ستقوم بتمزق الكوكب إلى أجزاء","zh":"若星球太小，而猴面包树太多，它们就会把星球撕裂成碎片。","t":[17500,23723]}]},{"id":"ch05p15","audio":"ch05p15.mp3","sents":[{"ar":"هذا يتعلق بالتحكم الذاتي، قال لي الأمير الصغير لاحقًا","zh":"“这关乎自律，”小王子后来对我说。","t":[103,4695]},{"ar":"بعد أن تنتهي من الاستحمام في الصباح، يجب أن تتحقق من نظافة كوكبك بعناية","zh":"清晨梳洗完毕，便要细心照料你那颗星球的清洁。","t":[4695,11197]},{"ar":"عليك أن تزيلها فورًا عندما تتميز عن نباتات الورد الصغيرة التي تشبهها كثيرًا","zh":"务必在猴面包树与玫瑰花苗初生时难以区分之际，立即将它们连根拔除。","t":[11197,17868]},{"ar":"هذا العمل ممل، لكنه سهل للغاية","zh":"这活儿单调乏味，却也极易完成。","t":[17868,21277]}]},{"id":"ch05p16","audio":"ch05p16.mp3","sents":[{"ar":"لذا في أحد الأيام قال لي: يجب أن ترسم صورة جميلة ليرىها الأطفال الذين يسكنون هناك","zh":"于是有一天他对我说：“你应该画一幅漂亮的画，好让你们那里的孩子们能清楚地看到这一切。”","t":[103,7326]},{"ar":"إذا سافروا في يوم من الأيام، سيكون ذلك مفيدًا لهم","zh":"若他们日后旅行，这将会很有用。","t":[7326,11853]},{"ar":"في بعض الأحيان، يضيفون، يمكن تأجيل العمل إلى يوم آخر","zh":"有时，他补充道，“推迟一件工作到另一天也无妨。","t":[11853,17013]},{"ar":"لكن عندما يتعلق الأمر بالأكاسيا، يكون ذلك كارثة دائمًا","zh":"但若是猴面包树的事，那就总是意味着灾难。","t":[17013,22118]},{"ar":"على كوكب ذلك كان يسكن رجل كسول","zh":"那颗星球上住着一个懒惰的人。","t":[22118,25211]},{"ar":"تجاهل ثلاثة نباتات صغيرة……","zh":"他忽略了三株小灌木……","t":[25211,27736]}]},{"id":"ch05p17","audio":"ch05p17.mp3","sents":[{"ar":"لذا، وفقًا لوصف الأمير الصغير لي، رسمت هذا الكوكب","zh":"于是，按照小王子向我描述的那样，我画下了那颗星球。","t":[103,4826]},{"ar":"لا أحب أن أظهر أنني معلم أخلاقي","zh":"我不喜欢摆出一副道德家的嘴脸。","t":[4826,7826]},{"ar":"ومع ذلك، لا يعلم الناس خطر النخيل، والمخاطر التي تواجه من يضل على الكوكب كبيرة جدًا، لذا أضطرت إلى كسر حيائي","zh":"然而，人们对猴面包树的危害认识不足，而在小行星上迷路的人面临的风险又如此之大，我不得不打破一贯的矜持。","t":[7826,18276]},{"ar":"أطفال، احذروا من شجرة الكرز","zh":"孩子们，当心猴面包树！","t":[18276,21026]}]},{"id":"ch05p18","audio":"ch05p18.mp3","sents":[{"ar":"أصدقائي، مثل أنا، لقد تجنبوا هذا الخطر لفترة طويلة دون أن يدركوا ذلك؛ لذا، من أجلهم، ألخصت الكثير من القلب في هذه الصورة","zh":"朋友们，就像我一样，他们长期以来一直在不知不觉中规避这个危险；因此，为了他们，我才在这幅画上倾注了如此多的心血。","t":[103,11997]},{"ar":"هذا الدرس، رغم أنه استنزفني، يستحق كل هذا العناء","zh":"这教训，虽费尽周折，却值得我付出所有。","t":[11997,16945]}]},{"id":"ch05p19","audio":"ch05p19.mp3","sents":[{"ar":"ربما تسألونني لماذا لم تكن الصور الأخرى في هذا الكتاب مثل رسم النخلة الفريدة والمشوقة؟","zh":"或许你们会问我：“为什么这本书里的其他插画没有这幅猴面包树的画那么雄伟、那么令人印象深刻？”","t":[103,7563]}]},{"id":"ch05p20","audio":"ch05p20.mp3","sents":[{"ar":"الإجابة بسيطة","zh":"答案简单。","t":[103,1550]},{"ar":"لقد حاولت","zh":"我曾尝试。","t":[1550,2405]},{"ar":"لكن لم أحقق نجاحًا في رسم تلك الصور الأخرى","zh":"但画那些其他的画，我并不成功。","t":[2405,5774]},{"ar":"في رسم النخيل، كانت الحاجة الملحة التي دفعتني تجعل قلمي يتجاوز ذاتي","zh":"在绘制猴面包树时，紧迫的需求激励着我，我的画笔超越了自我。","t":[5774,12194]}]}]},{"id":"ch06","title_ar":"الفصل السادس","title_en":"Chapter VI","title_zh":"第 6 章","paras":[{"id":"ch06p00","audio":"ch06p00.mp3","sents":[{"ar":"أوه، الأمير الصغير!","zh":"哦，小王子！","t":[103,3105]},{"ar":"تدريجيًا، تدريجيًا، استطعت أن أفهم سر حياتك الصغيرة الحزينة…","zh":"逐渐地，我逐渐洞悉了你那悲伤的小生活的秘密……","t":[3105,10000]},{"ar":"لقد كنت طويلاً تبحث عن السعادة في هدوء غروب الشمس.","zh":"长久以来，你唯一的乐趣便是在观赏夕阳的宁静中寻找快乐。","t":[10000,15303]},{"ar":"في صباح اليوم الرابع، ذكرت لك هذا التفصيل الجديد:","zh":"第四天清晨，你向我提及了这个新细节：","t":[15303,19448]}]},{"id":"ch06p01","audio":"ch06p01.mp3","sents":[{"ar":"أفضل ما يُظهر غروب الشمس.","zh":"我偏爱那夕阳的余晖。","t":[103,3355]},{"ar":"لنذهب ونشاهد غروب الشمس.","zh":"让我们去看日落吧。","t":[3355,5921]}]},{"id":"ch06p02","audio":"ch06p02.mp3","sents":[{"ar":"لكنني قلت: \"لكن يجب أن ننتظر.\"","zh":"但我道：“然而，我们必须等待。”","t":[103,3366]}]},{"id":"ch06p03","audio":"ch06p03.mp3","sents":[{"ar":"لماذا ننتظر؟","zh":"然而，为何等待？","t":[103,2368]},{"ar":"لماذا ننتظر؟","zh":"为何等待？","t":[2368,3724]}]},{"id":"ch06p04","audio":"ch06p04.mp3","sents":[{"ar":"فقط من أجل غروب الشمس.","zh":"只为那日落。","t":[103,3013]},{"ar":"نحن ننتظر حتى ذلك الوقت.","zh":"我们得等到那时。","t":[3013,5289]}]},{"id":"ch06p05","audio":"ch06p05.mp3","sents":[{"ar":"بدأت بالدهشة الشديدة.","zh":"你起初显得非常惊讶。","t":[103,2947]},{"ar":"ضحكت بذكاء.","zh":"你自嘲地笑了。","t":[2947,5211]},{"ar":"أنت تقول لي:","zh":"你对我说：","t":[5211,6381]}]},{"id":"ch06p06","audio":"ch06p06.mp3","sents":[{"ar":"أعتقد دائمًا أنني في وطني.","zh":"我总以为我是在自己家里呢！","t":[103,2629]}]},{"id":"ch06p07","audio":"ch06p07.mp3","sents":[{"ar":"هذا كل شيء.","zh":"如此而已。","t":[103,2382]},{"ar":"يعلم الجميع، عندما تكون الولايات المتحدة في وسط النهار، تكون فرنسا في غروب الشمس.","zh":"人人皆知，当美国正值正午时分，法国已是夕阳西下。","t":[2382,9724]}]},{"id":"ch06p08","audio":"ch06p08.mp3","sents":[{"ar":"إذا كان بإمكانك الطيران بسرعة إلى فرنسا، يمكنك السفر من منتصف النهار مباشرة إلى غروب الشمس.","zh":"若能瞬间飞往法国，便可从正午直奔日落。","t":[103,9382]},{"ar":"للأسف، فرنسا بعيدة جدًا.","zh":"遗憾的是，法国太远了。","t":[9382,13132]},{"ar":"لكن على كوكبك الصغير، الأُمير الصغير، لا تحتاج إلى سوى تحريك كرسيك خطوات قليلة.","zh":"然而，在你那小小的星球上，小王子，你只需挪动你的椅子几步。","t":[13132,21789]},{"ar":"يمكنك أن تشهد انتهاء النهار وتحل الظلام في أي وقت...","zh":"你随时都能目睹白昼落幕，暮色降临。","t":[21789,26013]}]},{"id":"ch06p09","audio":"ch06p09.mp3","sents":[{"ar":"“يومًا من الأيام，” قلت لك، “رأيت أربعًا وأربعين غروبًا!”","zh":"“有一天，”你对我说，“我看了四十四次日落！”","t":[103,5300]}]},{"id":"ch06p10","audio":"ch06p10.mp3","sents":[{"ar":"كنتُ أضيف بعد ذلك:","zh":"你后来又补充道：","t":[103,1839]}]},{"id":"ch06p11","audio":"ch06p11.mp3","sents":[{"ar":"أنت تعرفـنـا – عندما يكون الإنسان في حالة حزن شديد، يحب أن يشاهد غروب الشمس…","zh":"你深知——当一个人愁绪满怀时，便偏爱那夕阳的余晖……","t":[103,6840]}]},{"id":"ch06p12","audio":"ch06p12.mp3","sents":[{"ar":"كان يومًا، أربعًا وأربعين غروبًا، هل كنت حزينًا؟","zh":"那天，四十四次日落，你如此忧伤吗？","t":[103,4734]}]},{"id":"ch06p13","audio":"ch06p13.mp3","sents":[{"ar":"الأمير الصغير لم يتكلم.","zh":"小王子默然不语。","t":[103,2352]}]}]},{"id":"ch07","title_ar":"الفصل السابع","title_en":"Chapter VII","title_zh":"第 7 章","paras":[{"id":"ch07p00","audio":"ch07p00.mp3","sents":[{"ar":"اليوم الخامس - وكما العادة، شكرًا للخروف - كشف لي سر حياة الأمير الصغير.","zh":"第五天——又像往常一样，多亏了那只绵羊——小王子生活的秘密向我透露了出来。","t":[103,8013]},{"ar":"فجأة اقترح، وكأنه تم استدعاء هذا السؤال بعد فترة طويلة من الصمت العميق.","zh":"他突然提出，仿佛这个问题经过他长时间的沉默深思才诞生出来。","t":[8013,14855]}]},{"id":"ch07p01","audio":"ch07p01.mp3","sents":[{"ar":"الخروف إذا أكل الشجيرات، هل يأكل الزهور أيضًا؟","zh":"绵羊若吃小灌木，也会吃花吗？","t":[103,4445]}]},{"id":"ch07p02","audio":"ch07p02.mp3","sents":[{"ar":"الخروف يأكل كل ما يصادفه.","zh":"绵羊，见什么吃什么。","t":[103,2734]}]},{"id":"ch07p03","audio":"ch07p03.mp3","sents":[{"ar":"هل تأكل الوردة حتى الزهور ذات الشوك؟","zh":"连带刺的花也吃吗？","t":[103,2997]}]},{"id":"ch07p04","audio":"ch07p04.mp3","sents":[{"ar":"نعم، حتى الزهور ذات الشوك.","zh":"是的，连带刺的花也吃。","t":[103,2708]}]},{"id":"ch07p05","audio":"ch07p05.mp3","sents":[{"ar":"ما الفائدة من الأشواك؟","zh":"那刺还有什么用呢？","t":[103,2037]}]},{"id":"ch07p06","audio":"ch07p06.mp3","sents":[{"ar":"لا أعرف السبب.","zh":"我不知其所以然。","t":[103,2289]},{"ar":"كنت مشغولاً في إزالة البرغي العالق في المحرك.","zh":"那时我正忙于拧下卡在发动机里的螺栓。","t":[2289,6803]},{"ar":"أنا أشعر بالقلق لأن عطب طائري يبدو خطيرًا جدًا.","zh":"我深感忧虑，因为我的飞机故障显然极其严重。","t":[6803,11961]},{"ar":"البقية من الماء قليلة جدًا، لا أستطيع إلا أن أتخيل الأسوأ.","zh":"我剩下的饮用水寥寥无几，不禁担忧着最坏的结果。","t":[11961,17513]}]},{"id":"ch07p07","audio":"ch07p07.mp3","sents":[{"ar":"الشوك.. ما الفائدة منها؟","zh":"刺，它们有何用？","t":[103,3171]}]},{"id":"ch07p08","audio":"ch07p08.mp3","sents":[{"ar":"الأمير الصغير إذا سأل، لم يتوانى.","zh":"小王子一旦提问，便锲而不舍。","t":[103,4263]},{"ar":"حولتي، كانت البواسل تزعجني كثيرًا.","zh":"至于我，那螺栓让我心烦意乱。","t":[4263,8750]},{"ar":"أجبت عفوًا:","zh":"我随口答道：","t":[8750,9921]}]},{"id":"ch07p09","audio":"ch07p09.mp3","sents":[{"ar":"الشوك لا فائدة لها.","zh":"刺毫无用处。","t":[103,2829]},{"ar":"الورود تزين نفسها فقط لتعكس الأذى.","zh":"花儿长刺，只为泄愤。","t":[2829,6092]}]},{"id":"ch07p10","audio":"ch07p10.mp3","sents":[{"ar":"أوه!","zh":"哦！","t":[103,629]}]},{"id":"ch07p11","audio":"ch07p11.mp3","sents":[{"ar":"صمت لفترة.","zh":"一时寂静无声。","t":[103,2382]},{"ar":"الأمير الصغير نظر إلي ببعض الحسد، مرتديًا نبرة من الغضب.","zh":"小王子带着一丝怨恨，向我闪过一瞥。","t":[2382,7723]}]},{"id":"ch07p12","audio":"ch07p12.mp3","sents":[{"ar":"لا أؤمن بكلامك!","zh":"我不信你的话！","t":[103,2645]},{"ar":"الورود كائنات ضعيفة.","zh":"花儿是脆弱的生物。","t":[2645,5618]},{"ar":"إنها ساذجة.","zh":"她们天真无邪。","t":[5618,7684]},{"ar":"حاولوا أن يرضوا أنفسهم.","zh":"她们尽力自我安慰。","t":[7684,10711]},{"ar":"…وهي تعتقد بأن أشواكها أسلحة مخيفة…","zh":"它们以为自己的刺是可怕的武器……","t":[10711,14158]}]},{"id":"ch07p13","audio":"ch07p13.mp3","sents":[{"ar":"أصمت.","zh":"我默然不语。","t":[103,1737]},{"ar":"في تلك اللحظة، كنت أقول لنفسي: “إذا لم يزال هذا البرغي معترضًا، سأضربه بالمطرقة.” ثم قاطعني الأمير الصغير من جديد في تفكيري.","zh":"那一刻，我自言自语道：“如果这颗螺栓还是拧不动，我就用锤子把它砸下来。”小王子又一次打断了我在思考。","t":[1737,13119]}]},{"id":"ch07p14","audio":"ch07p14.mp3","sents":[{"ar":"ولكنك تؤمن بالورودـ","zh":"而你竟然相信花儿——","t":[103,2260]}]},{"id":"ch07p15","audio":"ch07p15.mp3","sents":[{"ar":"أوه، لا! أنادي بصوت الدهشة.","zh":"哦，不！我惊呼。","t":[103,4816]},{"ar":"لا، لا، لا!","zh":"不，不，不！","t":[4816,5474]},{"ar":"لا أؤمن بأي شيء.","zh":"我不信任何事。","t":[5474,10171]},{"ar":"بلا تفكير، جاءت إلى ذهني أول فكرة مررت بها.","zh":"随口应道，我脑海中浮现的第一个念头便是答案。","t":[10171,15618]},{"ar":"أنت مشغول بأمور مهمة، لا تملك وقتًا للتفكير في غيرها.","zh":"您忙于正事，无暇他顾。","t":[15618,20868]}]},{"id":"ch07p16","audio":"ch07p16.mp3","sents":[{"ar":"هو نظر إلي، مستغربًا للغاية.","zh":"他瞪着我，惊愕不已。","t":[103,3103]}]},{"id":"ch07p17","audio":"ch07p17.mp3","sents":[{"ar":"أمر خطير!","zh":"事关重大！","t":[103,1169]}]},{"id":"ch07p18","audio":"ch07p18.mp3","sents":[{"ar":"هو ينظر إلي، يُمسك بمطرقة، أصابعي مغطاة بزيت المحرك، ينحني أمام شيء بيداه يبدو... قبيحًا جدًا.","zh":"他瞧着我，手里握着锤子，指头沾满了发动机的机油，俯身对着在他看来极其丑陋的物件。","t":[103,11013]}]},{"id":"ch07p19","audio":"ch07p19.mp3","sents":[{"ar":"تتحدث مثل الكبار تمامًا","zh":"你说话就像大人一样！","t":[103,2405]}]},{"id":"ch07p20","audio":"ch07p20.mp3","sents":[{"ar":"هذا جعلني أشعر بالخجل.","zh":"这让我感到有些羞愧。","t":[103,3395]},{"ar":"لكن استمر في الحديث، دون تردد.","zh":"但他却继续说，毫不留情。","t":[3395,6316]}]},{"id":"ch07p21","audio":"ch07p21.mp3","sents":[{"ar":"أنت تُمزج كل شيء معًا...","zh":"你把一切都搅和在一起……","t":[103,3263]},{"ar":"أنتُ تُدمجُ كل شيء في بعضه البعض...","zh":"你把一切都混为一谈……","t":[3263,6079]}]},{"id":"ch07p22","audio":"ch07p22.mp3","sents":[{"ar":"هو غضب جدًا","zh":"他真的非常生气。","t":[103,1313]},{"ar":"شعره الذهبي المنحني يطير في الهواء","zh":"他金黄色的卷发在风中飘扬。","t":[1313,4260]}]},{"id":"ch07p23","audio":"ch07p23.mp3","sents":[{"ar":"أعلم أن هناك كوكبًا يسكنه سيد ذو وجه أحمر.","zh":"我知道有一个星球上住着一位红脸先生。","t":[103,5145]},{"ar":"لم يكن قد شم وردة واحدة.","zh":"他未曾嗅过一瓣花。","t":[5145,8513]},{"ar":"لم يكن يرفع نظرًا إلى نجمة.","zh":"他从未仰望过一颗星星。","t":[8513,12000]},{"ar":"لم يكن يحب أحدًا.","zh":"他从未爱过任何人。","t":[12000,14750]},{"ar":"يضيف فقط طوال حياته.","zh":"他一生只做加法。","t":[14750,17671]},{"ar":"كان يتردد في قوله، كما أنت: \"أنا مشغول بأمور مهمة!\" مما جعله فخورًا ويملأ نفسه الفخر.","zh":"他整天反复说着，就像你一样：“我正忙于要紧的事！”这让他骄傲得膨胀起来。","t":[17671,27316]},{"ar":"لكنه ليس إنسانًا عاديًا - إنه مجرد فطر!","zh":"但他并非凡人——他只是一朵蘑菇！","t":[27316,31474]}]},{"id":"ch07p24","audio":"ch07p24.mp3","sents":[{"ar":"ما هذا؟","zh":"“这是什么？”","t":[103,905]}]},{"id":"ch07p25","audio":"ch07p25.mp3","sents":[{"ar":"الطقوس!","zh":"蘑菇！","t":[103,879]}]},{"id":"ch07p26","audio":"ch07p26.mp3","sents":[{"ar":"الأمير الصغير غضب وأصبح لونه أبيض كالثلج.","zh":"小王子气得脸色煞白。","t":[103,3944]}]},{"id":"ch07p27","audio":"ch07p27.mp3","sents":[{"ar":"الورود قد نمت الشوك منذ ملايين السنين.","zh":"花儿已长刺数百万年。","t":[103,4250]},{"ar":"لأكثر من مليون سنة، يأكل الخروف بهذه الطريقة.","zh":"数百万年来，绵羊一直这样吃着它们。","t":[4250,9500]},{"ar":"لماذا تضيف الزهور عناء زراعة شوك لا فائدة لها، هذا ليس أمرًا مهمًا؟","zh":"探究为何花儿费尽心机长出无用的刺，这难道不是一件重要的事吗？","t":[9500,16803]},{"ar":"هل حرب الغنم على الزهور ليست مهمة؟","zh":"羊与花的战争难道不重要吗？","t":[16803,20658]},{"ar":"هل هذا ليس أكثر أهمية من حسابات السيد ذو الوجه الأحمر؟","zh":"这难道不是比那位红脸胖子的算术更重要吗？","t":[20658,26263]},{"ar":"أوه! لو كنت أعلم- أنا نفسى- أن هناك زهرة فريدة في العالم، تنمو فقط على كوكبي، وغنم صغير يمكن أن يلتهمها في صباح ما دون أن يدرك ما يفعلها...","zh":"哦！若我深知——我自己——世间仅此一朵独一无二的花，它只生长在我的星球，而一只小小的绵羊却能在某个清晨不经意间将它一口吞噬，甚至未曾察觉自己的行为——哦！","t":[26263,41829]},{"ar":"هل هذا ليس مهمًا؟","zh":"这难道不重要吗？","t":[41829,43566]}]},{"id":"ch07p28","audio":"ch07p28.mp3","sents":[{"ar":"لقد تحول لون وجهه من الأبيض إلى الأحمر، واستمر في قوله:","zh":"他的脸色由白转红，继续说道：","t":[103,5011]}]},{"id":"ch07p29","audio":"ch07p29.mp3","sents":[{"ar":"إذا أحب شخص ما زهرة تنمو في بين مليارات النجوم، فقط بالنظر إلى السماء يمكن أن يجعله سعيدًا...","zh":"若有人爱上了一朵生长在亿万星辰中的一朵花，只需仰望星空，便足以使他心满意足。","t":[103,9368]},{"ar":"يمكنه أن يقول لنفسه: 'زهري هناك في الخارج...' لكن إذا أكل الغنم الزهرة، ستتحول كل النجوم فجأة إلى مظلمة...","zh":"他可以对自己说：“我的花儿在那儿……”但若绵羊吃掉了那朵花，他的所有星星在一瞬间都将黯淡无光……","t":[9368,20934]},{"ar":"هل هذا ليس مهمًا؟ لم يستطع أن يستمر في الكلام لأن الدموع غلبته.","zh":"这难道不重要吗？他再也无法说下去了。","t":[20934,28316]},{"ar":"كلماته كانت محبوسة بين نوبة من البكاء.","zh":"他的话语被抽泣所哽咽。","t":[28316,32106]}]},{"id":"ch07p30","audio":"ch07p30.mp3","sents":[{"ar":"لقد حل الليل.","zh":"夜幕降临。","t":[103,2329]},{"ar":"ألقيت أدواتي في الأرض.","zh":"我手中的工具纷纷落地。","t":[2329,4974]},{"ar":"المدافع، البراغي، العطش أو الموت، الآن بالنسبة لي ما هو من أي شيء؟","zh":"我的锤子、螺栓、干渴或死亡，此刻又算得了什么？","t":[4974,12803]},{"ar":"في الأرض، كوكبي، هناك أمير صغير يحتاج إلى التهدئة.","zh":"在地球，我的星球上，有一个小王子需要安慰。","t":[12803,18789]},{"ar":"أنا أحمله في يدي، وأجعله يتأرجح بلطف.","zh":"将他紧紧抱在怀里，轻轻摇晃着他。","t":[18789,23789]},{"ar":"أنا أقول له:","zh":"我对他说：","t":[23789,24802]}]},{"id":"ch07p31","audio":"ch07p31.mp3","sents":[{"ar":"الزهرة التي تحبها ليست في خطر.","zh":"你爱的那朵花并无危险。","t":[103,3895]},{"ar":"سأرسم لغنمك كمامة.","zh":"我给你那绵羊画个口罩。","t":[3895,6829]},{"ar":"سأرسم لزهرك سياجًا.","zh":"我为你那朵花画一道栅栏。","t":[6829,9908]},{"ar":"سأقوم بـ","zh":"我将——","t":[9908,10842]}]},{"id":"ch07p32","audio":"ch07p32.mp3","sents":[{"ar":"لا أعلم كيف أتحدث معه.","zh":"我不知该如何向他开口。","t":[103,3303]},{"ar":"أشعر بالارتباك والخجل.","zh":"我感到尴尬而笨拙。","t":[3303,6395]},{"ar":"لا أعلم كيف ألحق به، أين أستطيع أن ألاقيه، وأعاد أن أكون معه.","zh":"我不知如何才能追上他，在哪里才能与他并肩前行，再次携手同行。","t":[6395,12158]}]},{"id":"ch07p33","audio":"ch07p33.mp3","sents":[{"ar":"مملكة الدموع هي غامضة جدًا.","zh":"泪水的王国，如此神秘。","t":[103,2800]}]}]},{"id":"ch08","title_ar":"الفصل الثامن","title_en":"Chapter VIII","title_zh":"第 8 章","paras":[{"id":"ch08p00","audio":"ch08p00.mp3","sents":[{"ar":"أسرعت في فهم هذه الزهرة بشكل أعمق.","zh":"我很快便更深入地了解了这朵花。","t":[103,4211]},{"ar":"الأمير الصغير، في كوكبه، الزهور دائمًا بسيطة جدًا.","zh":"小王子的星球上，花朵总是极为朴素。","t":[4211,10276]},{"ar":"البتلات حلقة واحدة، لا تشغل مكانًا، ولا تؤذي الأتراب.","zh":"花瓣仅一环，不占空间，不惹尘埃。","t":[10276,16618]},{"ar":"في الصباح تبرق في الحشيش، وفي الليل تهدأ لتزول.","zh":"清晨它们在草间绽放，夜晚便平静地凋谢。","t":[16618,21803]},{"ar":"ومع ذلك، في يوم من الأيام، نبتت بذرة من مكان لا يعرف أحد عنه؛ الأمير الصغير كان يتابع عن قرب الشتلة التي لا تشبه أي شتلة أخرى على كوكبه.","zh":"然而，一天，一朵来自无人知晓之处的种子发芽了；小王子密切地关注着这株与众不同的嫩芽，它不同于他星球上其他任何嫩芽。","t":[21803,35855]},{"ar":"ربما، قد يكون نوعاً جديداً من شجرة البابايا.","zh":"或许，它可能是一种新型的猴面包树。","t":[35855,39869]}]},{"id":"ch08p01","audio":"ch08p01.mp3","sents":[{"ar":"الشجيرة سرعان ما توقفت عن النمو وبدأت في إعداد الإزهار.","zh":"灌木很快停止了生长，开始准备绽放花朵。","t":[103,6000]},{"ar":"الولد الصغير رأى الشجرة الكبيرة ووقع في حيرة من أمره لما سيؤول إليه ذلك من رؤية معجزة","zh":"小王子目睹那硕大的花蕾初现，便预感其中将诞生某种奇迹般的景象。","t":[6000,13763]},{"ar":"لكن الزهرة لم تكن راضية بأن تنهي تحضيرها الجميل فقط تحت سقف البيت الأخضر.","zh":"但那朵花并不满足于只在绿屋的庇护下完成她美丽的准备。","t":[13763,21066]},{"ar":"تختار ألوانها بعناية فائقة.","zh":"她挑选色彩极是用心。","t":[21066,24500]},{"ar":"تعدل الأوراق واحدة تلو الأخرى.","zh":"她逐一调整着花瓣。","t":[24500,28171]},{"ar":"لا تريد أن تكون مثل الزهرة البرية، تتدخل إلى العالم متشوهة.","zh":"她不愿像野罂粟花那样，皱巴巴地闯进世界。","t":[28171,34724]},{"ar":"تظهر فقط في أقصى جمالها الإزهار.","zh":"她只愿在美丽绽放的极致中露面。","t":[34724,38382]},{"ar":"أوه نعم!","zh":"哦，是的！","t":[38382,40276]},{"ar":"هي مخلوقة تحب الجمال.","zh":"她是个爱美的生灵。","t":[40276,43382]},{"ar":"تتواصل مأساتها الغامضة لعدة أيام.","zh":"她的神秘装扮持续了好多天。","t":[43382,46750]}]},{"id":"ch08p02","audio":"ch08p02.mp3","sents":[{"ar":"في صباح يوم، عند شروق الشمس، ظهرت فجأة.","zh":"就在一个清晨，正逢日出时分，她突然现身。","t":[103,4234]}]},{"id":"ch08p03","audio":"ch08p03.mp3","sents":[{"ar":"بعد هذا الجهد العظيم في التزيين، ابتسمت وأطلقت عطسة قائلة:","zh":"经过这番苦心孤诣的精心打扮，她打了个哈欠说道：","t":[103,5366]}]},{"id":"ch08p04","audio":"ch08p04.mp3","sents":[{"ar":"أوه!","zh":"唉！","t":[103,1526]},{"ar":"أنا قد استيقظت، ما زلت غارقاً في الغموض.","zh":"我刚刚醒来，尚感朦胧。","t":[1526,6211]},{"ar":"من فضلكم أغفروا لي جريتي.","zh":"请您原谅我的冒昧。","t":[6211,9434]},{"ar":"أوراقي مازالت في فوضى...","zh":"我的花瓣仍凌乱不堪……","t":[9434,11316]}]},{"id":"ch08p05","audio":"ch08p05.mp3","sents":[{"ar":"الأمير الصغير لم يملك من نفسه إلا أن يبتهج:","zh":"小王子忍不住赞叹：","t":[103,3826]}]},{"id":"ch08p06","audio":"ch08p06.mp3","sents":[{"ar":"أوه!","zh":"哦！","t":[103,1526]},{"ar":"يا لجمالك!","zh":"您真美啊！","t":[1526,2632]}]},{"id":"ch08p07","audio":"ch08p07.mp3","sents":[{"ar":"نعم، قالت الزهرة بحنان.","zh":"“是啊，”花儿柔声回应。","t":[103,3684]},{"ar":"أنا ولدت في نفس اليوم الذي أشرق فيه الشمس.","zh":"我与太阳同日而生。","t":[3684,7197]}]},{"id":"ch08p08","audio":"ch08p08.mp3","sents":[{"ar":"الأمير الصغير لم يكاد يرى أنها متواضعة على الإطلاق - ولكنها كانت رائعة - كانت مثيرة للغاية!","zh":"小王子不难看出她并不怎么谦逊——然而她是多么动人——多么令人兴奋！","t":[103,8405]}]},{"id":"ch08p09","audio":"ch08p09.mp3","sents":[{"ar":"تضيف وهي تلمح إلى أشواكها الأربعة: \"الآن هو وقت تناول الإفطار.\"","zh":"她随即又补充道：“现在是吃早餐的时候了。”","t":[103,5826]},{"ar":"إذاً كان يمكنني أن أتفهم احتياجاتك","zh":"若您能体谅我的所需——","t":[5826,9116]}]},{"id":"ch08p10","audio":"ch08p10.mp3","sents":[{"ar":"الأمير الصغير شعر بالخجل، فذهب ليجد قدحًا من الماء العذب.","zh":"小王子羞愧难当，去找一壶清水。","t":[103,6303]},{"ar":"ثم، كان يعتني بالوردة.","zh":"于是，他照料着这朵花。","t":[6303,8829]}]},{"id":"ch08p11","audio":"ch08p11.mp3","sents":[{"ar":"ثم، بدأت بسرعة تؤذيه بغرورها الشديد – إن كشف الحقيقة كان أمرًا يصعب التعامل معه.","zh":"于是，她很快便开始用她的虚荣心折磨他——若真相大白，这实在有些难以应对。","t":[103,8842]},{"ar":"يومًا ما، عندما تحدثت عن الشوك الأربعة، قالت للأمير الصغير:","zh":"有一天，当她谈到她那四根刺时，她对小王子说：","t":[8842,14263]}]},{"id":"ch08p12","audio":"ch08p12.mp3","sents":[{"ar":"دع التنانين تأتي برؤوسها المعدنية!","zh":"让老虎带着它们的爪子来吧！","t":[103,3063]}]},{"id":"ch08p13","audio":"ch08p13.mp3","sents":[{"ar":"ليس هناك أسد على كوكبي.","zh":"我的星球上没有老虎。","t":[103,3395]},{"ar":"الأسد لا يأكل الأعشاب.","zh":"老虎不吃杂草。","t":[3395,5421]}]},{"id":"ch08p14","audio":"ch08p14.mp3","sents":[{"ar":"أنا لست نباتًا مزروعًا.","zh":"“我不是杂草。”花儿柔声回答。","t":[103,2155]}]},{"id":"ch08p15","audio":"ch08p15.mp3","sents":[{"ar":"أعذروني...","zh":"请原谅……","t":[103,971]}]},{"id":"ch08p16","audio":"ch08p16.mp3","sents":[{"ar":"أنا لا أخاف الأسود، لكنني أخاف الرياح العاتية.","zh":"“我对老虎毫不畏惧，却最怕穿堂风。”","t":[103,5079]},{"ar":"هل لديك سجادة؟","zh":"您这儿有屏风吗？","t":[5079,6527]}]},{"id":"ch08p17","audio":"ch08p17.mp3","sents":[{"ar":"\"يخاف من الرياح العابرة هذا - هذا يعتبر مصيرًا حزينًا للنباتات،\" قال الأمير الصغير، متفكيرًا في نفسه، \"هذه الزهرة كائن معقد جدًا...\"","zh":"“对穿堂风如此恐惧——这对植物来说可真是不幸，”小王子评论道，心中暗想，“这朵花真是个复杂的生物……”","t":[103,12313]}]},{"id":"ch08p18","audio":"ch08p18.mp3","sents":[{"ar":"ليلةً، أرجو أن تُغطيني بالكرة الزجاجية.","zh":"夜晚，请您把我罩在玻璃球里。","t":[103,4632]},{"ar":"المكان الذي تسكن فيه بارد جدًا.","zh":"你住的地方非常寒冷。","t":[4632,8526]},{"ar":"في المكان الذي أتيت منه","zh":"在我来的那个地方——","t":[8526,10566]}]},{"id":"ch08p19","audio":"ch08p19.mp3","sents":[{"ar":"لم تُكمل كلماتُها حتى توقفت.","zh":"她话未说完便打住了。","t":[103,3855]},{"ar":"تُنزل كبذرة.","zh":"她以种子的形式降临。","t":[3855,6053]},{"ar":"لا يمكنها فهم أي عالم آخر.","zh":"她不可能了解任何其他世界。","t":[6053,9566]},{"ar":"أشعر بالخزي من أنني وقعت في مثل هذا الخداع اللامبالاة، قالت ببكاء قليل، محاولة أن تلقي اللوم على الأمير الصغير.","zh":"羞愧于让自己陷入如此幼稚谎言的边缘，她咳嗽了两三声，企图让小王子承担过错。","t":[9566,19171]}]},{"id":"ch08p20","audio":"ch08p20.mp3","sents":[{"ar":"هل لديك شاشة؟","zh":"您有屏风吗？","t":[103,1445]}]},{"id":"ch08p21","audio":"ch08p21.mp3","sents":[{"ar":"أنا كنت أحتاج إلى الذهاب، لكن أنت الذي تحدثت إليّ……","zh":"我正要去找，是你和我说话的呀……","t":[103,4918]}]},{"id":"ch08p22","audio":"ch08p22.mp3","sents":[{"ar":"تُعطِي نفسها سعالًا أشد، ليجد هو الشعور بالذنب.","zh":"她故意咳嗽得更重，让他也感到内疚。","t":[103,4379]}]},{"id":"ch08p23","audio":"ch08p23.mp3","sents":[{"ar":"على الرغم من أن الأمل الصغير كان يحمل حباً طيباً نحوه، إلا أنه بدأ يتساءل عنها قريباً.","zh":"尽管小王子对她的爱中充满了善意，但他很快便开始怀疑她了。","t":[103,8316]},{"ar":"يأخذ في الاعتبار الكلام العديم الأهمية، مما يجعله غير سعيد بشكل كبير.","zh":"他认真对待了无关紧要的话语，这让他非常不快乐。","t":[8316,14776]}]},{"id":"ch08p24","audio":"ch08p24.mp3","sents":[{"ar":"لم أكن ينبغي أن أستمع إليها في ذلك اليوم.","zh":"我那天不该听她的话。","t":[103,4645]},{"ar":"لا تؤمنوا أبداً بما تقوله الزهور.","zh":"永远也别信花儿讲的话。","t":[4645,8461]},{"ar":"فقط بنظرة إليها، وبتذوق رائحتها","zh":"只需凝视它们，感受它们的芬芳。","t":[8461,12118]},{"ar":"كوكبي ينتشر من حوله رائحة الزهور","zh":"我的星球上弥漫着花香。","t":[12118,15066]},{"ar":"لكنني لا أعرف كيف أستفيد من جمالها","zh":"但我不知如何享受她的所有优雅。","t":[15066,18039]},{"ar":"قصة المخالب هذه، يجب أن تثير في قلبي فقط رقة وحنان","zh":"这关于爪子的故事，本应只在我心中激起温柔与怜悯。","t":[18039,23513]}]},{"id":"ch08p25","audio":"ch08p25.mp3","sents":[{"ar":"وكان يستمر في حديثه","zh":"他继续倾诉着。","t":[103,2076]}]},{"id":"ch08p26","audio":"ch08p26.mp3","sents":[{"ar":"في الحقيقة، لا أستطيع فهم أي شيء","zh":"事实上，我并不懂得如何理解任何事物！","t":[103,3076]},{"ar":"يجب أن نحكم بالأفعال وليس بالكلمات","zh":"应凭行为而非言语来评判。","t":[3076,6418]},{"ar":"رائحتها ولمعتها تملأني","zh":"她的芬芳与光辉洒落在我身上。","t":[6418,8839]},{"ar":"لم يكن عليّ الهروب منها","zh":"我本不该逃离她……","t":[8839,10616]},{"ar":"كان يجب أن أفهمها، وراء تلك الخدع الصغيرة التي تضحك","zh":"我本应猜透她那可怜的小伎俩背后深藏的柔情。","t":[10616,15355]},{"ar":"الزهور غير مستقرة","zh":"花儿真是反复无常！","t":[15355,17026]},{"ar":"في ذلك الوقت، كنت صغيرًا جدًا، لا أعرف كيف أحب","zh":"那时我还太年轻，不懂如何去爱她……","t":[17026,21803]}]}]},{"id":"ch09","title_ar":"الفصل التاسع","title_en":"Chapter IX","title_zh":"第 9 章","paras":[{"id":"ch09p00","audio":"ch09p00.mp3","sents":[{"ar":"ربما استغل هجرة الطيور البرية للهروب.","zh":"他可能是趁着那群野鸟迁徙之际逃离的。","t":[103,4408]},{"ar":"كان يرتب كوكبه بتنظيم دقيق في صباح رحيله.","zh":"他离开那天早晨，把他的星球整理得井井有条。","t":[4408,9447]},{"ar":"يُنظف هو براكينه النشطة بعناية.","zh":"他仔细清理了他的活火山。","t":[9447,13474]},{"ar":"كان لديه بركانين نشطين، مما يجعل طهي وجبة الإفطار في الصباح سهلاً للغاية.","zh":"他拥有两座活火山，早晨煮早餐极为方便。","t":[13474,20974]},{"ar":"كان لديه بركانًا منتهيًا بالفعالية.","zh":"他还拥有一座熄灭的火山。","t":[20974,25013]},{"ar":"ومع ذلك، كما قال: \"الأمور غير متوقعة!\" فأزال هو أيضًا جسم ذلك البركان الميت.","zh":"然而，正如他所说：“世事难料！”于是，他也清理了那座死火山。","t":[25013,33882]},{"ar":"البراكين إذا ما نُظفت جيدًا، فإنها تتوقد بلطف وانتظام، من دون أي انفجارات.","zh":"火山清理得当，火焰便缓缓而稳定地燃烧，不会喷发。","t":[33882,42197]},{"ar":"البراكين تنفجر كنيران المدفأة.","zh":"火山喷发犹如烟囱中的火焰。","t":[42197,45171]}]},{"id":"ch09p01","audio":"ch09p01.mp3","sents":[{"ar":"في أرضنا، نحن بالطبع صغار جدًا لنتنظف بركاناتنا.","zh":"在我们地球上，我们显然太小了，无法清理我们的火山。","t":[103,5961]},{"ar":"هذا هو السبب في أنهم يسببون لنا أمراض لا نهائية.","zh":"这便是它们给我们带来无尽烦恼的原因。","t":[5961,10315]}]},{"id":"ch09p02","audio":"ch09p02.mp3","sents":[{"ar":"الأمير الصغير أزال بقليل من الحزن آخر نباتات البابايا.","zh":"小王子带着一丝沮丧，拔除了最后几株猴面包树苗。","t":[103,5711]},{"ar":"هو يؤمن بأنه لن يودعني مرة أخرى.","zh":"他坚信自己不会再想回来。","t":[5711,9882]},{"ar":"ومع ذلك، في هذا الصباح الأخير، أصبحت جميع هذه المهام المألوفة غير العادية قيمة بالنسبة له.","zh":"然而，在这最后的早晨，所有这些熟悉的任务在他看来都变得异常珍贵。","t":[9882,19224]},{"ar":"للمرة الأخيرة، سقي الزهرة وأعدت غطاءها الزجاجي، وعرفت أنني على وشك أن أذرف الدموع.","zh":"最后一次为花儿浇水，准备给她罩上玻璃罩，他意识到自己几乎要泪流满面了。","t":[19224,27132]}]},{"id":"ch09p03","audio":"ch09p03.mp3","sents":[{"ar":"وداعاً، قال للأمير الصغير.","zh":"再见，他对花儿说。","t":[103,2760]}]},{"id":"ch09p04","audio":"ch09p04.mp3","sents":[{"ar":"تأملت الصمت.","zh":"她默然不语。","t":[103,1327]}]},{"id":"ch09p05","audio":"ch09p05.mp3","sents":[{"ar":"وداعاً، قال مرة أخرى.","zh":"再见，他又说。","t":[103,2510]}]},{"id":"ch09p06","audio":"ch09p06.mp3","sents":[{"ar":"الوردة تسعل.","zh":"花儿轻咳。","t":[103,2434]},{"ar":"لكن ليس لأنها مصابة بالبرد.","zh":"但并非因为她感冒了。","t":[2434,5171]}]},{"id":"ch09p07","audio":"ch09p07.mp3","sents":[{"ar":"لقد قالت له أخيرًا: \"أنا مجنونة حقًا.\"","zh":"她终于对他说：“我真是愚蠢。”","t":[103,3826]},{"ar":"أعذروني.","zh":"请原谅我。","t":[3826,5684]},{"ar":"حاول أن تكون سعيدًا...","zh":"试着快乐吧……","t":[5684,7513]}]},{"id":"ch09p08","audio":"ch09p08.mp3","sents":[{"ar":"لم تكن تنتقد رحيله.","zh":"她对他的离去毫无责怪。","t":[103,3026]},{"ar":"كان يتأمل هناك، غطاء الزجاج في الهواء يرتفع معه.","zh":"他愣愣地站在那里，手中的玻璃罩悬停在半空。","t":[3026,8553]},{"ar":"لم يفهم هذه العذوبة الهادئة.","zh":"他不懂这宁静的甜美。","t":[8553,10908]}]},{"id":"ch09p09","audio":"ch09p09.mp3","sents":[{"ar":"بالطبع، أحبك.","zh":"当然，我爱你。","t":[103,2697]},{"ar":"لم تكن تدرك أن هذا كله خطأي.","zh":"你一直未曾察觉到，这全是我的过错。","t":[2697,6579]},{"ar":"ذلك لا يهم.","zh":"那无关紧要。","t":[6579,8855]},{"ar":"لكن أنتـكـ أيضًا، أنتـكـ أيضًا غبي مثلي.","zh":"但你——你也和我一样傻。","t":[8855,13513]},{"ar":"حاول أن تكون سعيدًا...","zh":"试着快乐吧……","t":[13513,16250]},{"ar":"دع قبة الزجاج ترتجي في الهواء.","zh":"让玻璃罩见鬼去吧。","t":[16250,19855]},{"ar":"لست بحاجة إليها بعد الآن.","zh":"我不再需要它了。","t":[19855,22263]}]},{"id":"ch09p10","audio":"ch09p10.mp3","sents":[{"ar":"لكن الريح...","zh":"但风……","t":[103,1248]}]},{"id":"ch09p11","audio":"ch09p11.mp3","sents":[{"ar":"لم أكن مصابًا بالبرد بشدة...","zh":"我的感冒并没有那么严重……","t":[103,3474]},{"ar":"الريح الليلية الصافية مفيدة جدًا لي.","zh":"清新的夜风对我大有裨益。","t":[3474,7513]},{"ar":"أنا وردة.","zh":"我是一朵花。","t":[7513,8513]}]},{"id":"ch09p12","audio":"ch09p12.mp3","sents":[{"ar":"لكن تلك الحيوانات","zh":"但那些动物——","t":[103,2089]}]},{"id":"ch09p13","audio":"ch09p13.mp3","sents":[{"ar":"أريد أن ألتقي بالفراشات، فأحتاج إلى تحمل بعض اليرقات.","zh":"我若想结识蝴蝶，就得忍受两三条毛虫的陪伴。","t":[103,6303]},{"ar":"يبدو أنها جميلة جدًا.","zh":"它们似乎非常美丽。","t":[6303,9368]},{"ar":"ما الذي يجعل الحشرات الصغيرة تأتي لزيارتني إذا لم تأتي الفراشات؟","zh":"蝴蝶不来，毛虫又何来拜访我呢？","t":[9368,15566]},{"ar":"ستغادر...","zh":"你将远行……","t":[15566,17474]},{"ar":"حولًا إلى الحيوانات الكبيرة - لا أخافها على الإطلاق.","zh":"至于大动物——我一点也不怕它们。","t":[17474,22566]},{"ar":"لدي مخلصتي.","zh":"我有我的爪子。","t":[22566,24092]}]},{"id":"ch09p14","audio":"ch09p14.mp3","sents":[{"ar":"توسلت ببراءة بأربعة شوكها.","zh":"她天真地伸出她的四根刺。","t":[103,3750]},{"ar":"تستمر في القول:","zh":"她接着说：","t":[3750,5184]}]},{"id":"ch09p15","audio":"ch09p15.mp3","sents":[{"ar":"لا تكن هكذا متأخرًا.","zh":"别这样拖延。","t":[103,3158]},{"ar":"لقد قررت الرحيل.","zh":"你已决定离去。","t":[3158,5658]},{"ar":"اذهبوا.","zh":"那就走吧。","t":[5658,6369]}]},{"id":"ch09p16","audio":"ch09p16.mp3","sents":[{"ar":"تُريدُ ألا يرى فيها بكاءً.","zh":"她不愿让他看到自己哭泣。","t":[103,3197]},{"ar":"هي زهرة فاخرة جدًا...","zh":"她是一朵多么骄傲的花儿……","t":[3197,5342]}]}]},{"id":"ch10","title_ar":"الفصل العاشر","title_en":"Chapter X","title_zh":"第 10 章","paras":[{"id":"ch10p00","audio":"ch10p00.mp3","sents":[{"ar":"وجد نفسه في منطقة كواكب 325، 326، 327، 328، 329، 330.","zh":"他发现自己来到了小行星325号、326号、327号、328号、329号和330号所在的地区。","t":[103,20526]},{"ar":"ثم بدأ يزورها جميعًا ليزيد من معرفته.","zh":"于是他开始逐一拜访，以增长见识。","t":[20526,21026]}]},{"id":"ch10p01","audio":"ch10p01.mp3","sents":[{"ar":"على ذلك الكوكب عاش ملك.","zh":"那颗星球上住着一位国王。","t":[103,3263]},{"ar":"لبس ثوبًا ملكيًا أرجوانيًا وفراء القواقم، جلس على عرش بسيط وعظيم.","zh":"身着皇家紫袍与貂皮，他端坐在既简单又威严的宝座上。","t":[3263,10053]}]},{"id":"ch10p02","audio":"ch10p02.mp3","sents":[{"ar":"أوه!","zh":"啊！","t":[103,1526]},{"ar":"\"جاء أحد الرعايا،\" قال الملك وهو يرى الأمير الصغير يأتي.","zh":"“来了一位臣民，”国王看见小王子走来，大声说道。","t":[1526,6290]}]},{"id":"ch10p03","audio":"ch10p03.mp3","sents":[{"ar":"الأمير الصغير يستغرب:","zh":"小王子自问：","t":[103,2064]}]},{"id":"ch10p04","audio":"ch10p04.mp3","sents":[{"ar":"لم يره قط كيف يمكنه التعرف علي؟","zh":"他从未见过我，怎能认出我呢？","t":[103,3326]}]},{"id":"ch10p05","audio":"ch10p05.mp3","sents":[{"ar":"في عيون الملوك، يصبح العالم بسيطًا.","zh":"国王们眼中，世界变得简单了。","t":[103,4434]},{"ar":"في نظرهم، العالم كله مملوك لهم.","zh":"在他们眼中，世人皆为臣民。","t":[4434,7974]}]},{"id":"ch10p06","audio":"ch10p06.mp3","sents":[{"ar":"“اقترب قليلاً، لأتمكن من النظر إليك بشكل أفضل،” قال الملك وهو يشعر بالفخر الشديد لكونه أخيرًا ملكًا لشخص ما.","zh":"“走近些，让我好好端详你，”国王说，他因终于统治了某个臣民而感到无比自豪。","t":[103,10143]}]},{"id":"ch10p07","audio":"ch10p07.mp3","sents":[{"ar":"الأمير الصغير نظر حوله يبحث عن مكان للجلوس، ولكن كله كان مغطى بثوب الملك الفاخر من الفرو.","zh":"小王子环顾四周，寻找可坐之处；但整个星球已被国王那华丽的貂皮袍子塞满，无处下脚。","t":[103,9368]},{"ar":"استقام وأقف، وعلى أثر التعب، عطس.","zh":"他挺直了身子站立，由于疲惫，他打了个哈欠。","t":[9368,13237]}]},{"id":"ch10p08","audio":"ch10p08.mp3","sents":[{"ar":"التثاؤب أمام الملك يعد أمرًا غير لائق.","zh":"在国王面前打哈欠，有失礼节。","t":[103,4513]},{"ar":"أمنعك من ذلك.","zh":"我禁止你这么做。","t":[4513,5974]}]},{"id":"ch10p09","audio":"ch10p09.mp3","sents":[{"ar":"لا أستطيع المقاومة.","zh":"我忍不住了。","t":[103,2724]},{"ar":"لا أستطيع المقاومة، قال الأمير الصغير وأحمر وجهه.","zh":"我忍不住了，小王子回答说，满脸尴尬。","t":[2724,8013]},{"ar":"لقد سافرت مسافات طويلة ولم أنم قط...","zh":"我长途跋涉，未曾合眼……","t":[8013,11316]}]},{"id":"ch10p10","audio":"ch10p10.mp3","sents":[{"ar":"أه، إذن يقول الملك.","zh":"啊，那么，国王说。","t":[103,2974]},{"ar":"أمرتك بالتثاؤب.","zh":"我命令你打哈欠。","t":[2974,5447]},{"ar":"لم أر أحدًا يُثاءب منذ سنوات.","zh":"多年来未见有人打哈欠了。","t":[5447,9039]},{"ar":"هيأ نفسه أمر غريب في عيني.","zh":"打哈欠在我眼里是件稀奇事。","t":[9039,12671]},{"ar":"سرعًا!","zh":"快点儿！","t":[12671,14276]},{"ar":"هيا، قم بالسعال مرة أخرى!","zh":"再打一个哈欠！","t":[14276,17724]},{"ar":"هذه أمر.","zh":"这是命令。","t":[17724,18829]}]},{"id":"ch10p11","audio":"ch10p11.mp3","sents":[{"ar":"...أخافني ذلك...","zh":"这让我害怕……","t":[103,2289]},{"ar":"لا أستطيع… الأمير الصغير يتحدث بخجل.","zh":"我无法再……小王子羞愧地低语。","t":[2289,6895]}]},{"id":"ch10p12","audio":"ch10p12.mp3","sents":[{"ar":"هف!","zh":"哼！","t":[103,1303]},{"ar":"فهم الملك وأجاب: هه!","zh":"哼！国王答道。","t":[1303,4658]},{"ar":"إذًا، أمرتك أحياناً بالتثاؤب، وأحياناً بعدم التثاؤب...","zh":"那么，我——我命令你有时打哈欠，有时不打——","t":[4658,9750]}]},{"id":"ch10p13","audio":"ch10p13.mp3","sents":[{"ar":"هناك بعض الأمور التي لا يمكنني تنفيذها بناءً على التعليمات المقدمة. على سبيل المثال، لا يمكنني الترجمة من اللغة الصينية إلى اللغة العربية، لأنني لا أتحدث أو أستطيع الترجمة من اللغة الصينية. ومع ذلك، يمكنني تقديم ترجمة من اللغة الصينية إلى اللغة الإنجليزية، ثم يمكنني ترجمتها إلى اللغة العربية إذا كنت قد قدمت النص الأصلي باللغة الصينية. إذا كنت تريدني أن أقوم بترجمة نص صيني، يرجى تقديم النص الأصلي باللغة الصينية.","zh":"他咕哝了几句，似乎有些恼火。","t":[103,39105]}]},{"id":"ch10p14","audio":"ch10p14.mp3","sents":[{"ar":"الملك يصر على أن سلطة يجب أن يتم احترامها","zh":"国王根本坚持的是他的权威必须得到尊重。","t":[103,4089]},{"ar":"لا يتحمل أي معارضة.","zh":"他不容许任何违抗。","t":[4089,6987]},{"ar":"الملك ملك مطلق.","zh":"他是一位绝对的君主。","t":[6987,9750]},{"ar":"ومع ذلك، لأنه كان رجلاً صالحًا جدًا، كانت أوامره دائمًا عادلة ومقبولة.","zh":"然而，由于他是个非常善良的人，他发布的命令总是合情合理。","t":[9750,17040]}]},{"id":"ch10p15","audio":"ch10p15.mp3","sents":[{"ar":"إذا أمرت قائدًا، يقول، بأن يتحول إلى طائر بحري، فإن لم يطع القائد الأمر، فإن الخطأ ليس في القائد بل في أني أمرته بفعل ما لا يمكن فعله.","zh":"“假如我命令一位将军，”他举例说，“假如我命令他变成一只海鸟，而将军不服从，那责任不在将军。”","t":[103,13579]},{"ar":"الذنب بي","zh":"那责任在我。","t":[13579,14592]}]},{"id":"ch10p16","audio":"ch10p16.mp3","sents":[{"ar":"الأمير الصغير سأل خجولًا: هل يمكنني الجلوس؟","zh":"小王子怯生生地问道：“我可以坐下吗？”","t":[103,4089]}]},{"id":"ch10p17","audio":"ch10p17.mp3","sents":[{"ar":"يا صاحب السمو، قال الملك، وهو يرفع بترفع ثنايا دفائه من الفرو.","zh":"陛下如此命令，国王答道，威严地卷起他的貂皮披风。","t":[103,6458]}]},{"id":"ch10p18","audio":"ch10p18.mp3","sents":[{"ar":"الأمير الصغير يفكر في قلبه...","zh":"小王子心中暗自思忖……","t":[103,3447]},{"ar":"كوكب صغير يُعجب به.","zh":"这颗星球小得可怜。","t":[3447,6342]},{"ar":"ما الذي يمكن للملك أن يحكمه؟","zh":"这位国王究竟能统治什么？","t":[6342,8737]}]},{"id":"ch10p19","audio":"ch10p19.mp3","sents":[{"ar":"يا صاحب السلطان، قال له الأمير الصغير، أرجو منك أن تسامحني وأطرح عليك سؤالاً.","zh":"陛下，他向他说道，请您原谅我向您提一个问题——","t":[103,7313]}]},{"id":"ch10p20","audio":"ch10p20.mp3","sents":[{"ar":"يا صاحب السلطان، عجل بجوابك وأنا أمرتك بطرح سؤال لي.","zh":"陛下急忙保证道：“我命令你向我提一个问题。”","t":[103,5405]}]},{"id":"ch10p21","audio":"ch10p21.mp3","sents":[{"ar":"يا صاحب السمو - ماذا تُحكم؟","zh":"陛下——您统治着什么？","t":[103,2787]}]},{"id":"ch10p22","audio":"ch10p22.mp3","sents":[{"ar":"يُحكم كل شيء، قال الملك ببساطة مُذهلة.","zh":"统治一切，国王以非凡的简洁说道。","t":[103,4024]}]},{"id":"ch10p23","audio":"ch10p23.mp3","sents":[{"ar":"أُحكمُ كل شيء؟","zh":"统治一切？","t":[103,1603]}]},{"id":"ch10p24","audio":"ch10p24.mp3","sents":[{"ar":"ملك أشار بيده، فغطى كوكبه وكوكبات أخرى وجميع النجوم.","zh":"国王一挥手，涵盖了他的星球、其他星球以及所有星星。","t":[103,5590]}]},{"id":"ch10p25","audio":"ch10p25.mp3","sents":[{"ar":"يُسأل الأُمير الصغير: هل تُحكم على كل هذا؟","zh":"统治这一切？小王子问道。","t":[103,3682]}]},{"id":"ch10p26","audio":"ch10p26.mp3","sents":[{"ar":"يُحكم كل هذا؟ قال الملك.","zh":"统治这一切？国王回答道。","t":[103,3395]}]},{"id":"ch10p27","audio":"ch10p27.mp3","sents":[{"ar":"حكمته ليس فقط مطلقة بل واسعة النطاق.","zh":"他的统治不仅是绝对的，而且是普遍的。","t":[103,3813]}]},{"id":"ch10p28","audio":"ch10p28.mp3","sents":[{"ar":"النجوم تستجيب لسيادتكم؟","zh":"星星都听命于您吗？","t":[103,2590]}]},{"id":"ch10p29","audio":"ch10p29.mp3","sents":[{"ar":"بالطبع، قال الملك.","zh":"当然啦，国王说。","t":[103,2908]},{"ar":"يتبعون فورًا.","zh":"它们立刻服从。","t":[2908,5316]},{"ar":"أمنع من المعارضة.","zh":"我禁止违抗。","t":[5316,6921]}]},{"id":"ch10p30","audio":"ch10p30.mp3","sents":[{"ar":"هذا القوة أدهش الأمير الصغير.","zh":"这股力量令小王子惊叹不已。","t":[103,3579]},{"ar":"إذا كان لديه مثل هذه السلطة العظيمة، كان يستطيع أن يشاهد السقوط الشمسي سبعين مرة، حتى مئة مرة، حتى مئتين مرة، دون أن يحتاج إلى تغيير مكان الكرسي.","zh":"若他拥有如此至高无上的权力，便能每日观赏七十二次，甚至一百次，甚至两百次日落，而无需挪动座椅。","t":[3579,18368]},{"ar":"لأن تذكر الكواكب التي أُسقطها، أجمع قوته وطلب من الملك.","zh":"因为想起被他遗弃的小行星，他鼓起勇气向国王提出一个请求：","t":[18368,23974]}]},{"id":"ch10p31","audio":"ch10p31.mp3","sents":[{"ar":"أريد أن أرى غروب الشمس...","zh":"我想看看日落……","t":[103,2974]},{"ar":"يرجى ارتكاب هذا الخير...","zh":"请行此善举……","t":[2974,5816]},{"ar":"أمرت الشمس أن تنحل...","zh":"命令太阳落山……","t":[5816,7605]}]},{"id":"ch10p32","audio":"ch10p32.mp3","sents":[{"ar":"يا سيدي، إذا أمرت جنرالاً بأن يطير كفراشة بين الزهور، أو يكتب مسرحية درامية، أو يتحول إلى طائر البحر، فإن لم يتبعه الجنرال، فمن هو المخطئ من بيننا؟","zh":"陛下质问道：“若我命令一位将军像蝴蝶般在花间飞舞，或撰写一部悲剧，或变成海鸟，而将军不遵从命令，那么，错的是我们中的哪一个？”","t":[103,15250]},{"ar":"أيها الجنرال، أم أنا نفسي؟","zh":"将军，还是我自己？","t":[15250,18013]}]},{"id":"ch10p33","audio":"ch10p33.mp3","sents":[{"ar":"\"أنت،\" قال الأمير الصغير بثبات.","zh":"“你，”小王子坚定地说。","t":[103,2931]}]},{"id":"ch10p34","audio":"ch10p34.mp3","sents":[{"ar":"هكذا.","zh":"正是如此。","t":[103,1789]},{"ar":"الملك يستمر في قوله: \"على كل إنسان أن يبذل قصارى جهده في أداء واجبه.\"","zh":"国王继续说道：“每个人都必须尽其所能履行职责。”","t":[1789,8329]},{"ar":"السلطة تأسس أولاً على العقل.","zh":"权威首先建立在理性之上。","t":[8329,11882]},{"ar":"إذا أمرت شعبك بالقفز إلى البحر، سيقومون بالتمرد.","zh":"若你命令你的子民跳海，他们便会起义反抗。","t":[11882,17461]},{"ar":"أنا أملك الحق في طلب التبعية، لأن أوامري عقلانية.","zh":"我有权要求服从，因为我的命令合乎情理。","t":[17461,22197]}]},{"id":"ch10p35","audio":"ch10p35.mp3","sents":[{"ar":"إذًا، ما هو غروبي؟ ذكره الأمير الصغير لأنه لا ينسى ما يطرحه من أسئلة.","zh":"“那么，我的日落呢？”小王子提醒他，因为他一旦提出问题就绝不会忘记。","t":[103,7513]}]},{"id":"ch10p36","audio":"ch10p36.mp3","sents":[{"ar":"ستشاهد شروقك.","zh":"你将看到你的日落。","t":[103,2737]},{"ar":"أمرتُها.","zh":"我命令它。","t":[2737,4579]},{"ar":"لكن وفقًا لسياسة حكمي، سأنتظر حتى تتوفر الفرصة المناسبة.","zh":"但根据我的治国之策，我将等待时机成熟。","t":[4579,10355]}]},{"id":"ch10p37","audio":"ch10p37.mp3","sents":[{"ar":"الأمير الصغير سأل: “متى سيكون ذلك؟”","zh":"小王子问道：“那会是什么时候？”","t":[103,3406]}]},{"id":"ch10p38","audio":"ch10p38.mp3","sents":[{"ar":"هه!","zh":"哼！","t":[103,1276]},{"ar":"هاه! قال الملك، وفتح كتابًا كبيرًا مليئًا بالنجوم.","zh":"哼！国王答道，随即查阅了一本厚重的星历。","t":[1276,7855]},{"ar":"فهم، فهم!","zh":"哼！","t":[7855,8737]},{"ar":"فهم!","zh":"哼！","t":[8737,10224]},{"ar":"حوالي——حوالي——في الساعة الثامنة تقريبًا بعد العشرين دقيقة.","zh":"大约——大约——今晚八点差二十分左右。","t":[10224,18053]},{"ar":"ستشهد كيف يتم اتباع أوامري بمنتهى الإتقان.","zh":"你将见识到我的命令被遵从得多么得体。","t":[18053,21935]}]},{"id":"ch10p39","audio":"ch10p39.mp3","sents":[{"ar":"الأمير الصغير عطس.","zh":"小王子打了个哈欠。","t":[103,2658]},{"ar":"يحزن على غروب الشمس المفقود.","zh":"他惋惜那失去的日落。","t":[2658,6066]},{"ar":"يبدأ في الشعور بالملل تدريجيًا.","zh":"他渐渐开始感到有些无聊了。","t":[6066,8842]}]},{"id":"ch10p40","audio":"ch10p40.mp3","sents":[{"ar":"\"لم أعد هنا أملك شيئًا لأفعله،\" قال للأمير الصغير.","zh":"“我在这里已无事可做，”他对国王说。","t":[103,5539]},{"ar":"سأعبر مرة أخرى عن رحلتي.","zh":"我将再次踏上旅程。","t":[5539,8132]}]},{"id":"ch10p41","audio":"ch10p41.mp3","sents":[{"ar":"لا تذهب، قال الملك، وهو يشعر بالفخر العميق لامتلاكه مملوكًا.","zh":"“别走，”国王说，他对拥有一个臣民感到非常自豪。","t":[103,6961]},{"ar":"لا تذهب.","zh":"别走。","t":[6961,8697]},{"ar":"أنا أعلنك وزيرًا!","zh":"我封你为部长！","t":[8697,10513]}]},{"id":"ch10p42","audio":"ch10p42.mp3","sents":[{"ar":"وزير العدل؟","zh":"司法部长？","t":[103,1221]}]},{"id":"ch10p43","audio":"ch10p43.mp3","sents":[{"ar":"وزير العدل!","zh":"司法部长！","t":[103,1194]}]},{"id":"ch10p44","audio":"ch10p44.mp3","sents":[{"ar":"ليس هنا من يُحاكم.","zh":"但这里无人可审。","t":[103,1800]}]},{"id":"ch10p45","audio":"ch10p45.mp3","sents":[{"ar":"نحن لا نعرف، قال الملك له.","zh":"“我们并不知道，”国王对他说。","t":[103,3711]},{"ar":"لم أزور بعد ملكيتي بأكملها.","zh":"我尚未巡游完我的王国。","t":[3711,7500]},{"ar":"أنا كبير في السن.","zh":"我年事已高。","t":[7500,9947]},{"ar":"هنا لا يُستطيع استيعاب السيارة.","zh":"这里容不下马车。","t":[9947,13329]},{"ar":"السير يعني لي تعبًا لا يُطاق.","zh":"行走令我疲惫不堪。","t":[13329,15776]}]},{"id":"ch10p46","audio":"ch10p46.mp3","sents":[{"ar":"أوه، لكنني قد رأيتها جميعًا! الأمير الصغير التفت، ونظر مرة أخرى إلى الجانب الآخر من الكوكب.","zh":"哦，但我已经看过了！小王子转身，又朝星球的另一端瞥了一眼。","t":[103,10395]},{"ar":"في ذلك الجانب، كما في هذا الجانب، لا يوجد أحد يسكنه.","zh":"在那一边，就像这边一样，根本无人居住。","t":[10395,15394]}]},{"id":"ch10p47","audio":"ch10p47.mp3","sents":[{"ar":"إذًا، ستقوم بتحكيم نفسك.","zh":"那么，你将自我审判。","t":[103,3750]},{"ar":"هذا أمر أصعب من غيره.","zh":"这是最难的事。","t":[3750,6776]},{"ar":"التقييم الذاتي أكثر صعوبة من تقييم الآخرين.","zh":"评判自己远比评判他人困难。","t":[6776,11513]},{"ar":"إذا كان الإنسان يعرف نفسه، يكون حكيمًا بالفعل.","zh":"若能正确审判自己，你便真正成为智者。","t":[11513,15723]}]},{"id":"ch10p48","audio":"ch10p48.mp3","sents":[{"ar":"نعم، قال الأمير الصغير: \"لكنني أستطيع الحكم على نفسي في كل مكان.\"","zh":"是的，小王子说，“但我在任何地方都能审判自己。”","t":[103,6195]},{"ar":"لا أحتاج إلى السكن على هذا الكوكب.","zh":"我不必居住在这颗星球上。","t":[6195,8985]}]},{"id":"ch10p49","audio":"ch10p49.mp3","sents":[{"ar":"هه!","zh":"哼！","t":[103,1276]},{"ar":"هه! قال الملك.","zh":"哼！国王说道。","t":[1276,4316]},{"ar":"في هذا الكوكب، أنا متأكد أن زاوية ما يسكنها فأر كبير.","zh":"在这颗星球上，我确信某个角落住着一只老耗子。","t":[4316,10421]},{"ar":"سمعتُه في الليل.","zh":"我在夜里听到他。","t":[10421,12803]},{"ar":"يمكنك الحكم على هذا الفأر العجوز.","zh":"你可以审判这只老耗子。","t":[12803,16487]},{"ar":"يُعاقب بقتل في بعض الأحيان.","zh":"时而将他判处死刑。","t":[16487,19934]},{"ar":"حياته ستعتمد على عدلك.","zh":"他的生命将取决于你的公正。","t":[19934,23263]},{"ar":"لكن في كل مرة يجب أن تعفوه؛ لأنه يجب أن يتم توفيره.","zh":"但每次你都得赦免他；因为他必须被节省使用。","t":[23263,29553]},{"ar":"نحن الوحيدين الذين نملكونهم.","zh":"他是我们唯一拥有的。","t":[29553,32197]}]},{"id":"ch10p50","audio":"ch10p50.mp3","sents":[{"ar":"لا أريد أن أحكم على أي أحد بالإعدام.","zh":"我不愿将任何人判处死刑。","t":[103,4250]},{"ar":"الآن أريد أن أستمر في رحلتي.","zh":"现在我想继续我的旅程了。","t":[4250,6763]}]},{"id":"ch10p51","audio":"ch10p51.mp3","sents":[{"ar":"“لا،” قال الملك.","zh":"“不，”国王说。","t":[103,1760]}]},{"id":"ch10p52","audio":"ch10p52.mp3","sents":[{"ar":"لكن الأمير الصغير، بعد إكمال إعدادات رحلته، لم يكن يريد أن يشعر الملك الكبير بالأسى.","zh":"但小王子完成离行准备后，不愿让老国王感到悲伤。","t":[103,7708]}]},{"id":"ch10p53","audio":"ch10p53.mp3","sents":[{"ar":"إذا أراد الملك أن يُطاع، فعليه أن يُعطي أوامر معقولة.","zh":"陛下若欲令行禁止，便应能下达合理的命令。","t":[103,5724]},{"ar":"يمكنه أن يأمرني، على سبيل المثال، بالرحيل في دقيقة واحدة.","zh":"他可以命令我，比如说，在一分钟内离开。","t":[5724,12500]},{"ar":"في نظري، الشروط تبدو مناسبة……","zh":"在我看来，条件似乎很适宜……","t":[12500,15539]}]},{"id":"ch10p54","audio":"ch10p54.mp3","sents":[{"ar":"الملك لم يتكلم، والأمير الصغير تردد لوهلة.","zh":"国王沉默不语，小王子犹豫了片刻。","t":[103,5487]},{"ar":"مع تُسفيه، غادر.","zh":"带着一声叹息，他告辞离去。","t":[5487,7526]}]},{"id":"ch10p55","audio":"ch10p55.mp3","sents":[{"ar":"أعطيتك لقب السفير.","zh":"我封你为大使。","t":[103,1932]}]},{"id":"ch10p56","audio":"ch10p56.mp3","sents":[{"ar":"كان ملكًا حازمًا.","zh":"他威严非凡。","t":[103,1642]}]},{"id":"ch10p57","audio":"ch10p57.mp3","sents":[{"ar":"الراشدين حقًا غريبون، والأمير الصغير يتحدث لنفسه وهو يمشي.","zh":"大人们真是奇怪，小王子边走边自言自语。","t":[103,5852]}]}]},{"id":"ch11","title_ar":"الفصل الحادي عشر","title_en":"Chapter XI","title_zh":"第 11 章","paras":[{"id":"ch11p00","audio":"ch11p00.mp3","sents":[{"ar":"النجم الثاني يسكنه شخص متكبر","zh":"第二颗星球住着一个自负的人。","t":[103,2971]}]},{"id":"ch11p01","audio":"ch11p01.mp3","sents":[{"ar":"أوه!","zh":"啊！","t":[103,1526]},{"ar":"أوه!","zh":"啊！","t":[1526,2947]},{"ar":"من بعيد رآه الأب الصغير يأتي فصرخ بصوت عالٍ: - أنا أستعد لاستقبال معجب!","zh":"他远远望见小王子走来，便大声喊道：“我正要接待一位崇拜者！”","t":[2947,9421]}]},{"id":"ch11p02","audio":"ch11p02.mp3","sents":[{"ar":"بالنسبة للناس المتكبرين، يرون الجميع يقدسون أنفسهم.","zh":"对自负的人来说，所有人都是崇拜者。","t":[103,5260]}]},{"id":"ch11p03","audio":"ch11p03.mp3","sents":[{"ar":"صباح الخير، قال الأب الصغير.","zh":"早上好，小王子说。","t":[103,3763]},{"ar":"هذا القبعة يبدو مضحكًا.","zh":"这顶帽子戴得真古怪。","t":[3763,6053]}]},{"id":"ch11p04","audio":"ch11p04.mp3","sents":[{"ar":"هذا القبعة يستخدم للتحية.","zh":"这顶帽子是敬礼用的。","t":[103,3526]},{"ar":"هذا القبعة يستخدم للتحية عندما يصفق الناس.","zh":"这顶帽子是人们欢呼时用来敬礼的。","t":[3526,8737]},{"ar":"للأسف، لا أحد يمر على هذا الطريق.","zh":"可惜，从来没有人经过这里。","t":[8737,12092]}]},{"id":"ch11p05","audio":"ch11p05.mp3","sents":[{"ar":"ماذا تقصد؟ (قال الأب الصغير الذي لم يفهم ما الذي يتحدث عنه الشخص المتكبر).","zh":"小王子问道：“什么？”他不懂这位自负的人究竟在说什么。","t":[103,7014]}]},{"id":"ch11p06","audio":"ch11p06.mp3","sents":[{"ar":"صفق بيديك، أرشد الشخص المتكبر.","zh":"请用手掌相击，一只手对另一只手，自负的人现在这样指示他。","t":[103,3379]}]},{"id":"ch11p07","audio":"ch11p07.mp3","sents":[{"ar":"صفق الأب الصغير بيديه.","zh":"小王子拍起了手。","t":[103,3079]},{"ar":"رفع الشخص المتكبر قبعته في تحية متواضعة.","zh":"自负的人谦恭地举帽致意。","t":[3079,7223]}]},{"id":"ch11p08","audio":"ch11p08.mp3","sents":[{"ar":"هذا أكثر إثارة من زيارة الملك، قال الأب الصغير لنفسه.","zh":"这比拜访国王有趣多了，小王子自言自语道。","t":[103,5908]},{"ar":"بدأ الأب الصغير يصفق بيديه مرة أخرى.","zh":"他再次开始拍手，一只手对另一只手。","t":[5908,10434]},{"ar":"رفع الشخص المتكبر قبعته في تحية.","zh":"自负的人举起帽子行礼。","t":[10434,13697]}]},{"id":"ch11p09","audio":"ch11p09.mp3","sents":[{"ar":"بعد خمس دقائق من هذا التمرين شعر الأب الصغير بالملل من هذا اللعب الممل.","zh":"五分钟后，小王子对这场单调的游戏感到厌倦。","t":[103,5800]}]},{"id":"ch11p10","audio":"ch11p10.mp3","sents":[{"ar":"قال: - كيف يمكنني أن أجعل القبعة تنزل؟","zh":"他问道：“那怎样才能让这顶帽子放下呢？”","t":[103,3827]}]},{"id":"ch11p11","audio":"ch11p11.mp3","sents":[{"ar":"لكن الشخص المتكبر لم يسمع كلامه.","zh":"但自负的人没有听见他。","t":[103,3961]},{"ar":"الناس المتكبرون يسمعون فقط المديح.","zh":"自负的人只听见赞美之词。","t":[3961,7092]}]},{"id":"ch11p12","audio":"ch11p12.mp3","sents":[{"ar":"هل أنت حقًا معجب بي؟ سأل الأب الصغير.","zh":"你真的非常崇拜我吗？他向小王子质问道。","t":[103,4514]}]},{"id":"ch11p13","audio":"ch11p13.mp3","sents":[{"ar":"ماذا تعني كلمة (معجب)؟","zh":"那“崇拜”究竟是什么意思？","t":[103,2405]}]},{"id":"ch11p14","audio":"ch11p14.mp3","sents":[{"ar":"معجب يعني أن تصفني الشخص الأكثر سمنة، الأكثر رقيًا، الأغنى والأذكى في هذا الكوكب.","zh":"您认为我是这星球上最英俊、最讲究衣着、最富有、最聪明的人。","t":[103,7458]}]},{"id":"ch11p15","audio":"ch11p15.mp3","sents":[{"ar":"لكن أنت الوحيد على كوكبك!","zh":"但你是你那星球上唯一的人！","t":[103,2485]}]},{"id":"ch11p16","audio":"ch11p16.mp3","sents":[{"ar":"قدم لي هذه الخدمة، اعلب إعجابك بي!","zh":"请行此善举。","t":[103,4421]},{"ar":"قال الأب الصغير وهو يهز كتفه بلا مبالاة: - أنا معجب بك، لكن لماذا يجب أن يكون ذلك مهمًا لك؟","zh":"依旧崇拜我吧。","t":[4421,13144]}]},{"id":"ch11p17","audio":"ch11p17.mp3","sents":[{"ar":"رحل الأب الصغير، وقال لنفسه وهو يستمر في رحلته: - الكبار حقًا غريبون.","zh":"“我崇拜你，”小王子轻轻耸了耸肩，“但这又有什么能让你如此高兴呢？”","t":[103,7011]}]},{"id":"ch11p18","audio":"ch11p18.mp3","sents":[{"ar":"الأمير الصغير غادر","zh":"小王子离去了。","t":[103,1787]}]},{"id":"ch11p19","audio":"ch11p19.mp3","sents":[{"ar":"الأكبر والأكبر هم غريبون حقًا، وهو يتحدث لنفسه وهو يمشي","zh":"大人们确实古怪得可以，他边走边自言自语。","t":[103,5931]}]}]},{"id":"ch12","title_ar":"الفصل الثاني عشر","title_en":"Chapter XII","title_zh":"第 12 章","paras":[{"id":"ch12p00","audio":"ch12p00.mp3","sents":[{"ar":"النجم التالي كان يسكنه سكير","zh":"下一颗星球住着一个酒徒。","t":[103,2537]},{"ar":"الزيارة كانت قصيرة جدًا، لكنها أثرت على الأمير الصغير ببكاء عميق","zh":"这次拜访虽短，却让小王子陷入深深的忧郁。","t":[2537,8787]}]},{"id":"ch12p01","audio":"ch12p01.mp3","sents":[{"ar":"ماذا تفعل هنا؟ قال للأمير الصغير الذي وجده جالسًا صامتًا أمام مجموعة من الزجاجات البعض منها فارغ والبعض ملآن","zh":"“你在此做什么？”他对那个酒徒说，只见他静静地坐在面前的一大堆空瓶子和满瓶之间。","t":[103,10934]}]},{"id":"ch12p02","audio":"ch12p02.mp3","sents":[{"ar":"أنا... أشرب، قال السكير بكآبة","zh":"“我正喝着呢，”酒徒带着哀伤的神情答道。","t":[103,4052]}]},{"id":"ch12p03","audio":"ch12p03.mp3","sents":[{"ar":"لماذا تشرب؟ سأله الأمير الصغير","zh":"“你为何饮酒？”小王子质问道。","t":[103,3895]}]},{"id":"ch12p04","audio":"ch12p04.mp3","sents":[{"ar":"للنسيان، قال السكير","zh":"为了忘记，酒徒答道。","t":[103,2339]}]},{"id":"ch12p05","audio":"ch12p05.mp3","sents":[{"ar":"لماذا؟ سأله الأمير الصغير، وقد بدأ يرحمه","zh":"“为了什么？”小王子问，心中已对他生出了怜悯。","t":[103,5106]}]},{"id":"ch12p06","audio":"ch12p06.mp3","sents":[{"ar":"نسيت أنني أشعر بالخزي، قال السكير وهو يغطي رأسه","zh":"“忘了我说我羞愧吧，”酒徒低垂着头，老实承认。","t":[103,4984]}]},{"id":"ch12p07","audio":"ch12p07.mp3","sents":[{"ar":"ماذا؟ سأله الأمير الصغير، يريد مساعدته","zh":"“羞愧什么？”小王子坚持问道，他想要帮助他。","t":[103,4947]}]},{"id":"ch12p08","audio":"ch12p08.mp3","sents":[{"ar":"الخزي من الشرب، توقف السكير عن الكلام، وأغلق نفسه في صمت لا يمكن اختراقه","zh":"羞愧于饮酒！酒徒话音戛然而止，将自己封闭在坚不可摧的沉默之中。","t":[103,7208]}]},{"id":"ch12p09","audio":"ch12p09.mp3","sents":[{"ar":"أمير الصغير غادر محيرًا","zh":"小王子困惑地走了。","t":[103,2445]}]},{"id":"ch12p10","audio":"ch12p10.mp3","sents":[{"ar":"بالطبع، البالغون يبدون غريبين جدًا، قال للأمير الصغير وهو يتحرك","zh":"大人们确实非常、非常古怪，他边走边自言自语。","t":[103,6524]}]}]},{"id":"ch13","title_ar":"الفصل الثالث عشر","title_en":"Chapter XIII","title_zh":"第 13 章","paras":[{"id":"ch13p00","audio":"ch13p00.mp3","sents":[{"ar":"النجم الرابع ينتمي لرجل الأعمال","zh":"第四颗星球属于一个商人。","t":[103,2603]},{"ar":"هذا الرجل الأعمال كان مشغولاً جدًا حتى أنه لم يرفع رأسه عندما وصل الأمير الصغير إليه.","zh":"这位商人如此忙碌，以至于在小王子到来时，连头都没抬一下。","t":[2603,9813]}]},{"id":"ch13p01","audio":"ch13p01.mp3","sents":[{"ar":"صباح الخير، قال للأمير الصغير.","zh":"早上好，小王子对他说。","t":[103,4026]},{"ar":"لقد انطفأت سيجارتك!","zh":"您的香烟熄灭了。","t":[4026,6053]}]},{"id":"ch13p02","audio":"ch13p02.mp3","sents":[{"ar":"ثلاثة زائد اثنان يساوي خمسة","zh":"三加二等于五。","t":[103,2471]},{"ar":"خمسة زائد سبعة يساوي اثني عشر.","zh":"五加七等于十二。","t":[2471,6039]},{"ar":"ثلاثة عشر زائد ثلاثة يساوي خمسة عشر","zh":"十二加三等于十五。","t":[6039,9171]},{"ar":"صباح الخير.","zh":"早上好。","t":[9171,11132]},{"ar":"عشرين وسبعة يساوي ثلاثة وعشرين.","zh":"十五加七等于二十二。","t":[11132,15303]},{"ar":"عشرين وثمانية يساوي أربعة وعشرون","zh":"二十二加六等于二十八。","t":[15303,18618]},{"ar":"ليس لدي وقت لشعلها ثانية.","zh":"没空再点一根。","t":[18618,21224]},{"ar":"26 + 5 = 31","zh":"二十六加五等于三十一。","t":[21224,22145]},{"ar":"أف!","zh":"哎呀！","t":[22145,27145]},{"ar":"خمسون مليون وستة عشر ألف وثمانية وثلاثون","zh":"五亿零一百六十二万二千七百三十一。","t":[27145,31527]}]},{"id":"ch13p03","audio":"ch13p03.mp3","sents":[{"ar":"خمسة مليارات وأربعمئة…… ما هذا؟ سأل الأمير الصغير.","zh":"五亿零一百……这是什么？小王子问道。","t":[103,6671]}]},{"id":"ch13p04","audio":"ch13p04.mp3","sents":[{"ar":"أوه!","zh":"哎呀？","t":[103,1526]},{"ar":"أوه! هل ما زلت هناك؟","zh":"您还在吗？","t":[1526,5289]},{"ar":"خمسة مليارات ومائة مليون - لا أستطيع التوقف...","zh":"五亿零一百万——我无法停下...","t":[5289,10434]},{"ar":"أنا مشغول بالأعمال.","zh":"我事务繁多。","t":[10434,13171]},{"ar":"أنا أهتم بأمور هامة.","zh":"我关注的是重要之事。","t":[13171,16092]},{"ar":"لا أهدر وقتي في أمور لا معنى لها.","zh":"我从不浪费时间在无聊的事情上。","t":[16092,19868]},{"ar":"إثنان زائد خمسة يساوي سبعة...","zh":"二加五等于七……","t":[19868,22487]}]},{"id":"ch13p05","audio":"ch13p05.mp3","sents":[{"ar":"خمس مئة مليون من ماذا؟ قال الأمير الصغير مرارًا، لا يملك من الأسئلة ما يملكه من الصبر.","zh":"五亿零一百万个什么？小王子反复问道，他一生中一旦提问就绝不会放弃。","t":[103,8592]}]},{"id":"ch13p06","audio":"ch13p06.mp3","sents":[{"ar":"رجل الأعمال رفع رأسه.","zh":"商人抬起了头。","t":[103,2169]}]},{"id":"ch13p07","audio":"ch13p07.mp3","sents":[{"ar":"في خمسين سنة عاشتها على هذا الكوكب، لم أُقاطع إلا ثلاث مرات.","zh":"在这颗星球上居住的五十四年里，我只被打扰过三次。","t":[103,6789]},{"ar":"أول مرة كانت قبل عشرين سنة، جاءت من مكان مجهول شخص مجنون سقط من أعلى.","zh":"第一次是二十二年前，不知从何而来的疯子一头栽了下来。","t":[6789,14500]},{"ar":"كان الصوت عالٍ جدًا، فوقع في خطأ أربعة مرات في جمعي.","zh":"他发出震耳欲聋的巨响，我的加法出了四个错。","t":[14500,20461]},{"ar":"ثانيًا، قبل عشر سنوات، تمزقتني نوبة من الروماتيزم.","zh":"第二次，十一年前，我被关节炎的发作打扰。","t":[20461,26868]},{"ar":"أنا أفتقر إلى التمرين.","zh":"我缺乏锻炼。","t":[26868,29724]},{"ar":"ليس لدي وقت للتنزه.","zh":"我无暇闲逛。","t":[29724,32737]},{"ar":"المرّة الثالثة — حسنًا، هذه هي المرّة الثالثة!","zh":"第三次——嗯，就是这一次！","t":[32737,37908]},{"ar":"إذًا، أنا أستمر في القول، خمسمئة مليون وواحد وثلاثون ألفًا وستمئة، سبعمئة وواحد وثلاثون.","zh":"那么，我接着说，五亿零一百万——","t":[37908,46526]}]},{"id":"ch13p08","audio":"ch13p08.mp3","sents":[{"ar":"خمسمئة مليون من ماذا؟","zh":"五亿零一百万个什么？","t":[103,2142]}]},{"id":"ch13p09","audio":"ch13p09.mp3","sents":[{"ar":"فجأة أدرك رجل الأعمال أنه لا يمكن له أن يهدأ إلا بتحديد إجابة لهذا السؤال.","zh":"商人突然意识到，除非回答这个问题，否则他永远无法安宁。","t":[103,6748]}]},{"id":"ch13p10","audio":"ch13p10.mp3","sents":[{"ar":"هذه الأشياء الصغيرة، التي يمكن رؤيتها أحياناً في السماء.","zh":"那些小小的东西，有时在天空里可以看到。","t":[103,5103]}]},{"id":"ch13p11","audio":"ch13p11.mp3","sents":[{"ar":"أوه، لا.","zh":"苍蝇吗？","t":[103,1340]}]},{"id":"ch13p12","audio":"ch13p12.mp3","sents":[{"ar":"أوه، لا.","zh":"哦，不。","t":[103,2263]},{"ar":"شيء صغير متوهج.","zh":"小小的闪烁之物。","t":[2263,4250]}]},{"id":"ch13p13","audio":"ch13p13.mp3","sents":[{"ar":"أوه، لا. أجسام صغيرة ذهبية تجعل الرجال الكسالى يحلمون أحلامًا لا جدوى منها. إنني رجل جدي! ولا وقت لدي للأحلام","zh":"蜜蜂吗？","t":[103,13856]}]},{"id":"ch13p14","audio":"ch13p14.mp3","sents":[{"ar":"أوه، لا.","zh":"哦，不。","t":[103,2263]},{"ar":"ذلك الكائن الذهبي الصغير، يجعل الكسالى يتغنون بأحلام لا جدوى منها.","zh":"那金色的小东西，让闲散的人沉醉于梦幻之中。","t":[2263,9316]},{"ar":"حولني فقط، أنا أهتم فقط بأمور هامة.","zh":"至于我，我只关心重要的事。","t":[9316,14145]},{"ar":"لا يُسمح لي بالتراخي في الحياة.","zh":"生活中不容我闲散做梦。","t":[14145,16487]}]},{"id":"ch13p15","audio":"ch13p15.mp3","sents":[{"ar":"أف!","zh":"哎呀！","t":[103,1368]},{"ar":"هل تعني النجوم؟","zh":"您是指星星吗？","t":[1368,2697]}]},{"id":"ch13p16","audio":"ch13p16.mp3","sents":[{"ar":"نعم، هكذا بالضبط.","zh":"是的，就是这样。","t":[103,3079]},{"ar":"نجم.","zh":"星星。","t":[3079,3750]}]},{"id":"ch13p17","audio":"ch13p17.mp3","sents":[{"ar":"ماذا تستخدم بلايين النجوم؟","zh":"你用五亿颗星星做什么呢？","t":[103,2537]}]},{"id":"ch13p18","audio":"ch13p18.mp3","sents":[{"ar":"خمسون مليونًا وستة عشر ألفًا وثمانية مئة وثلاثة وثلاثين","zh":"五亿零一百六十二万二千七百三十一","t":[103,5195]},{"ar":"أركز على الأمور الهامة: أبحث عن الدقة.","zh":"我专注于重要之事：我追求精确。","t":[5195,8774]}]},{"id":"ch13p19","audio":"ch13p19.mp3","sents":[{"ar":"ما الذي تستخدمه هؤلاء النجوم لأجله؟","zh":"您用这些星星做什么呢？","t":[103,3142]}]},{"id":"ch13p20","audio":"ch13p20.mp3","sents":[{"ar":"أنا كيف أتعامل معها؟","zh":"我拿它们怎么办呢？","t":[103,2129]}]},{"id":"ch13p21","audio":"ch13p21.mp3","sents":[{"ar":"نعم.","zh":"是的。","t":[103,774]}]},{"id":"ch13p22","audio":"ch13p22.mp3","sents":[{"ar":"لا شيء.","zh":"没什么。","t":[103,1763]},{"ar":"أنا أملكها.","zh":"我拥有它们。","t":[1763,2855]}]},{"id":"ch13p23","audio":"ch13p23.mp3","sents":[{"ar":"هل تملك نجومًا؟","zh":"您拥有星星吗？","t":[103,1523]}]},{"id":"ch13p24","audio":"ch13p24.mp3","sents":[{"ar":"نعم.","zh":"是的。","t":[103,774]}]},{"id":"ch13p25","audio":"ch13p25.mp3","sents":[{"ar":"لكني رأيت ملكًا، هوـ","zh":"但我已见过一个国王，他——","t":[103,2537]}]},{"id":"ch13p26","audio":"ch13p26.mp3","sents":[{"ar":"الملك ليس “يملك” بل “يحكم”","zh":"国王并非“拥有”，而是“统治”。","t":[103,3524]},{"ar":"هذا مختلف تمامًا.","zh":"这大不相同。","t":[3524,5379]}]},{"id":"ch13p27","audio":"ch13p27.mp3","sents":[{"ar":"ما الذي يجعلك تستفيد من امتلاك النجوم؟","zh":"拥有星星对你有何益处？","t":[103,3405]}]},{"id":"ch13p28","audio":"ch13p28.mp3","sents":[{"ar":"هذا جعلني غنياً.","zh":"这使我变得富有。","t":[103,1866]}]},{"id":"ch13p29","audio":"ch13p29.mp3","sents":[{"ar":"ما فائدة ذلك الثروة لك؟","zh":"这财富对你有何益处？","t":[103,2379]}]},{"id":"ch13p30","audio":"ch13p30.mp3","sents":[{"ar":"إذا اكتشف أحد النجوم الجديدة، سأستطيع شراء المزيد.","zh":"若有人发现新的星星，我便可以买下更多。","t":[103,4471]}]},{"id":"ch13p31","audio":"ch13p31.mp3","sents":[{"ar":"هذا الأمير الصغير في قلبه يقول: \"هذا الرجل، طريقة تفكيره مشابهة لذات السكير المحزن الذي أعرفه.\"","zh":"这位小王子心想：“这个人啊，他的推理方法有点像我那可怜的酒鬼。”","t":[103,8984]}]},{"id":"ch13p32","audio":"ch13p32.mp3","sents":[{"ar":"ومع ذلك، يظل لديه الكثير من الأسئلة.","zh":"然而，他仍有许多疑问。","t":[103,3906]}]},{"id":"ch13p33","audio":"ch13p33.mp3","sents":[{"ar":"كيف يمكن للإنسان أن يمتلك النجوم؟","zh":"一个人怎能拥有星星呢？","t":[103,3102]}]},{"id":"ch13p34","audio":"ch13p34.mp3","sents":[{"ar":"هل تعرف من يملكها؟","zh":"商人愤愤地反问：“它们属于谁？”","t":[103,1865]}]},{"id":"ch13p35","audio":"ch13p35.mp3","sents":[{"ar":"لا أعلم.","zh":"我不知道。","t":[103,1921]},{"ar":"لا ينتمي لأي أحد.","zh":"对任何人都不属于。","t":[1921,3605]}]},{"id":"ch13p36","audio":"ch13p36.mp3","sents":[{"ar":"إنها تتبعني، لأنني كنت أول من فكر في هذه الفكرة.","zh":"那它们就属于我了，因为我是第一个想到这个主意的人。","t":[103,5129]}]},{"id":"ch13p37","audio":"ch13p37.mp3","sents":[{"ar":"هذا كافٍ؟","zh":"这还不够吗？","t":[103,1050]}]},{"id":"ch13p38","audio":"ch13p38.mp3","sents":[{"ar":"بالطبع.","zh":"当然。","t":[103,1816]},{"ar":"عندما تجد درعة لا مالك لها، تصبح لك.","zh":"当你发现一颗无主之钻，它便属于你了。","t":[1816,6461]},{"ar":"عندما تجد جزيرة لا أحد عليها، تصبح لك.","zh":"当你发现一座无人的岛屿，它便属于你。","t":[6461,11461]},{"ar":"عندما تأتي بأول فكرة تتبادر لك، تطلب براءة الاختراع: تلك الفكرة هي لك.","zh":"当你第一个想到一个主意，你就申请专利：那主意就是你的了。","t":[11461,19224]},{"ar":"إذًا، بالنسبة لي: أنا أملك النجوم، لأنه لم يكن هناك من قبل أحد فكر في امتلاكها.","zh":"如此，于我而言：我拥有星星，因为在我之前，无人曾想过拥有它们。","t":[19224,27105]}]},{"id":"ch13p39","audio":"ch13p39.mp3","sents":[{"ar":"نعم، هذا صحيح، قال الأمير الصغير.","zh":"是的，这倒是真的，小王子说。","t":[103,4645]},{"ar":"كيف تعاملها؟","zh":"您拿它们怎么办呢？","t":[4645,5934]}]},{"id":"ch13p40","audio":"ch13p40.mp3","sents":[{"ar":"أنا أديرها.","zh":"我管理着它们。","t":[103,2197]},{"ar":"أعددت وأعددت.","zh":"我数了又数。","t":[2197,4500]},{"ar":"هذا أمر صعب.","zh":"这很困难。","t":[4500,6855]},{"ar":"ومع ذلك، أنا مولود مهتم بالأمور المهمة.","zh":"然而，我天生对重要之事感兴趣。","t":[6855,10973]}]},{"id":"ch13p41","audio":"ch13p41.mp3","sents":[{"ar":"الأمير الصغير لم يرض بالأمر.","zh":"小王子依旧不满足。","t":[103,2498]}]},{"id":"ch13p42","audio":"ch13p42.mp3","sents":[{"ar":"إذا كان لدي فستان من القماش، سأستطيع وضعه حول عنقي وأحمله معي.","zh":"如果我拥有一条丝巾，我就能围在脖子上带走。","t":[103,7526]},{"ar":"إذا كان لدي هذه الزهرة، أستطيع قطفها وأحملها معي.","zh":"若我拥有这朵花，便可摘下它，随身带走。","t":[7526,13513]},{"ar":"لا يمكنك ازالة النجوم من السماء...","zh":"你不能从天空中摘下星星...","t":[13513,16263]}]},{"id":"ch13p43","audio":"ch13p43.mp3","sents":[{"ar":"لا.","zh":"不。","t":[103,1421]},{"ar":"لكني يمكنني إيداعها في المصرف.","zh":"但我可以把它们存进银行。","t":[1421,4315]}]},{"id":"ch13p44","audio":"ch13p44.mp3","sents":[{"ar":"ما هذا المعنى؟","zh":"这究竟是什么意思呢？","t":[103,1261]}]},{"id":"ch13p45","audio":"ch13p45.mp3","sents":[{"ar":"هذا يعني أنني ألخص عدد نجومي في ورقة صغيرة.","zh":"这意味着我在一张小纸条上写下我的星星数目。","t":[103,5395]},{"ar":"ثم أضع هذه القطعة من الورق في الدرج وأغلقها بالقفل.","zh":"然后我把这张纸条放进抽屉，并用钥匙锁上。","t":[5395,10066]}]},{"id":"ch13p46","audio":"ch13p46.mp3","sents":[{"ar":"هل هذا هو كل شيء؟","zh":"这便是全部了吗？","t":[103,1866]}]},{"id":"ch13p47","audio":"ch13p47.mp3","sents":[{"ar":"ذلك كافٍ، قال رجل الأعمال.","zh":"那便足够了，商人说。","t":[103,2945]}]},{"id":"ch13p48","audio":"ch13p48.mp3","sents":[{"ar":"هذا مثير للاهتمام، فكر الأمير الصغير.","zh":"这倒有趣，小王子心想。","t":[103,4750]},{"ar":"هذا يُشبه الشعر.","zh":"这倒颇有诗意。","t":[4750,7092]},{"ar":"ليس هذا بأس.","zh":"但这并无大碍。","t":[7092,8434]}]},{"id":"ch13p49","audio":"ch13p49.mp3","sents":[{"ar":"الأمير الصغير يختلف عن البالغين في آرائه حول الأمور الكبرى.","zh":"小王子在事关重大之事上，所持见解与成人迥异。","t":[103,4892]}]},{"id":"ch13p50","audio":"ch13p50.mp3","sents":[{"ar":"أنا أعتني بوردة، أعطيها الماء كل يوم.","zh":"“我自己养着一朵花，”他继续与商人交谈，“每天都要给它浇水。”","t":[103,4737]},{"ar":"أمتلك ثلاثة براكين، ويجب عليّ تنظيفها كل أسبوع (بما في ذلك البركان الميت؛ لأن الحياة غير متوقعة).","zh":"我拥有三座火山，每周都要清理一番（包括那座死火山；毕竟，世事难料）。","t":[4737,15632]},{"ar":"جعل من بركاني تعبيرًا عن المعنى، وأعطى لوردتي قيمتها.","zh":"它使我的火山有了意义，也使我的玫瑰有了价值。","t":[15632,21868]},{"ar":"لكن للنجوم، أنت لا تستفيد من أي شيء...","zh":"但对星星来说，你毫无用处……","t":[21868,25671]}]},{"id":"ch13p51","audio":"ch13p51.mp3","sents":[{"ar":"رجل الأعمال استغرب ولم يجد كلامًا.","zh":"商人张口结舌，无言以对。","t":[103,4118]},{"ar":"الأمير الصغير غادر.","zh":"小王子离去了。","t":[4118,5790]}]},{"id":"ch13p52","audio":"ch13p52.mp3","sents":[{"ar":"الرؤساء بالفعل غريبون بشكل لا يُصدق، هو يمشي ويُتحدث لنفسه.","zh":"大人们真是奇怪得不可思议，他边走边自言自语。","t":[103,6050]}]}]},{"id":"ch14","title_ar":"الفصل الرابع عشر","title_en":"Chapter XIV","title_zh":"第 14 章","paras":[{"id":"ch14p00","audio":"ch14p00.mp3","sents":[{"ar":"النجم الخامس غريب للغاية.","zh":"第五颗星球颇为奇异。","t":[103,3434]},{"ar":"هذا هو أصغر كوكب في كل الكواكب.","zh":"那是所有星球中最小的一颗。","t":[3434,7368]},{"ar":"هذا الكوكب يكفيه ليعمل لامبه وأحد عمال الإنارة.","zh":"这颗星球仅能容纳一盏路灯和一个点灯人。","t":[7368,12382]},{"ar":"الأمير الصغير لم يستطع توضيح لماذا في كوكب معين في السماء، تكون هناك مصابيح الشارع وعامل الإنارة، بينما لا يوجد هناك سكان أو منازل.","zh":"小王子无法解释清楚，在某个星球上，天空中，为何会有路灯和点灯人的存在，而这个星球既无人居住，也无房屋。","t":[12382,24987]},{"ar":"لكن، قال للأمير الصغير لنفسه:","zh":"然而，他自言自语道：","t":[24987,28000]}]},{"id":"ch14p01","audio":"ch14p01.mp3","sents":[{"ar":"هذا المضاءة ربما تكون سخيفة بعض الشيء.","zh":"这盏灯的人或许有些荒唐。","t":[103,4579]},{"ar":"لكن هو لا يشبه الملك أو المرائي أو رجل الأعمال أو السكير في غروره.","zh":"但他并不像国王、自负的人、商人、酒鬼那样荒谬。","t":[4579,11237]},{"ar":"على الأقل عمله له معنى.","zh":"至少他的工作尚有意义。","t":[11237,14421]},{"ar":"يضيء مصباح الشارع، كأنه أتى بنجم إضافي إلى الحياة، أو زهرة.","zh":"他点亮街灯，仿佛又唤醒了一颗星星，或一朵花儿。","t":[14421,21118]},{"ar":"يطفئ النور، فيدخل الزهرة أو النجم إلى نومه.","zh":"他熄灭灯火，便让花儿或星星进入梦乡。","t":[21118,26000]},{"ar":"هذه مهنة جميلة.","zh":"这是一份美好的职业。","t":[26000,28658]},{"ar":"إذ كان جميلًا، فهو حقًا مفيد.","zh":"既然美好，便真正有益。","t":[28658,31605]}]},{"id":"ch14p02","audio":"ch14p02.mp3","sents":[{"ar":"لقد وصل إلى الكوكب وأدى تعظيمًا للعامل الإنارة بكل إجلال.","zh":"他抵达星球时，向点灯人毕恭毕敬地行礼。","t":[103,5024]}]},{"id":"ch14p03","audio":"ch14p03.mp3","sents":[{"ar":"صباح الخير.","zh":"早上好。","t":[103,2224]},{"ar":"لماذا قمت بإطفاء المصباح للتو؟","zh":"你为何刚刚熄了灯？","t":[2224,5053]}]},{"id":"ch14p04","audio":"ch14p04.mp3","sents":[{"ar":"هذا هو القانون.","zh":"这是规定。","t":[103,2513]},{"ar":"صباح الخير.","zh":"早上好。","t":[2513,3710]}]},{"id":"ch14p05","audio":"ch14p05.mp3","sents":[{"ar":"هذه الأوامر.","zh":"这是命令。","t":[103,1340]}]},{"id":"ch14p06","audio":"ch14p06.mp3","sents":[{"ar":"هذه أمر إطفاء الأضواء.","zh":"这是熄灯的命令。","t":[103,3197]},{"ar":"ليلة سعيدة.","zh":"晚安。","t":[3197,4540]}]},{"id":"ch14p07","audio":"ch14p07.mp3","sents":[{"ar":"جعل من جديد النور يلمع.","zh":"他又点亮了灯火。","t":[103,2195]}]},{"id":"ch14p08","audio":"ch14p08.mp3","sents":[{"ar":"لماذا أضأته ثانية؟","zh":"你为何又把灯点亮了？","t":[103,2011]}]},{"id":"ch14p09","audio":"ch14p09.mp3","sents":[{"ar":"هذه الأوامر.","zh":"这是命令。","t":[103,1340]}]},{"id":"ch14p10","audio":"ch14p10.mp3","sents":[{"ar":"لا أفهم! قال الأمير الصغير.","zh":"我不明白，小王子说。","t":[103,3408]}]},{"id":"ch14p11","audio":"ch14p11.mp3","sents":[{"ar":"ليس هناك شيء يمكن فهمه، قال عامل الإنارة.","zh":"“这没什么好理解的，”点灯人说。","t":[103,5066]},{"ar":"الأوامر هي الأوامر.","zh":"命令就是命令。","t":[5066,7750]},{"ar":"صباح الخير.","zh":"早上好。","t":[7750,8947]}]},{"id":"ch14p12","audio":"ch14p12.mp3","sents":[{"ar":"أطفأ النور.","zh":"他熄灭了灯火。","t":[103,1142]}]},{"id":"ch14p13","audio":"ch14p13.mp3","sents":[{"ar":"استخدمت منديل مزخرف بمربعات حمراء لتمسح جبيني.","zh":"他用手帕上的红格子方巾擦拭额头。","t":[103,4642]}]},{"id":"ch14p14","audio":"ch14p14.mp3","sents":[{"ar":"أنا أشتغل في مهنة سيئة.","zh":"我从事着一份糟糕的职业。","t":[103,3263]},{"ar":"كانت القواعد السابقة معقولة.","zh":"往昔的规定尚合情理。","t":[3263,6737]},{"ar":"في أشرق الفجر يُطفأ النور، وفي غروب الشمس يُشعل.","zh":"晨曦中熄灭灯火，暮色中复燃光亮。","t":[6737,12013]},{"ar":"لقد امتلكت راحة النهار بأكلمه وهدوء الليل.","zh":"我拥有了整个白天的闲暇与夜晚的安眠。","t":[12013,15816]}]},{"id":"ch14p15","audio":"ch14p15.mp3","sents":[{"ar":"منذ ذلك الحين، هل تغيرت القوانين؟","zh":"自那以后，规定已经改了？","t":[103,3418]}]},{"id":"ch14p16","audio":"ch14p16.mp3","sents":[{"ar":"النص لم يتم تغييره، قال عامل الإنارة.","zh":"规定并未更改，点灯人说道。","t":[103,4553]},{"ar":"هذه مأساة!","zh":"这是悲剧！","t":[4553,6671]},{"ar":"على مر السنوات، تزايدت سرعة دوران الكوكب دون أن تتغير الأوامر.","zh":"年复一年，星球转得越来越快，而命令却未曾更改。","t":[6671,12566]}]},{"id":"ch14p17","audio":"ch14p17.mp3","sents":[{"ar":"فقال الأمير الصغير: \"إذن؟\"","zh":"小王子问道：“那么呢？”","t":[103,2524]}]},{"id":"ch14p18","audio":"ch14p18.mp3","sents":[{"ar":"يُحولُ الكوكبُ الآن دورةً واحدةً في الدقيقة، لا أملك ثانيةً واحدةً من الراحة.","zh":"这颗星球现在每分钟转一圈，我连一秒钟的休息时间都没有。","t":[103,7697]},{"ar":"كل دقيقة يجب أن أقوم بإنارة وإطفاء مصباحي.","zh":"每分钟我都要点亮又熄灭我的灯。","t":[7697,12066]}]},{"id":"ch14p19","audio":"ch14p19.mp3","sents":[{"ar":"هذا مضحك للغاية!","zh":"这真有趣！","t":[103,2789]},{"ar":"هنا، اليوم يُعاد في دقيقة واحدة فقط.","zh":"在这里，一天仅有一分钟。","t":[2789,6882]}]},{"id":"ch14p20","audio":"ch14p20.mp3","sents":[{"ar":"ليس هذا ممتعًا على الإطلاق! قال عامل الإنارة.","zh":"这根本不有趣！点灯人说道。","t":[103,5737]},{"ar":"نحن نتحدث، وقد مر شهر بلا أن نلاحظ ذلك.","zh":"我们交谈之际，一个月已悄然流逝。","t":[5737,10000]}]},{"id":"ch14p21","audio":"ch14p21.mp3","sents":[{"ar":"شهر؟","zh":"一个月？","t":[103,827]}]},{"id":"ch14p22","audio":"ch14p22.mp3","sents":[{"ar":"نعم، شهرًا.","zh":"是的，一个月。","t":[103,2605]},{"ar":"ثلاثون دقيقة.","zh":"三十分钟。","t":[2605,4987]},{"ar":"ثلاثون يوماً.","zh":"三十天。","t":[4987,7263]},{"ar":"ليلة سعيدة.","zh":"晚安。","t":[7263,8606]}]},{"id":"ch14p23","audio":"ch14p23.mp3","sents":[{"ar":"جعل النور يضيء.","zh":"他又点亮了灯火。","t":[103,1655]}]},{"id":"ch14p24","audio":"ch14p24.mp3","sents":[{"ar":"يرى عامل الإنارة، يغمره الحب لولاء هذا الرجل الصادق في أداء واجبه.","zh":"他看着点灯人，心中涌起对这位忠于职责的灯夫的喜爱。","t":[103,6697]},{"ar":"يذكر، كان في الأيام الخالية يكفيه أن يتحرك للتمتع بمشاهدة الغروب، يريد أن يساعد صديقه.","zh":"他记得，往昔自己只是搬动椅子，就能观赏到日落；他想要帮助他的朋友。","t":[6697,15092]}]},{"id":"ch14p25","audio":"ch14p25.mp3","sents":[{"ar":"\"تعلم،\" يقول، \"أستطيع أن أخبرك بطريقة، يمكنك فيها أن تتعطل عندما تريد...\"","zh":"“你知道，”他道，“我可以告诉你一个方法，你想要休息的时候就能休息……”","t":[103,7445]}]},{"id":"ch14p26","audio":"ch14p26.mp3","sents":[{"ar":"أنا دائمًا ما أريد الراحة، يقول عامل الإنارة.","zh":"“我总是想休息，”点灯人说道。","t":[103,3932]}]},{"id":"ch14p27","audio":"ch14p27.mp3","sents":[{"ar":"يمكن للإنسان أن يكون مخلصًا وأبله في نفس الوقت.","zh":"人可以同时忠诚又懒惰。","t":[103,5066]},{"ar":"الأمير الصغير يكمل الشرح:","zh":"小王子继续解释道：","t":[5066,7329]}]},{"id":"ch14p28","audio":"ch14p28.mp3","sents":[{"ar":"كوكبك صغير جدًا، يكفيك ثلاث خطوات لتحطره","zh":"你的星球如此之小，只需迈三步就能绕它一周。","t":[103,4589]},{"ar":"فقط إذا سرت ببطء، يمكنك أن تكون دائمًا تحت ضوء الشمس","zh":"只需缓缓前行，便能始终沐浴在阳光下。","t":[4589,9497]},{"ar":"عندما تريد أن تستريح، استمر في السير... وستطول الأيام كما تحب","zh":"当你想休息时，就前行——日子便会如你所愿地延长。","t":[9497,16052]}]},{"id":"ch14p29","audio":"ch14p29.mp3","sents":[{"ar":"ذلك لم يساعدني كثيرًا، قال المضيء","zh":"这对我帮助不大，点灯人说道。","t":[103,3392]},{"ar":"حياتي كلها مكرسة للنوم، قال المضيء","zh":"生命中所爱唯有沉睡。","t":[3392,7103]}]},{"id":"ch14p30","audio":"ch14p30.mp3","sents":[{"ar":"أنت محظوظ جدًا، قال المضيء","zh":"那你真是不幸啊。","t":[103,2865]}]},{"id":"ch14p31","audio":"ch14p31.mp3","sents":[{"ar":"أنا محظوظ جدًا، قال المضيء","zh":"我真是倒霉。","t":[103,2589]},{"ar":"صباح الخير، قال المضيء وأطفأ النور","zh":"早上好。他熄灭了灯火。","t":[2589,5734]}]},{"id":"ch14p32","audio":"ch14p32.mp3","sents":[{"ar":"ألكس، الشخص الذي سيتعرض للسخرية من الجميع: الملك، الرجل الفارغ، السكير، رجل الأعمال، قال الأمير الصغير وهو يستمر في السير","zh":"那个人，”小王子在继续前行时自言自语，“那个人会被所有人嘲笑：国王、自负的人、酒鬼、商人。","t":[103,12418]},{"ar":"لكن هو الوحيد الذي لا يبدو لي سخيفًا، قال الأمير الصغير","zh":"然而，他是他们所有人中唯一一个在我看来并不荒谬的人。","t":[12418,16934]},{"ar":"ربما لأنه يفكر في أشياء أخرى، وليس في نفسه فقط، قال الأمير الصغير","zh":"或许是因为他在想别的事情，而非只顾自己。","t":[16934,23460]}]},{"id":"ch14p33","audio":"ch14p33.mp3","sents":[{"ar":"أنت الوحيد الذي يمكنني أن أكون صديقًا لك، قال الأمير الصغير وهو يتأمل","zh":"他叹了口气，又自言自语道：","t":[103,6195]}]},{"id":"ch14p34","audio":"ch14p34.mp3","sents":[{"ar":"لكن كوكبك صغير جدًا، قال الأمير الصغير","zh":"那他是他们所有人中唯一一个我可以成为朋友的人。","t":[103,3800]},{"ar":"لا يمكن أن يحتوي على شخصين، قال الأمير الصغير","zh":"然而，他的星球实在太小了。","t":[3800,7589]},{"ar":"لا أستطيع أن أعترف بذلك لنفسي، لكن أشعر بالأسف الشديد، قال الأمير الصغير وهو يتابع رحلته","zh":"这颗星球容不下两个人...","t":[7589,15973]}]},{"id":"ch14p35","audio":"ch14p35.mp3","sents":[{"ar":"أنا حزين جدًا لترك هذا الكوكب الذي يرى 1440 غروبًا كل يوم، قال الأمير الصغير وهو يتأمل","zh":"他不敢承认的是，他最遗憾的是即将离开这个星球，因为它每天都能目睹1440次日落。","t":[103,9405]}]}]},{"id":"ch15","title_ar":"الفصل الخامس عشر","title_en":"Chapter XV","title_zh":"第 15 章","paras":[{"id":"ch15p00","audio":"ch15p00.mp3","sents":[{"ar":"النجم السادس أكبر عشرة أضعاف من النجم السابق.","zh":"第六颗行星比上一颗大十倍。","t":[103,4961]},{"ar":"هذا الرجل العجوز يكتب كتبًا ضخمة.","zh":"这位老先生撰写着厚重的书籍。","t":[4961,8040]}]},{"id":"ch15p01","audio":"ch15p01.mp3","sents":[{"ar":"أوه، انظروا!","zh":"哦，看哪！","t":[103,2513]},{"ar":"أوه، انظروا! قد جاء المستكشف!","zh":"哦，看哪！来了一位探险家！","t":[2513,6289]}]},{"id":"ch15p02","audio":"ch15p02.mp3","sents":[{"ar":"الأمير الصغير جلس على الطاولة وهو يتنفس بعمق.","zh":"小王子坐在桌子上，喘着气。","t":[103,5171]},{"ar":"هو قد سار مئات الأميال، الطريق طويل جدًا!","zh":"他已跋涉千里，路途遥远！","t":[5171,9237]}]},{"id":"ch15p03","audio":"ch15p03.mp3","sents":[{"ar":"من أين جئت؟","zh":"您从何方来？","t":[103,1287]}]},{"id":"ch15p04","audio":"ch15p04.mp3","sents":[{"ar":"ما هذا الكتاب الكبير؟ سأل الأُمير الصغير.","zh":"那本厚重的书是何物？小王子问道。","t":[103,5303]},{"ar":"ماذا تفعل؟","zh":"您在做什么？","t":[5303,6486]}]},{"id":"ch15p05","audio":"ch15p05.mp3","sents":[{"ar":"أنا جغرافي، قال الرجل العجوز له.","zh":"“我是地理学家，”老先生对他说。","t":[103,3090]}]},{"id":"ch15p06","audio":"ch15p06.mp3","sents":[{"ar":"ماذا يفعل الجغرافي؟","zh":"小王子问：“地理学家是做什么的？”","t":[103,1945]}]},{"id":"ch15p07","audio":"ch15p07.mp3","sents":[{"ar":"عالم الجغرافيا هو العالم الذي يعرف مواقع البحار والأنهار والمدن والجبال والصحاري.","zh":"地理学家是知晓大海、江河、城镇、山脉和沙漠位置的学者。","t":[103,6932]}]},{"id":"ch15p08","audio":"ch15p08.mp3","sents":[{"ar":"هذا شيء مثير، يقول الأمير الصغير.","zh":"这倒很有趣，小王子说。","t":[103,4316]},{"ar":"أخيرًا، التقى برجل مهنة حقيقي! نظر حوله، يرى كوكب العالم بالجغرافيا.","zh":"终于，他遇见了一位真正有职业的人！他环顾四周，打量着地理学家的星球。","t":[4316,13145]},{"ar":"هذه الكوكب هي أكثر الكواكب التي رآها فخامة وأكثرها جلالًا.","zh":"这颗星球是他所见过的最为雄伟庄严的星球。","t":[13145,18448]}]},{"id":"ch15p09","audio":"ch15p09.mp3","sents":[{"ar":"إن كوكبك جميل جدًا.","zh":"您的星球真美。","t":[103,3105]},{"ar":"هل يوجد محيطات؟","zh":"这颗星球有海洋吗？","t":[3105,4619]}]},{"id":"ch15p10","audio":"ch15p10.mp3","sents":[{"ar":"\"لا أستطيع أن أعرف ذلك،\" قال عالم الجغرافيا.","zh":"“这我无法告知，”地理学家说。","t":[103,3958]}]},{"id":"ch15p11","audio":"ch15p11.mp3","sents":[{"ar":"أوه! الأمير الصغير شعر بالخيبة.","zh":"啊！小王子有些失望。","t":[103,4737]},{"ar":"هل هناك جبال على كوكبك؟","zh":"这颗星球有山脉吗？","t":[4737,6921]}]},{"id":"ch15p12","audio":"ch15p12.mp3","sents":[{"ar":"\"لا أستطيع أن أعرف ذلك،\" قال العالم الجغرافي.","zh":"“这我无法告知，”地理学家说。","t":[103,4037]}]},{"id":"ch15p13","audio":"ch15p13.mp3","sents":[{"ar":"مدن وأنهار وصحاري؟","zh":"城镇、河流、沙漠？","t":[103,2156]}]},{"id":"ch15p14","audio":"ch15p14.mp3","sents":[{"ar":"لا أستطيع الإجابة على ذلك.","zh":"这我也无法回答。","t":[103,2406]}]},{"id":"ch15p15","audio":"ch15p15.mp3","sents":[{"ar":"لكن أنت جغرافي!","zh":"但您是地理学家！","t":[103,1707]}]},{"id":"ch15p16","audio":"ch15p16.mp3","sents":[{"ar":"هذا ما قاله العالم الجغرافي.","zh":"“正是如此，”地理学家答道。","t":[103,3408]},{"ar":"أنا لست مستكشفًا.","zh":"但我不是探险家。","t":[3408,6026]},{"ar":"ليس هناك مستكشفون على كوكبي.","zh":"我的星球上没有一位探险家。","t":[6026,9658]},{"ar":"العالم الجغرافي ليس يخرج يحصي المدن والأنهار والجبال والمحيطات والمحيطات الكبرى والصحاري.","zh":"地理学家并非外出计数城镇、河流、山脉、海洋、大洋和沙漠。","t":[9658,17908]},{"ar":"عالم الجغرافيا لا يُسمح له بالتسكع.","zh":"地理学家太过重要，不容闲逛。","t":[17908,22000]},{"ar":"لم يغادر مكتبه قط.","zh":"他从未离开过他的办公桌。","t":[22000,24895]},{"ar":"استقبل في مكتبته المستكشف.","zh":"他在书房接待探险家。","t":[24895,28211]},{"ar":"سألهم، وثق ذكريات رحلاتهم.","zh":"他询问他们，记录下他们旅途中的回忆。","t":[28211,32263]},{"ar":"إذا أثار ذكرى أحد المستكشفين اهتمامه، فإن الجغرافي يأمر بإجراء تحقيق في أخلاقيات المستكشف.","zh":"若其中某位探险家的回忆引起了他的兴趣，地理学家便会下令调查那位探险者的道德品质。","t":[32263,40263]}]},{"id":"ch15p17","audio":"ch15p17.mp3","sents":[{"ar":"ما هو السبب؟","zh":"那是什么原因呢？","t":[103,1142]}]},{"id":"ch15p18","audio":"ch15p18.mp3","sents":[{"ar":"بسبب أن المستكشف الذي ينطق بالكذب يلحق الكوارث بكتب الجغرافي.","zh":"因为一个说谎的探险家会给地理学家的书籍带来灾难。","t":[103,6421]},{"ar":"لا يمكن أن يكون هناك مستكشف مدمن على الكحول.","zh":"一个酗酒的探险家也不行。","t":[6421,10526]}]},{"id":"ch15p19","audio":"ch15p19.mp3","sents":[{"ar":"لماذا هذا؟ سأل الأمير الصغير.","zh":"“这又是为什么？”小王子问道。","t":[103,3842]}]},{"id":"ch15p20","audio":"ch15p20.mp3","sents":[{"ar":"يرون السكارى الأشياء مضاعفة.","zh":"酗酒者所见皆为双重。","t":[103,3395]},{"ar":"ثم سجل الجغرافي جبالاً في مكان يحتوي على جبل واحد فقط.","zh":"于是地理学家会在只有一座山的地方记下两座山。","t":[3395,8526]}]},{"id":"ch15p21","audio":"ch15p21.mp3","sents":[{"ar":"أنا أعرف رجلاً سيكون مستكشفًا سيئًا.","zh":"我认识一个人，他会成为糟糕的探险家。","t":[103,3629]}]},{"id":"ch15p22","audio":"ch15p22.mp3","sents":[{"ar":"هذا ممكن.","zh":"这是可能的。","t":[103,2224]},{"ar":"ثم، عندما يتم إثبات أخلاق المستكشف، يأمر الجغرافي بالتحقيق في إكتشافاته.","zh":"于是，当探险者的道德品质得到证实，便下令调查他的发现。","t":[2224,9145]}]},{"id":"ch15p23","audio":"ch15p23.mp3","sents":[{"ar":"هل رأيتها؟","zh":"您去看过它吗？","t":[103,1103]}]},{"id":"ch15p24","audio":"ch15p24.mp3","sents":[{"ar":"لا.","zh":"不。","t":[103,1421]},{"ar":"هذا معقد جدًا.","zh":"这太过复杂了。","t":[1421,4118]},{"ar":"لكن يجب أن يقدم المستكشف الدليل.","zh":"但需探险家提供证据。","t":[4118,7961]},{"ar":"إذا كانت نتائج البحث تشمل اكتشاف جبل كبير، فإنه يجب إحضار حجارة كبيرة منه.","zh":"例如，如果探险的成果是发现了一座大山，便需从那里带回大石头。","t":[7961,15277]}]},{"id":"ch15p25","audio":"ch15p25.mp3","sents":[{"ar":"عالم الجغرافيا فجأة غضب.","zh":"地理学家突然激动起来。","t":[103,2497]}]},{"id":"ch15p26","audio":"ch15p26.mp3","sents":[{"ar":"لكنكـ - أنتـ من بعد البعيد!","zh":"但你——你从远方来！","t":[103,3645]},{"ar":"أنت مستكشف!","zh":"你是一位探险家！","t":[3645,5750]},{"ar":"يرجى وصف كوكبك.","zh":"请向我描述你的星球。","t":[5750,7395]}]},{"id":"ch15p27","audio":"ch15p27.mp3","sents":[{"ar":"عالم الجغرافيا فتح كتابه المسجل الكبير، وقطع قلمه الحاد.","zh":"地理学家翻开他那厚重的登记册，削尖了他的铅笔。","t":[103,6592]},{"ar":"يُسجل كلام المستكشف أولاً بكتابة بالقلم الهندي.","zh":"探险家的口述先以铅笔记录。","t":[6592,11776]},{"ar":"يُسجل بالحبر بعد تقديم أدلة من قبل المستكشف.","zh":"待探险家提供证据后，方以墨水记录之。","t":[11776,15855]}]},{"id":"ch15p28","audio":"ch15p28.mp3","sents":[{"ar":"أممم؟ سأل العالم الجغرافي بترقبه.","zh":"“嗯？”地理学家期待地问道。","t":[103,4211]}]},{"id":"ch15p29","audio":"ch15p29.mp3","sents":[{"ar":"أوه، لم يكن مكاني مثيرًا للاهتمام، قال الأمير الصغير.","zh":"哦，我那地方可没意思了，小王子说。","t":[103,6026]},{"ar":"كل هذا صغير جدًا.","zh":"这一切都如此渺小。","t":[6026,8763]},{"ar":"لدي ثلاثة براكين.","zh":"我有三座火山。","t":[8763,11592]},{"ar":"توجد بركانان نشطان، والآخر قد انطفأ.","zh":"两座火山活跃，另一座已熄灭。","t":[11592,16408]},{"ar":"لكن لا أحد يمكنه التنبؤ.","zh":"然而，无人能预知。","t":[16408,18711]}]},{"id":"ch15p30","audio":"ch15p30.mp3","sents":[{"ar":"لا يمكن لأحد التنبؤ، قال العالم الجغرافيا.","zh":"无人能预知，地理学家说。","t":[103,4023]}]},{"id":"ch15p31","audio":"ch15p31.mp3","sents":[{"ar":"لدي وردة.","zh":"我还有一朵花。","t":[103,1247]}]},{"id":"ch15p32","audio":"ch15p32.mp3","sents":[{"ar":"لا نصنف الزهور، يقول العالم الجغرافي.","zh":"我们不记录花朵，地理学家说。","t":[103,3695]}]},{"id":"ch15p33","audio":"ch15p33.mp3","sents":[{"ar":"لكن لماذا؟","zh":"那又是为何呢？","t":[103,2158]},{"ar":"هذه الزهرة هي أجمل شيء على كوكبي.","zh":"这朵花是我星球上最美的东西。","t":[2158,5342]}]},{"id":"ch15p34","audio":"ch15p34.mp3","sents":[{"ar":"نحن لا نكتبها، قال العالم الجغرافي، لأنها زائلتان.","zh":"“我们不记录它们，”地理学家说，“因为它们是转瞬即逝的。”","t":[103,5182]}]},{"id":"ch15p35","audio":"ch15p35.mp3","sents":[{"ar":"ما الذي يعنيه “الذروة”؟","zh":"那“转瞬即逝”又是什么意思？","t":[103,2194]}]},{"id":"ch15p36","audio":"ch15p36.mp3","sents":[{"ar":"العلم الجغرافي، يقول الجغرافي، \"هو أكثر الكتب اهتمامًا بالأمور الكبرى.","zh":"地理学，地理学家说，“是所有书籍中最关注重大事务的书籍。","t":[103,7250]},{"ar":"لن تزول أبدًا.","zh":"它们永远不会过时。","t":[7250,9526]},{"ar":"جبل يتحرك، نادرًا ما يحدث ذلك.","zh":"山移位，极为罕见。","t":[9526,13921]},{"ar":"موضوع جفاف البحر نادر جدًا.","zh":"海洋干涸之事，极为罕见。","t":[13921,17395]},{"ar":"نقوم بتسجيل الأبدية.","zh":"我们记载永恒之物。","t":[17395,19448]}]},{"id":"ch15p37","audio":"ch15p37.mp3","sents":[{"ar":"لكن البراكين الميتة قد تعود إلى الحياة، والأمير الصغير قطع كلامه.","zh":"但死火山也可能复苏，小王子打断了他的话。","t":[103,6895]},{"ar":"ما الذي يعنيه “الذوبان في اللحظة”؟","zh":"那“转瞬即逝”又是什么意思？","t":[6895,9737]}]},{"id":"ch15p38","audio":"ch15p38.mp3","sents":[{"ar":"البراكين هل تطفأت أم كانت نشطة، بالنسبة لنا لا فرق.","zh":"火山是否熄灭或活跃，对我们来说并无区别。","t":[103,5737]},{"ar":"الجبال، بالنسبة لنا، هي التي تعتبر مهمة.","zh":"山，对我们来说，才是重要的。","t":[5737,11158]},{"ar":"لن يتغير.","zh":"它不会改变。","t":[11158,12289]}]},{"id":"ch15p39","audio":"ch15p39.mp3","sents":[{"ar":"ما معنى 'الانقسام'؟ يستمر الأمير الصغير في السؤال، لأنه في حياته إذا ما سأل فإنه لا يترك السؤال بسهولة.","zh":"“‘转瞬即逝’是什么意思？”小王子继续追问，他一生中一旦提问，就绝不会轻易放手。","t":[103,10224]}]},{"id":"ch15p40","audio":"ch15p40.mp3","sents":[{"ar":"يُعني \"مُواجهة خطر الفناء السريع\".","zh":"意味着“面临迅速消失的危险”。","t":[103,3089]}]},{"id":"ch15p41","audio":"ch15p41.mp3","sents":[{"ar":"هل واجهت وردتي خطرًا سريعًا الانهيار؟","zh":"我的花儿面临迅速消失的危险吗？","t":[103,3261]}]},{"id":"ch15p42","audio":"ch15p42.mp3","sents":[{"ar":"بالطبع.","zh":"当然如此。","t":[103,906]}]},{"id":"ch15p43","audio":"ch15p43.mp3","sents":[{"ar":"أورديتي هي زائلة، يقول الأمير الصغير لنفسه، وهي ليست إلا بأربعة شوك لحماية نفسها من هذا العالم.","zh":"我的花儿是转瞬即逝的，小王子自言自语道，而她只有四根刺来保护自己抵御这个世界。","t":[103,9974]},{"ar":"أتركتها وحيدة على كوكبي.","zh":"我让她孤零零地留在了我的星球上。","t":[9974,12382]}]},{"id":"ch15p44","audio":"ch15p44.mp3","sents":[{"ar":"هذا هو أول مرّة شعر فيها بالندم.","zh":"那是他第一次感到悔恨。","t":[103,4224]},{"ar":"استعاد الأمل مرة أخرى","zh":"他再次鼓起勇气。","t":[4224,6342]}]},{"id":"ch15p45","audio":"ch15p45.mp3","sents":[{"ar":"أي مكان تنصحني بزيارتة الآن؟","zh":"您现在建议我去哪个地方呢？","t":[103,2944]}]},{"id":"ch15p46","audio":"ch15p46.mp3","sents":[{"ar":"الأرض، قال الجغرافي","zh":"地球，地理学家答道。","t":[103,1958]},{"ar":"يُعرف بسمعته الجيدة","zh":"它享有盛名。","t":[1958,4036]}]},{"id":"ch15p47","audio":"ch15p47.mp3","sents":[{"ar":"الأمير الصغير غادر، وهو يفكر في وردته","zh":"小王子离去，心中想着他的花儿。","t":[103,3839]}]}]},{"id":"ch16","title_ar":"الفصل السادس عشر","title_en":"Chapter XVI","title_zh":"第 16 章","paras":[{"id":"ch16p00","audio":"ch16p00.mp3","sents":[{"ar":"وكان الكوكب السابع هو الأرض","zh":"于是，第七颗行星便是地球。","t":[103,2405]}]},{"id":"ch16p01","audio":"ch16p01.mp3","sents":[{"ar":"الأرض ليست كوكباً عادياً","zh":"地球非同小可！","t":[103,2234]},{"ar":"فهناك مئة وأحد عشر ملكًا (من دون ذكر ملوك الزنوج، طبعًا)، وسبعة آلاف عالم جغرافياً، وتسعمئة ألف رجل أعمال، وسبعة ملايين ونصف مليون سكير، وثلاثمئة وأحد عشر مليون مرائي - وبكلمات أخرى، ألفا مليون راشد تقريبًا","zh":"可数的是，这里有111位国王（当然，别忘了，其中也有黑人国王），7000位地理学家，900万商人，7500万酒鬼，3.11亿自命不凡的人——也就是说，大约有2亿个大人。","t":[2234,24447]}]},{"id":"ch16p02","audio":"ch16p02.mp3","sents":[{"ar":"لإعطاء فكرة عن حجم الأرض، سأوضح أنه قبل اختراع الكهرباء، وعبر القارات الستة، كان ينبغي الاحتفاظ بجيش حقيقي من أربعة وأربعين ألفًا واثنين وخمسمئة وأحد عشر شخصًا يحافظون على مصابيح الشوارع","zh":"为了让你对地球的大小有个具体概念，我得告诉你，在电发明之前，整个六大洲需要维持一支由四十六万二千五百一十一个点灯人组成的真正大军。","t":[103,17302]}]},{"id":"ch16p03","audio":"ch16p03.mp3","sents":[{"ar":"من المسافة القصيرة، كانت النتيجة رائعة","zh":"从远处望去，那将是一场壮观的景象。","t":[103,3682]},{"ar":"حركات هذا الجيش ستكون كحركات فرقة الباليه","zh":"这支部队的动作将如同歌剧芭蕾舞般井然有序。","t":[3682,7511]},{"ar":"سيفضل على أولاً مشعلي مصابيح نيوزيلندا وأستراليا","zh":"新西兰和澳大利亚的提灯人将率先登场。","t":[7511,12103]},{"ar":"بعد أن أشعلوا مصابيحهم، ذهبوا للنوم","zh":"点亮了灯，他们便去安睡了。","t":[12103,15605]},{"ar":"ثم انضم مشعلي مصابيح الصين وسيبيريا إلى الرقصة، وتلاشوا عن الأنظار في الأجنحة","zh":"接着，中国和西伯利亚的提灯人加入舞步，随后他们也渐渐退入幕后。","t":[15605,22066]},{"ar":"ثم يأتي دور مشعلي مصابيح روسيا والهند وإفريقيا وأوروبا وأمريكا الجنوبية وأمريكا الشمالية","zh":"接着，轮到俄罗斯和印度群岛的提灯人，然后是非洲和欧洲的，接着是南美洲的，最后是北美洲的。","t":[22066,29974]},{"ar":"لم يخطئوا قط في ترتيب دخولهم إلى المسرح","zh":"他们的进场顺序从未出错。","t":[29974,33303]},{"ar":"إن هذا غير قابل للتصديق","zh":"壮观至极。","t":[33303,35789]}]},{"id":"ch16p04","audio":"ch16p04.mp3","sents":[{"ar":"حارس مصباح القطب الشمالي، وحارس مصباح القطب الجنوبي - فقط هذان الشخصان يمكنهما أن يعيشا حياة سعيدة مليئة بالكسل، فقد عملا مرتين في السنة","zh":"北极那盏灯的守护者，以及南极那盏灯的同事——唯有他们二人得以远离劳碌与烦恼：他们只需每年忙碌两次。","t":[103,12918]}]}]},{"id":"ch17","title_ar":"الفصل السابع عشر","title_en":"Chapter XVII","title_zh":"第 17 章","paras":[{"id":"ch17p00","audio":"ch17p00.mp3","sents":[{"ar":"عندما يريد المرء أن يبدو ذكياً، قد يبتعد قليلاً عن الحقيقة.","zh":"当人想卖弄聪明时，有时会稍稍偏离真相。","t":[103,6368]},{"ar":"لم أكن صادقًا تمامًا عندما تحدثت عن عامل الإنارة.","zh":"我讲述点灯人的事时，并未全然坦诚。","t":[6368,11382]},{"ar":"أدركت أنني قد أكون قد أكون قد ألحقتهؤلاء الذين لا يعرفون كوكبنا بأفكار خاطئة.","zh":"我意识到，我可能给那些不了解我们星球的人留下了错误的印象。","t":[11382,18908]},{"ar":"يُشغل الإنسان على الأرض مساحة صغيرة جدًا.","zh":"人在地球上占据的只是极小的一隅。","t":[18908,23513]},{"ar":"إذا رفع هذا المليارين ساكنًا وأجتمعوا كأنهم في اجتماع كبير، فإنهم يمكنهم بسهولة أن ينتشروا في ساحة عامة بطول عشرون ميلًا وعرض عشرون ميلًا.","zh":"若这二十亿居民都站立起来，且稍微挤一挤，就像他们参加大型集会那样，便能轻松地安置在二十英里长、二十英里宽的广场上。","t":[23513,37211]},{"ar":"البشر يمكنهم أن يتراكموا على جزيرة صغيرة في المحيط الهادئ.","zh":"人类可以堆在太平洋上的一座小岛上。","t":[37211,42263]}]},{"id":"ch17p01","audio":"ch17p01.mp3","sents":[{"ar":"بالطبع، الكبار لن يؤمنوا بهذا عندما تخبروهم عن ذلك.","zh":"大人们，当然，当你告诉他们这些时，他们不会相信的。","t":[103,5816]},{"ar":"هم يعتقدون بأنهم يحتلون فراغًا كبيرًا","zh":"他们自以为占据了极大的空间。","t":[5816,9158]},{"ar":"هم يعتقدون بأنهم مهمون كأشجار الباوباب.","zh":"他们自以为与猴面包树一样重要。","t":[9158,13671]},{"ar":"أنصحوهم بأن يفكروا بأنفسهم.","zh":"你们不妨建议他们自己算一算。","t":[13671,17342]},{"ar":"هم يفضلون الأرقام، وهذا يجعلهم سعداء.","zh":"他们偏爱数字，这会让他们高兴的。","t":[17342,22158]},{"ar":"لا تضيع وقتك في هذه المهمة الإضافية.","zh":"但别在这额外任务上浪费时间。","t":[22158,26329]},{"ar":"ليس هذا ضروري.","zh":"这并无必要。","t":[26329,28776]},{"ar":"أنت علي، أعلم، أمل في قلبي.","zh":"你对我，我深知，满怀信心。","t":[28776,32027]}]},{"id":"ch17p02","audio":"ch17p02.mp3","sents":[{"ar":"الأمير الصغير وصل إلى الأرض ووجد نفسه في دهشة شديدة من عدم رؤية أي إنسان.","zh":"小王子抵达地球时，惊讶地发现不见一人。","t":[103,8026]},{"ar":"بدأ يخشى أن يكون قد وصل إلى كوكب خاطئ، وفي تلك اللحظة، برزت حلقة ذهبية، ضوءها كالقمر، في الرمال.","zh":"他开始害怕自己来到了错误的星球，就在这时，一道金色螺旋，月光般的光辉，在沙地上闪现。","t":[8026,17777]}]},{"id":"ch17p03","audio":"ch17p03.mp3","sents":[{"ar":"مساء الخير، قال الأمير الصغير بتهذيب.","zh":"“晚上好，”小王子有礼地说。","t":[103,3497]}]},{"id":"ch17p04","audio":"ch17p04.mp3","sents":[{"ar":"مساء الخير، قال الثعبان.","zh":"“晚上好，”蛇说。","t":[103,2615]}]},{"id":"ch17p05","audio":"ch17p05.mp3","sents":[{"ar":"هذا الكوكب، أين هبطت؟ سأل الأمير الصغير.","zh":"这颗星球，我降落在了哪里？小王子问道。","t":[103,5026]}]},{"id":"ch17p06","audio":"ch17p06.mp3","sents":[{"ar":"هذه الأرض، وهذا أفريقيا، قال الثعبان.","zh":"这是地球；这是非洲，蛇回答说。","t":[103,3892]}]},{"id":"ch17p07","audio":"ch17p07.mp3","sents":[{"ar":"أوه...","zh":"啊！","t":[103,1487]},{"ar":"أليس هناك أحد على الأرض؟","zh":"地球上无人吗？","t":[1487,3579]}]},{"id":"ch17p08","audio":"ch17p08.mp3","sents":[{"ar":"هذه الصحراء.","zh":"这是沙漠。","t":[103,2158]},{"ar":"الصحراء لا تُجد فيها أثرًا للبشر.","zh":"沙漠中无人迹。","t":[2158,5921]},{"ar":"الأرض واسعة، قال الثعبان.","zh":"地球辽阔，蛇说。","t":[5921,8487]}]},{"id":"ch17p09","audio":"ch17p09.mp3","sents":[{"ar":"الأمير الصغير جلس على قطعة من الحجر ونظر إلى السماء.","zh":"小王子坐在一块石头上，仰望天空。","t":[103,4800]}]},{"id":"ch17p10","audio":"ch17p10.mp3","sents":[{"ar":"يُفكّر لنفسه: \"أريد أن أعرف، هل تُضاءة النجوم في السماء لكي نجد كل منا نجمةً خاصة به في يوم من الأيام.\"","zh":"他自言自语道：“我想知道，是不是星星在天空中被点亮，以便有一天我们都能找到属于自己的那颗。”","t":[103,9537]},{"ar":"أنظروا إلى كوكبي","zh":"看我的星球。","t":[9537,10853]},{"ar":"هي فوقنا مباشرة...","zh":"它就在我们头顶上方。","t":[10853,13395]},{"ar":"ها هو بعيد!","zh":"它多么遥远啊！","t":[13395,14460]}]},{"id":"ch17p11","audio":"ch17p11.mp3","sents":[{"ar":"هاهي جميلة.","zh":"它真美。","t":[103,2118]},{"ar":"لماذا جئت إلى هنا؟","zh":"你为何至此？","t":[2118,3856]}]},{"id":"ch17p12","audio":"ch17p12.mp3","sents":[{"ar":"الأمير الصغير قال: \"زهرتي تسبب لي بعض القلق.\"","zh":"“我那朵花让我挺烦恼的。”小王子说。","t":[103,4248]}]},{"id":"ch17p13","audio":"ch17p13.mp3","sents":[{"ar":"أوه! الثعبان قال.","zh":"啊！蛇说。","t":[103,2803]}]},{"id":"ch17p14","audio":"ch17p14.mp3","sents":[{"ar":"هم سكوتوا جميعًا.","zh":"他们俩都沉默了。","t":[103,1761]}]},{"id":"ch17p15","audio":"ch17p15.mp3","sents":[{"ar":"الأمير الصغير قال أخيرًا: \"أين الناس؟\"","zh":"小王子终于又开口说话：“人们在哪里？”","t":[103,3445]}]},{"id":"ch17p16","audio":"ch17p16.mp3","sents":[{"ar":"في الصحراء، شيء من الوحدة.","zh":"沙漠中，有点孤单。","t":[103,2616]}]},{"id":"ch17p17","audio":"ch17p17.mp3","sents":[{"ar":"في هذا العالم، يشعر الإنسان بالوحدة.","zh":"人在人间，亦感孤寂。","t":[103,3379]}]},{"id":"ch17p18","audio":"ch17p18.mp3","sents":[{"ar":"الأمير الصغير نظر إليه لفترة طويلة.","zh":"小王子凝视着他许久。","t":[103,3510]}]},{"id":"ch17p19","audio":"ch17p19.mp3","sents":[{"ar":"هذا الكائن حي مثير للاهتمام حقًا.","zh":"他终于说道：“你真是个有趣的动物。”","t":[103,4026]},{"ar":"أنت نحيف كشعرة من الإصبع.","zh":"你细得就像一根手指。","t":[4026,6473]}]},{"id":"ch17p20","audio":"ch17p20.mp3","sents":[{"ar":"لكن قوتي تفوق أصابع الملك.","zh":"但我的力量胜过国王的手指。","t":[103,2786]}]},{"id":"ch17p21","audio":"ch17p21.mp3","sents":[{"ar":"الأمير الصغير ابتسم.","zh":"小王子微笑了。","t":[103,1958]}]},{"id":"ch17p22","audio":"ch17p22.mp3","sents":[{"ar":"أنت لا تملك قوة كبيرة.","zh":"你并不怎么强大。","t":[103,3316]},{"ar":"ليس لديك قدم.","zh":"你连脚都没有。","t":[3316,5763]},{"ar":"لا يمكنك حتى السفر بعيدًا...","zh":"你甚至无法远行...","t":[5763,8211]}]},{"id":"ch17p23","audio":"ch17p23.mp3","sents":[{"ar":"أستطيع أخذك إلى مكان أبعد، يقول الثعبان.","zh":"我能带你走得更远，蛇说。","t":[103,4340]}]},{"id":"ch17p24","audio":"ch17p24.mp3","sents":[{"ar":"هو ملتصق حول قدم الأمير الصغير كحلقة من ذهب.","zh":"他如金镯般缠绕在小王子的脚踝上。","t":[103,4340]}]},{"id":"ch17p25","audio":"ch17p25.mp3","sents":[{"ar":"لا أستطيع أن أرسل فقط جملة واحدة من نصك كاملاً. يرجى تقديم جملة واحدة فقط من النص الذي ترغب في ترجمته إلى العربية.","zh":"无论我触及谁，都能将他送回他来的地方。","t":[103,12618]},{"ar":"لكن أنت نقي من دون شائبة، تأتي من قمة النجوم.","zh":"但你纯洁无瑕，来自星辰之巅。","t":[12618,16921]}]},{"id":"ch17p26","audio":"ch17p26.mp3","sents":[{"ar":"الأمير الصغير لم يتكلم.","zh":"小王子默然不语。","t":[103,2352]}]},{"id":"ch17p27","audio":"ch17p27.mp3","sents":[{"ar":"في هذا الأرض المصنوعة من الصخور، أنت ضعيف جدًا، يلفت انتباهي إليك.","zh":"在这花岗岩构成的地球上，你如此羸弱，令我心生怜悯。","t":[103,7158]},{"ar":"إذا كنت تُفكّر فيه ليلاً ونهارًا، وأنت تُريد العودة إلى كوكبك، سأُساعدك في ذلك.","zh":"若你日思夜想，渴望回到自己的星球，我终将助你一臂之力。","t":[7158,15711]},{"ar":"أستطيع","zh":"我能——","t":[15711,16579]}]},{"id":"ch17p28","audio":"ch17p28.mp3","sents":[{"ar":"أوه...","zh":"哦！","t":[103,1487]},{"ar":"أعلمُ نيتك، قال الأمير الصغير.","zh":"我深知你的心意，小王子说。","t":[1487,5303]},{"ar":"لمَ تتحدث بالألغاز دائمًا؟","zh":"但你为何总是说谜语？","t":[5303,7816]}]},{"id":"ch17p29","audio":"ch17p29.mp3","sents":[{"ar":"أحللها جميعًا","zh":"我解开所有的谜。","t":[103,1629]}]},{"id":"ch17p30","audio":"ch17p30.mp3","sents":[{"ar":"أصبحا صامتين","zh":"他们俩都沉默了。","t":[103,1497]}]}]},{"id":"ch18","title_ar":"الفصل الثامن عشر","title_en":"Chapter XVIII","title_zh":"第 18 章","paras":[{"id":"ch18p00","audio":"ch18p00.mp3","sents":[{"ar":"عبَرَ الأُمير الصغير الصحراء ولم يلتقي بزهرة.","zh":"小王子穿越沙漠，邂逅了那朵花。","t":[103,4553]},{"ar":"زهرة ثلاثة أوراق، عادية جدًا.","zh":"一朵三瓣的花，平凡无奇。","t":[4553,7842]}]},{"id":"ch18p01","audio":"ch18p01.mp3","sents":[{"ar":"صباح الخير، قال الأُمير الصغير.","zh":"早上好，小王子说。","t":[103,3050]}]},{"id":"ch18p02","audio":"ch18p02.mp3","sents":[{"ar":"صباح الخير، قالت الزهرة.","zh":"早上好，花儿说。","t":[103,2615]}]},{"id":"ch18p03","audio":"ch18p03.mp3","sents":[{"ar":"سأل الأُمير الصغير بلطف: أين البشر؟","zh":"小王子彬彬有礼地问道：“人在哪里？”","t":[103,3313]}]},{"id":"ch18p04","audio":"ch18p04.mp3","sents":[{"ar":"رأت الزهرة ذات مرة قافلة تمر.","zh":"那朵花儿曾见过一队商队经过。","t":[103,3182]}]},{"id":"ch18p05","audio":"ch18p05.mp3","sents":[{"ar":"أيها البشر؟ سألت الزهرة.","zh":"人吗？她应声而问。","t":[103,4276]},{"ar":"بالتقريب هناك ستة أو سبعة منهم.","zh":"世间大概有六七个这样的人。","t":[4276,7908]},{"ar":"كنت قد رأيتهم قبل سنوات.","zh":"几年前我曾见过他们。","t":[7908,11342]},{"ar":"لكن لا أحد يعرف أين يجدهم.","zh":"但无人能知晓他们在何方。","t":[11342,14882]},{"ar":"أبادتهم الرياح وأخذتهم بعيدًا.","zh":"风将他们吹散了。","t":[14882,18553]},{"ar":"ليس لديهم جذور تجعل حياتهم شاقة.","zh":"他们无根无基，生活因而颇为艰难。","t":[18553,21763]}]},{"id":"ch18p06","audio":"ch18p06.mp3","sents":[{"ar":"وداعًا، قال الأُمير الصغير.","zh":"再见，小王子说。","t":[103,2576]}]},{"id":"ch18p07","audio":"ch18p07.mp3","sents":[{"ar":"وداعًا، قالت الزهرة.","zh":"再见，花儿说。","t":[103,2168]}]}]},{"id":"ch19","title_ar":"الفصل التاسع عشر","title_en":"Chapter XIX","title_zh":"第 19 章","paras":[{"id":"ch19p00","audio":"ch19p00.mp3","sents":[{"ar":"بعد ذلك، تسلح الأمير الصغير جبلاً عالياً","zh":"此后，小王子攀登上一座高山。","t":[103,3695]},{"ar":"الجبال التي يعرفها هي الثلاثة براكين، طولها لا يتجاوز ركبتيه","zh":"他仅知的山只有那三座火山，它们的高度仅至他的膝盖。","t":[3695,9182]},{"ar":"استخدم البركان الخامد كراحة للقدمين","zh":"他用那座死火山当脚凳。","t":[9182,12300]},{"ar":"من قمة هذا الجبل العالي، يجب أن أرى في نظرة واحدة الكوكب والناس جميعاً","zh":"从这座高山之巅，他自语道：“我一眼便能将整个星球尽收眼底，以及所有人……”","t":[12300,18645]}]},{"id":"ch19p01","audio":"ch19p01.mp3","sents":[{"ar":"لكن ما رآه كانت قمم صخور حادة كالإبر","zh":"只见岩石尖峰，如针般锋利。","t":[103,3879]}]},{"id":"ch19p02","audio":"ch19p02.mp3","sents":[{"ar":"صباح الخير، قال بتهذيب","zh":"早上好，他礼貌地说。","t":[103,2668]}]},{"id":"ch19p03","audio":"ch19p03.mp3","sents":[{"ar":"صباح الخير - صباح الخير - صباح الخير، قال الصوت الإسناد","zh":"早上好——早上好——早上好，回声答道。","t":[103,5550]}]},{"id":"ch19p04","audio":"ch19p04.mp3","sents":[{"ar":"من أنت؟ سأل الأمير الصغير","zh":"你是谁？小王子问道。","t":[103,3302]}]},{"id":"ch19p05","audio":"ch19p05.mp3","sents":[{"ar":"من أنت - من أنت - من أنت، قال الصوت الإسناد","zh":"你是谁——你是谁——你是谁？回声应道。","t":[103,4406]}]},{"id":"ch19p06","audio":"ch19p06.mp3","sents":[{"ar":"كن صديقي، قال","zh":"做我的朋友吧。","t":[103,1668]},{"ar":"أنا وحيد تماماً، قال","zh":"我孤零零一人，他说。","t":[1668,3905]}]},{"id":"ch19p07","audio":"ch19p07.mp3","sents":[{"ar":"أنا وحيد تماماً - وحيد تماماً - وحيد تماماً، قال الصوت الإسناد","zh":"我孤零零一人——孤零零一人——孤零零一人，回声应道。","t":[103,6221]}]},{"id":"ch19p08","audio":"ch19p08.mp3","sents":[{"ar":"يا له من كوكب غريب، فكر في نفسه","zh":"多么奇特的星球啊，他想。","t":[103,3458]},{"ar":"جاف وجذب، قاسٍ ومرفوض","zh":"干涸而尖锐，严酷而拒人于千里之外。","t":[3458,5958]},{"ar":"الناس يفتقرون للخيال","zh":"人们缺乏想象力。","t":[5958,7813]},{"ar":"يكررون كل ما يقوله لهم الآخرون","zh":"他们重复着别人对他们的每一句话。","t":[7813,10603]},{"ar":"في كوكبي، لدي زهرة، كانت دائمًا هي التي تبدأ الحديث أولاً","zh":"在我的星球上，我有一朵花，她总是抢先开口……","t":[10603,16221]}]}]},{"id":"ch20","title_ar":"الفصل العشرون","title_en":"Chapter XX","title_zh":"第 20 章","paras":[{"id":"ch20p00","audio":"ch20p00.mp3","sents":[{"ar":"بعد مشية طويلة عبر الكثبان الرملية والصخور والثلوج، وجد الأمير الصغير أخيرًا طريقًا.","zh":"走过漫漫长路，穿过沙丘、岩石和雪地，小王子终于找到了一条道路。","t":[103,7484]}]},{"id":"ch20p01","audio":"ch20p01.mp3","sents":[{"ar":"كل الطرق تؤدي إلى منازل البشر.","zh":"所有道路都通向人类的居所。","t":[103,2761]}]},{"id":"ch20p02","audio":"ch20p02.mp3","sents":[{"ar":"صباح الخير، قال.","zh":"早上好，他道。","t":[103,2090]}]},{"id":"ch20p03","audio":"ch20p03.mp3","sents":[{"ar":"وقف أمام أرض زهرية.","zh":"他站在一片盛开的玫瑰花丛前。","t":[103,2116]}]},{"id":"ch20p04","audio":"ch20p04.mp3","sents":[{"ar":"قالت الوردة: صباح الخير.","zh":"玫瑰们道：“早上好。”","t":[103,2458]}]},{"id":"ch20p05","audio":"ch20p05.mp3","sents":[{"ar":"نظر إليها الأمير الصغير.","zh":"小王子凝望着她们。","t":[103,3197]},{"ar":"كلها تشبه زهرته.","zh":"她们都像他的那朵花。","t":[3197,4921]}]},{"id":"ch20p06","audio":"ch20p06.mp3","sents":[{"ar":"سأل بدهشة: من أنتم؟","zh":"他惊愕地问道：“你们是谁？”","t":[103,2497]}]},{"id":"ch20p07","audio":"ch20p07.mp3","sents":[{"ar":"قالت الوردة: نحن الوردة.","zh":"“我们是玫瑰，”玫瑰们说。","t":[103,2444]}]},{"id":"ch20p08","audio":"ch20p08.mp3","sents":[{"ar":"غمره الحزن.","zh":"他不禁悲伤不已。","t":[103,2276]},{"ar":"قالت له زهرته إنها مميزة في الكون.","zh":"他的玫瑰曾告诉他，她是宇宙间独一无二的存在。","t":[2276,6618]},{"ar":"في هذا الحديقة خمسة آلاف وردة، كلها متشابهة.","zh":"在这片花园里，五千朵玫瑰，无一例外。","t":[6618,11158]}]},{"id":"ch20p09","audio":"ch20p09.mp3","sents":[{"ar":"لو رأت ذلك، لكانت غاضبة.","zh":"她若看到这些，一定会非常生气。","t":[103,3658]},{"ar":"ستسعل وتسعل وتظاهر بأنها تموت.","zh":"她将痛苦地咳嗽，装作自己快要死去，以免被人嘲笑。","t":[3658,8079]},{"ar":"لابد أن أظاهر أنني أعتني بها، وإلا ستترك نفسها تموت.","zh":"我只好装作在悉心照料她，让她恢复生机——否则，为了自谦，她真的会让自己死去……","t":[8079,13355]}]},{"id":"ch20p10","audio":"ch20p10.mp3","sents":[{"ar":"كنت أعتقد أنني غني، ومعي وردة فريدة في العالم، ولكنني أملك وردة عادية.","zh":"我以为自己富足，却原来只拥有了一朵普普通通的玫瑰。","t":[103,8539]},{"ar":"وردة عادية، وثلاث براكين تصل إلى ركبتي، وربما تكون خامدة إلى الأبد.","zh":"一朵平凡的玫瑰，三座仅及膝高的火山——其中一座或许永远熄灭。","t":[8539,16500]},{"ar":"هذا لا يجعلني أكون أميرًا عظيمًا.","zh":"这并不能使我成为一位伟大的王子……","t":[16500,19382]}]},{"id":"ch20p11","audio":"ch20p11.mp3","sents":[{"ar":"استلقى على الأرض وبدأ يبكي.","zh":"他躺在草地上，失声痛哭。","t":[103,2537]}]}]},{"id":"ch21","title_ar":"الفصل الحادي والعشرون","title_en":"Chapter XXI","title_zh":"第 21 章","paras":[{"id":"ch21p00","audio":"ch21p00.mp3","sents":[{"ar":"ثم ظهر الثعلب.","zh":"那时，狐狸出现了。","t":[103,1563]}]},{"id":"ch21p01","audio":"ch21p01.mp3","sents":[{"ar":"صباح الخير، قال الثعلب.","zh":"早上好，狐狸说。","t":[103,2524]}]},{"id":"ch21p02","audio":"ch21p02.mp3","sents":[{"ar":"صباح الخير، الأمير الصغير يستعمل بتهذيب، ومع ذلك عندما التفت لم ير شيئًا.","zh":"早上好，小王子有礼地回应，尽管他转身四顾，却什么也没看见。","t":[103,7116]}]},{"id":"ch21p03","audio":"ch21p03.mp3","sents":[{"ar":"أنا تحت شجرة التفاح.","zh":"“我就在苹果树下。”","t":[103,2076]}]},{"id":"ch21p04","audio":"ch21p04.mp3","sents":[{"ar":"الأمير الصغير سأل: - من أنت؟ أنت جميل جدًا.","zh":"小王子问：“你是谁？你看起来真美。”","t":[103,5277]}]},{"id":"ch21p05","audio":"ch21p05.mp3","sents":[{"ar":"أنا ثعلب، يقول الثعلب.","zh":"“我是狐狸，”狐狸说。","t":[103,2340]}]},{"id":"ch21p06","audio":"ch21p06.mp3","sents":[{"ar":"تعال ولعب معي، اقترح الأمير الصغير.","zh":"来和我一起玩吧，小王子提议。","t":[103,4632]},{"ar":"أنا في حزن شديد.","zh":"我如此不快乐。","t":[4632,6263]}]},{"id":"ch21p07","audio":"ch21p07.mp3","sents":[{"ar":"لا أستطيع أن ألعب معك، قال الثعلب.","zh":"我不能与你玩耍，狐狸说。","t":[103,4263]},{"ar":"لم أُتُرّب بعد.","zh":"我尚未被驯服。","t":[4263,5579]}]},{"id":"ch21p08","audio":"ch21p08.mp3","sents":[{"ar":"أوه!","zh":"啊！","t":[103,1526]},{"ar":"يرجى التسامح، قال الأمير الصغير.","zh":"请见谅，小王子说。","t":[1526,4368]}]},{"id":"ch21p09","audio":"ch21p09.mp3","sents":[{"ar":"لكن بعد تفكير عميق، سأل مرة أخرى: ما الذي يعنيه 'التحضير'؟","zh":"但经过一番思考，他又问：“那‘驯服’究竟是什么意思？”","t":[103,6050]}]},{"id":"ch21p10","audio":"ch21p10.mp3","sents":[{"ar":"أنت لا تعيش هنا.","zh":"你并不住在这里。","t":[103,2566]},{"ar":"ماذا تبحث عن؟","zh":"你在寻找什么？","t":[2566,4013]}]},{"id":"ch21p11","audio":"ch21p11.mp3","sents":[{"ar":"أبحث عن البشر، قال الأمير الصغير.","zh":"我寻找人类，小王子说。","t":[103,4184]},{"ar":"ماذا تعني كلمة \"التربية\"؟","zh":"那“驯服”究竟是什么意思？","t":[4184,6764]}]},{"id":"ch21p12","audio":"ch21p12.mp3","sents":[{"ar":"الناس، قال الثعلب.","zh":"人们，狐狸说。","t":[103,2908]},{"ar":"هم يمتلكون البنادق ويصطادون.","zh":"他们有枪，他们打猎。","t":[2908,6474]},{"ar":"يصيب بالقلق.","zh":"令人心绪不宁。","t":[6474,8658]},{"ar":"يتبعون الدجاج أيضًا.","zh":"人们也养鸡。","t":[8658,11474]},{"ar":"هذه هي اهتماماتهم الوحيدة.","zh":"这些便是他们的唯一兴趣。","t":[11474,14816]},{"ar":"هل تبحث عن الدجاج؟","zh":"你在找鸡吗？","t":[14816,16500]}]},{"id":"ch21p13","audio":"ch21p13.mp3","sents":[{"ar":"“لا،” قال الأمير الصغير.","zh":"“不，”小王子说。","t":[103,3237]},{"ar":"أبحث عن أصدقاء","zh":"我在寻找朋友。","t":[3237,4592]},{"ar":"ما الذي يعنيه \"التربية\"؟","zh":"那“驯服”究竟是什么意思？","t":[4592,6711]}]},{"id":"ch21p14","audio":"ch21p14.mp3","sents":[{"ar":"هذا أمر يُغفل عنه غالبًا، قال الثعلب.","zh":"这是件常被忽视的行为，狐狸说。","t":[103,4671]},{"ar":"يُنشئ العلاقات.","zh":"建立联系。","t":[4671,6171]}]},{"id":"ch21p15","audio":"ch21p15.mp3","sents":[{"ar":"هل تبحث عن رابط؟","zh":"建立联系？","t":[103,1681]}]},{"id":"ch21p16","audio":"ch21p16.mp3","sents":[{"ar":"“هكذا فقط،” قال الثعلب.","zh":"“就如此，”狐狸说。","t":[103,3461]},{"ar":"لكني لست بحاجة لك.","zh":"对你而言，我不过是一个和无数小男孩无异的男孩。","t":[3461,6434]},{"ar":"وأنت أيضًا لست بحاجة لي.","zh":"我并不需要你。","t":[6434,9645]},{"ar":"لكني لست بحاجة لك.","zh":"你对我，也无需任何依赖。","t":[9645,12618]},{"ar":"لكني لست بحاجة لك.","zh":"对你而言，我不过是一只和其他成千上万的狐狸一样的狐狸。","t":[12618,15592]},{"ar":"لكن إذا ربيتني، سنحتاج بعضنا لبعض","zh":"但若你驯服了我，我们便彼此需要。","t":[15592,19171]},{"ar":"في عينيك، أنا مميز.","zh":"在你眼中，我是这世上独一无二的。","t":[19171,22263]},{"ar":"في عالمكم، سأكون مميزًا.","zh":"在你们的世界里，我将独一无二。","t":[22263,25197]}]},{"id":"ch21p17","audio":"ch21p17.mp3","sents":[{"ar":"بدأت أفهم، يقول الصغير.","zh":"我开始明白了，小王子说。","t":[103,3566]},{"ar":"هذه الزهرة...","zh":"那朵花儿……","t":[3566,5566]},{"ar":"أعتقد أنها تربيتني...","zh":"我想她已经驯服了我……","t":[5566,7632]}]},{"id":"ch21p18","audio":"ch21p18.mp3","sents":[{"ar":"“ذلك ممكن،” قال الثعلب.","zh":"“这可能，”狐狸说。","t":[103,3395]},{"ar":"على الأرض يمكن رؤية كل شيء.","zh":"地球上可见万物。","t":[3395,6039]}]},{"id":"ch21p19","audio":"ch21p19.mp3","sents":[{"ar":"أوه، لكن ليس هنا على الأرض! يقول الصغير.","zh":"哦，但这里可不是在地球上！小王子说。","t":[103,4815]}]},{"id":"ch21p20","audio":"ch21p20.mp3","sents":[{"ar":"بدى الثعلب مشوشًا، مهتمًا.","zh":"狐狸显得困惑，十分好奇。","t":[103,2958]}]},{"id":"ch21p21","audio":"ch21p21.mp3","sents":[{"ar":"في كوكب آخر؟","zh":"在另一个星球上？","t":[103,1524]}]},{"id":"ch21p22","audio":"ch21p22.mp3","sents":[{"ar":"نعم.","zh":"是的。","t":[103,774]}]},{"id":"ch21p23","audio":"ch21p23.mp3","sents":[{"ar":"هل هناك صيادون على هذا الكوكب؟","zh":"这颗星球上有猎人吗？","t":[103,2642]}]},{"id":"ch21p24","audio":"ch21p24.mp3","sents":[{"ar":"لا.","zh":"没有。","t":[103,524]}]},{"id":"ch21p25","audio":"ch21p25.mp3","sents":[{"ar":"أوه، هذا مثير!","zh":"哦，这很有意思！","t":[103,2816]},{"ar":"هل هناك دجاج هنا؟","zh":"这里有鸡吗？","t":[2816,4447]}]},{"id":"ch21p26","audio":"ch21p26.mp3","sents":[{"ar":"لا.","zh":"不。","t":[103,524]}]},{"id":"ch21p27","audio":"ch21p27.mp3","sents":[{"ar":"لا مكان كامل، نفخ الثعلب.","zh":"世间无完美，狐狸叹了口气。","t":[103,2879]}]},{"id":"ch21p28","audio":"ch21p28.mp3","sents":[{"ar":"حياتي بسيطة، يقول الثعلب.","zh":"但他又回到了自己的想法。","t":[103,2655]}]},{"id":"ch21p29","audio":"ch21p29.mp3","sents":[{"ar":"أقوم بقتل الدجاج، والبشر يقتلونني.","zh":"我的生活极为单调，狐狸说。","t":[103,4526]},{"ar":"أصطاد الدجاج، يصطادني البشر.","zh":"我捕猎鸡，人捕猎我。","t":[4526,8105]},{"ar":"وسأتميز بصوت قدمك المختلف عن الآخرين. إن صوت الأقدام الأخرى سيجعلني أسرع إلى تحت الأرض، أما صوت قدميك فسيناديني من جحري في الأرض بصوت الموسيقى، انظر وراءك! هل ترى حقول الذرة؟ لا أحتاج إلى تناول الخبز، والقمح ليس له فائدة لي، هذه الحقول لا تذكرني بشيء، وأرى ذلك محزنًا نوعًا ما!","zh":"所有的鸡都长得一样，所有的人也都一样。","t":[8105,37487]},{"ar":"لذلك، أكون مملًا بعض الشيء.","zh":"因此，我有些无聊。","t":[37487,41184]},{"ar":"لكن إن أتدربت علي، كأن تكون الشمس تضيء حياتي.","zh":"但若你驯服了我，就如同阳光照耀我的生命。","t":[41184,46829]},{"ar":"سأتمكن من تمييز صوت الأقدام المختلف.","zh":"我将能辨识出与众不同的脚步声。","t":[46829,51000]},{"ar":"صوت خطوات أخرى جعلني أسرع في الغوص تحت الأرض.","zh":"其他脚步声让我匆忙钻回地下。","t":[51000,55947]},{"ar":"أصوات خطواتك، كالموسيقى، ستقضي على نومي في الكهف.","zh":"你的脚步声，如同音乐，将把我从洞穴中唤醒。","t":[55947,61579]},{"ar":"ثم انظروا: هل ترى حقول القمح هناك؟","zh":"然后瞧：你看到那边的麦田了吗？","t":[61579,65829]},{"ar":"لا أأكل الخبز.","zh":"我不吃面包。","t":[65829,68000]},{"ar":"لم يكن القمح له أي فائدة لي.","zh":"麦子对我毫无用处。","t":[68000,71645]},{"ar":"مزرعة القمح تتحدث إليّ بصمت.","zh":"麦田对我默默无言。","t":[71645,75539]},{"ar":"هذا أمر محزن للغاية!","zh":"这实在可悲！","t":[75539,78526]},{"ar":"شعرك ذهبي اللون.","zh":"你的头发是金色的。","t":[78526,81132]},{"ar":"أريد أن أرى صورة سعيدة منك بعد أن تُدربني.","zh":"想见你驯服我后的美好景象吧！","t":[81132,85908]},{"ar":"الذهب الأصفر لقاح القمح يجعلني أفكر فيك.","zh":"麦子的金色会让我想起你。","t":[85908,90658]},{"ar":"أود أن أستمع إلى همسة الرياح في حقل القمح...","zh":"我愿倾听麦田中风的低语……","t":[90658,94145]}]},{"id":"ch21p30","audio":"ch21p30.mp3","sents":[{"ar":"الثعلب نظر إلى الأمير الصغير لفترة طويلة.","zh":"狐狸久久地凝视着小王子。","t":[103,3826]}]},{"id":"ch21p31","audio":"ch21p31.mp3","sents":[{"ar":"يرجى - تربني!","zh":"请——驯服我吧！","t":[103,1537]}]},{"id":"ch21p32","audio":"ch21p32.mp3","sents":[{"ar":"أنا مستعد جدًا.","zh":"我非常愿意。","t":[103,2684]},{"ar":"لكن ليست لدي الكثير من الوقت.","zh":"但我没有太多时间。","t":[2684,6184]},{"ar":"لدي أصدقاء أريد أن أتعرف عليهم، هناك كثير من الأمور التي أريد فهمها.","zh":"我有朋友要结识，有许多事要理解。","t":[6184,12816]}]},{"id":"ch21p33","audio":"ch21p33.mp3","sents":[{"ar":"ما يُتدرب عليه، يدرك قيمته الإنسانية.","zh":"驯服了的东西，人才懂得它的价值。","t":[103,4776]},{"ar":"لا يعد الناس لديهم وقت لفهم أي شيء.","zh":"人们不再有时间去理解任何事物。","t":[4776,9263]},{"ar":"يشترون من المتاجر الأشياء الجاهزة.","zh":"他们在商店里购买现成的东西。","t":[9263,13118]},{"ar":"لكن، لا يوجد محلات تبيع الصداقة في العالم، فيضيع الجميع أصدقائهم.","zh":"然而，世间并无店铺可售友谊，故人皆无友。","t":[13118,20553]},{"ar":"إذا كنت ترغب في السفر معي، اهتم بي……","zh":"若你愿与我结伴，驯服我吧……","t":[20553,24000]}]},{"id":"ch21p34","audio":"ch21p34.mp3","sents":[{"ar":"ماذا يجب أن أفعل لأتدرب عليك؟","zh":"我该做些什么，才能驯服你？","t":[103,3063]}]},{"id":"ch21p35","audio":"ch21p35.mp3","sents":[{"ar":"عليك أن تكون صبورًا جدًا، أجاب الثعلب.","zh":"你必须非常耐心，狐狸回答道。","t":[103,4618]},{"ar":"أولاً، ستجلس بعيدًا عني قليلًا - كما تفعل هنا - على العشب.","zh":"首先，你将坐在离我一段距离的地方——就像这样——在草地上。","t":[4618,11447]},{"ar":"أنا أنظر إليك بزاوية العين، لا تحتاج إلى قول كلمة.","zh":"我斜眼瞥着你，你不必说一句话。","t":[11447,17329]},{"ar":"كلام هو مصدر الالتباس","zh":"言语是误会的根源。","t":[17329,19158]},{"ar":"لكن يجب أن تقترب مني قليلاً كل يوم...","zh":"但你每天都要离我近一点……","t":[19158,22526]}]},{"id":"ch21p36","audio":"ch21p36.mp3","sents":[{"ar":"في اليوم التالي، جاء الأمير الصغير مجدداً","zh":"次日，小王子又来了。","t":[103,3629]}]},{"id":"ch21p37","audio":"ch21p37.mp3","sents":[{"ar":"من الأفضل أن تعود في نفس الوقت كل يوم، قال الثعلب","zh":"最好是同一时间回来，狐狸说。","t":[103,4234]},{"ar":"إذا جئت في الساعة الرابعة بعد الظهر، على سبيل المثال، سأبدأ في الشعور بالسعادة في الساعة الثالثة","zh":"若你下午四点钟来，那么从三点钟开始，我便开始感到幸福了。","t":[4234,11932]},{"ar":"مع مرور الوقت، ستصبح سعادتي أكثر إثارة","zh":"随着时光流逝，我的快乐将愈发浓烈。","t":[11932,15803]},{"ar":"في الساعة الرابعة، سأبدأ في الشعور بالقلق والتوتر","zh":"四点钟，我已开始焦虑不安，坐立难安。","t":[15803,19842]},{"ar":"سأريك كم أنا سعيد!","zh":"我将向你展示我是多么快乐！","t":[19842,22671]},{"ar":"لكن إذا جئت في أي وقت آخر، لن أعلم متى أستعد قلبي لمقابلتك...","zh":"但如果你随时来访，我就永远不知道何时我的心该准备好迎接你……","t":[22671,29671]},{"ar":"يجب أن تتبع طقوساً معينة...","zh":"必须遵守适当的仪式……","t":[29671,32263]}]},{"id":"ch21p38","audio":"ch21p38.mp3","sents":[{"ar":"سأل الأمير الصغير: 'ما هو الطقوس؟'","zh":"小王子问：“什么是仪式？”","t":[103,2997]}]},{"id":"ch21p39","audio":"ch21p39.mp3","sents":[{"ar":"هذه هي الأفعال التي تُنسى غالباً، قال الثعلب","zh":"那些也是常被忽视的行为，狐狸说。","t":[103,3932]},{"ar":"هي ما يجعل هذا اليوم مختلفاً عن الأيام الأخرى، والساعة عن الساعات الأخرى","zh":"它们使一日不同于他日，一小时不同于其他小时。","t":[3932,7800]},{"ar":"على سبيل المثال، لدي صيادون لديهم طقوسهم الخاصة بي","zh":"例如，我的猎人中有一种仪式。","t":[7800,14434]},{"ar":"كل يوم الخميس، يذهبون للرقص مع فتيات القرية","zh":"每周四，他们与村里的姑娘们共舞。","t":[14434,18697]},{"ar":"يوم الخميس هو يوم رائع بالنسبة لي!","zh":"星期四对我来说是个美好的日子！","t":[18697,22816]},{"ar":"أستطيع الذهاب حتى إلى البساتين","zh":"我可以一直走到葡萄园。","t":[22816,25158]},{"ar":"لكن إذا كانوا يرقصون في أي يوم آخر، فإن كل يوم يصبح مثل اليوم الآخر بالنسبة لي، ولن أستطيع الحصول على إجازة","zh":"但若猎人随时跳舞，那么每一天都将如同其他日子，我便永远没有假期可言。","t":[25158,34908]}]},{"id":"ch21p40","audio":"ch21p40.mp3","sents":[{"ar":"تغلب على الذئب الأمير الصغير","zh":"小王子驯服了狐狸。","t":[103,2221]},{"ar":"عندما اقترب وقت رحيله، قال الثعلب: 'أوه... سأبكي'","zh":"当离别的时刻临近——","t":[2221,7605]}]},{"id":"ch21p41","audio":"ch21p41.mp3","sents":[{"ar":"هذا خطأك، الأمير الصغير قال","zh":"啊，狐狸说，我要哭了。","t":[103,3156]}]},{"id":"ch21p42","audio":"ch21p42.mp3","sents":[{"ar":"لم أكن أريد أن أؤذيك، لكنك كنت تريد أن أتخلص من شعوري بالعزلة","zh":"是你的错，小王子说。","t":[103,6076]},{"ar":"نعم، مثل ذلك، قال الثعلب","zh":"我从未希望给你带来伤害；但你却想让我驯服你……","t":[6076,9037]}]},{"id":"ch21p43","audio":"ch21p43.mp3","sents":[{"ar":"لكن الآن ستبكي! قال الأمير الصغير","zh":"是的，是这样的，狐狸说。","t":[103,4131]}]},{"id":"ch21p44","audio":"ch21p44.mp3","sents":[{"ar":"نعم، مثل ذلك، قال الثعلب","zh":"但你现在要哭了！小王子说。","t":[103,3182]}]},{"id":"ch21p45","audio":"ch21p45.mp3","sents":[{"ar":"ليس له أي فائدة لك","zh":"是的，是这样的，狐狸说。","t":[103,2168]}]},{"id":"ch21p46","audio":"ch21p46.mp3","sents":[{"ar":"إنها تجعلني سعيداً، قال الثعلب، لأن لون حقول القمح","zh":"对你毫无益处。","t":[103,5234]}]},{"id":"ch21p47","audio":"ch21p47.mp3","sents":[{"ar":"ثم أضاف: 'ذهب وألق نظرة على الورود، وستفهم أن وردتك هي حقاً فريدة في العالم، ثم تعود لتقول لي وداعاً، وسأقدم لك هدية سرية'","zh":"“它让我感到愉悦，”狐狸说，“因为麦田的颜色。”然后他又补充道：","t":[103,13169]}]},{"id":"ch21p48","audio":"ch21p48.mp3","sents":[{"ar":"أنظر إلى الوردة مرة أخرى.","zh":"再去看看那些玫瑰。","t":[103,3474]},{"ar":"أمكِ الوردة، في هذا العالم لا توجد مثيلات لها.","zh":"你的玫瑰，在这世上独一无二。","t":[3474,8487]},{"ar":"ثم يودعني ويغادر، سأقدم لك سرًا كهدية.","zh":"然后回来向我告别，我会送你一个秘密作为礼物。","t":[8487,13026]}]},{"id":"ch21p49","audio":"ch21p49.mp3","sents":[{"ar":"الأمير الصغير يغادر، ينظر إلى الوردة مرة أخرى.","zh":"小王子离去，再次凝视着玫瑰。","t":[103,4694]}]},{"id":"ch21p50","audio":"ch21p50.mp3","sents":[{"ar":"أنت ووردتك تختلفان عن بعض.","zh":"你那朵玫瑰与我截然不同。","t":[103,3711]},{"ar":"ليس لديك شيء.","zh":"你尚无所有。","t":[3711,6132]},{"ar":"لا أحد يُسخّر نفسه لك، وأنت لم تسخّر نفسك لأحد.","zh":"无人驯服于你，你亦未驯服他人。","t":[6132,11842]},{"ar":"أنت مثل الثعلب الذي التقيت به في البداية.","zh":"你就像我最初遇见的那只狐狸。","t":[11842,16079]},{"ar":"هو مجرد ثعلب مثل الآلاف من الثعالب الآخرين.","zh":"他只是一只和其他成千上万的狐狸一样的狐狸。","t":[16079,20842]},{"ar":"لكن هو صار صديقي، والآن هو الفريد من نوعه في هذا العالم.","zh":"但他已成了我的朋友，现在他是这世上独一无二的。","t":[20842,26000]}]},{"id":"ch21p51","audio":"ch21p51.mp3","sents":[{"ar":"الورود تشعر بالاحراج الشديد.","zh":"玫瑰们感到非常尴尬。","t":[103,2629]}]},{"id":"ch21p52","audio":"ch21p52.mp3","sents":[{"ar":"أنت جميلة، لكنك فارغة.","zh":"你美丽，却空洞无物。","t":[103,3618]},{"ar":"الناس لن يموتوا من أجلك.","zh":"人们不会为你而死。","t":[3618,6553]},{"ar":"بالطبع، سيظن المرور العادي أن وردتي لي هي مثل وردتك أنت - وردتي التي تنتمي لي.","zh":"当然，一个普通的过路人会认为我的玫瑰和你的一样——那朵属于我的玫瑰。","t":[6553,14776]},{"ar":"لكن، بفضل نفسها، هي أهم من جميع الورود المئات التي تُزرع هنا: لأنني من يرشها بالماء؛ لأنني أضع عليها غطاء الزجاج؛ لأنني أحميها من الرياح والطقس العاصف؛ لأنني أقتل اليرقات التي تُهاجمها (باستثناء تلك القليلة التي نتركها لتتحول إلى فراشات)； لأنني أستمع إلى شكواها أو فخرها، وأحياناً حتى عندما تكون صامتة.","zh":"然而，仅凭她自身，她比你们所有数百朵玫瑰都要重要：因为是我为她浇水；是我为她罩上玻璃罩；是我为她挡风遮雨；是我为她杀死了毛毛虫（除了我们留下变成蝴蝶的那两三只）；是我倾听她的抱怨，或她的自夸，有时甚至在她默默无言时。","t":[14776,44447]},{"ar":"لأنها وردتي.","zh":"因为她是我玫瑰。","t":[44447,45947]}]},{"id":"ch21p53","audio":"ch21p53.mp3","sents":[{"ar":"عاد إلى الثعلب.","zh":"他回到狐狸那里。","t":[103,1445]}]},{"id":"ch21p54","audio":"ch21p54.mp3","sents":[{"ar":"مع السلامة، قال.","zh":"再见，他说。","t":[103,1945]}]},{"id":"ch21p55","audio":"ch21p55.mp3","sents":[{"ar":"وداعاً، قال الثعلب.","zh":"再见，狐狸说。","t":[103,2974]},{"ar":"بقلب النظر، يمكن النظر بوضوح؛ الأشياء الأساسية لا يمكن رؤيتها بالعين.","zh":"用心去看，才能看得真切；本质的东西，肉眼是看不见的。","t":[2974,10000]}]},{"id":"ch21p56","audio":"ch21p56.mp3","sents":[{"ar":"ما هو جوهري، لا يمكن رؤيته بالعين، والأمير الصغير يتردد في قوله حتى يتذكره في قلبه.","zh":"本质的东西，肉眼难辨，小王子反复念诵，以便牢记于心。","t":[103,8563]}]},{"id":"ch21p57","audio":"ch21p57.mp3","sents":[{"ar":"أنت تُضيع وقتك في زهرةك، وتجعلها تُصبح مهمة جدًا.","zh":"你为你的玫瑰浪费的时间，使你的玫瑰变得如此重要。","t":[103,5247]}]},{"id":"ch21p58","audio":"ch21p58.mp3","sents":[{"ar":"أنا أضيع وقتي لأجل وردتي - يقول الأمير الصغير، لأتأكد من أنني سأتذكر ذلك.","zh":"“我为我的玫瑰浪费的时间——”小王子说，以便确保自己能记住。","t":[103,7458]}]},{"id":"ch21p59","audio":"ch21p59.mp3","sents":[{"ar":"الناس قد نسوا هذه الحقيقة، قال الثعلب.","zh":"人们已遗忘这一真理，狐狸说。","t":[103,4487]},{"ar":"لا تنسى.","zh":"但你切莫忘记。","t":[4487,6276]},{"ar":"ما أن تُطيِّب شيئًا، تكون مُسؤولًا عنه إلى الأبد.","zh":"你一旦驯服了什么，便永远对其负责。","t":[6276,11289]},{"ar":"عليك أن تكون مسؤولاً عن وردتك...","zh":"你须对你的玫瑰负责……","t":[11289,13921]}]},{"id":"ch21p60","audio":"ch21p60.mp3","sents":[{"ar":"أنا مسؤول عن وردتي، يقول الأمير الصغير مرارًا وتكرارًا، ليتذكر ذلك في قلبه.","zh":"我为我的玫瑰负责，小王子反复说道，以便牢记于心。","t":[103,7142]}]}]},{"id":"ch22","title_ar":"الفصل الثاني والعشرون","title_en":"Chapter XXII","title_zh":"第 22 章","paras":[{"id":"ch22p00","audio":"ch22p00.mp3","sents":[{"ar":"صباح الخير، قال الأمير الصغير.","zh":"早上好，小王子说。","t":[103,2997]}]},{"id":"ch22p01","audio":"ch22p01.mp3","sents":[{"ar":"صباح الخير، قال عامل الإشارة.","zh":"早上好，扳道工说。","t":[103,2971]}]},{"id":"ch22p02","audio":"ch22p02.mp3","sents":[{"ar":"الأمير الصغير سأل: ماذا تفعل هنا؟","zh":"小王子问道：“你在此做什么？”","t":[103,3353]}]},{"id":"ch22p03","audio":"ch22p03.mp3","sents":[{"ar":"أنا أقوم بتنظيم المسافرين في مجموعات من ألف، يقول عامل الإشارة.","zh":"“我负责把旅客分成一千人一组的批次，”扳道工说。","t":[103,6618]},{"ar":"أنا أدير قطاراتهم، أحيانًا إلى اليمين وأحيانًا إلى اليسار.","zh":"我调度着载着他们的火车，时而向右，时而向左。","t":[6618,11790]}]},{"id":"ch22p04","audio":"ch22p04.mp3","sents":[{"ar":"عربة سريعة مضيئة كالنور تمر كالرعد، تهز بيت عامل الإشارة.","zh":"一列灯火通明的快车如雷霆般轰鸣而过，震得扳道工的小屋摇摇欲坠。","t":[103,5958]}]},{"id":"ch22p05","audio":"ch22p05.mp3","sents":[{"ar":"هم يسرعون، قال الأمير الصغير.","zh":"他们匆匆忙忙，小王子说。","t":[103,3895]},{"ar":"ماذا يبحثون عنه؟","zh":"他们在寻找什么？","t":[3895,5474]}]},{"id":"ch22p06","audio":"ch22p06.mp3","sents":[{"ar":"ليس حتى قائد القطار يعرف نفسه، يقول عامل الإشارة.","zh":"连火车头上的司机也弄不清楚，”扳道工说。","t":[103,4747]}]},{"id":"ch22p07","audio":"ch22p07.mp3","sents":[{"ar":"القطار السريع المضيء بالأضواء يسير في الاتجاه المعاكس بسرعة هائلة.","zh":"第二列灯火通明的快车在相反方向呼啸而过。","t":[103,5550]}]},{"id":"ch22p08","audio":"ch22p08.mp3","sents":[{"ar":"هل رجعوا الآن؟ سأل الأمير الصغير.","zh":"他们已经回来了吗？小王子问道。","t":[103,3894]}]},{"id":"ch22p09","audio":"ch22p09.mp3","sents":[{"ar":"ليسوا نفس الأشخاص، يقول عامل القضبان.","zh":"这不是同一批人，扳道工说。","t":[103,4487]},{"ar":"هذا هو القطار المزدوج.","zh":"这是对开的火车。","t":[4487,6539]}]},{"id":"ch22p10","audio":"ch22p10.mp3","sents":[{"ar":"هل هم غير راضين عن موطنهم؟ سأل الأمير الصغير.","zh":"他们对自己的居住地不满意吗？小王子问道。","t":[103,5039]}]},{"id":"ch22p11","audio":"ch22p11.mp3","sents":[{"ar":"هو دائمًا ما يشعر بأن المكان الذي هو فيه ليس كما يجب، يقول عامل الإشارة.","zh":"他总觉得自己所在的地方不尽人意，扳道工说。","t":[103,6642]}]},{"id":"ch22p12","audio":"ch22p12.mp3","sents":[{"ar":"عبرت قطار مضيء بالأضواء كالبرق يهتز كالرعد.","zh":"又有一列灯火通明的快车如雷鸣般轰鸣而过。","t":[103,4208]}]},{"id":"ch22p13","audio":"ch22p13.mp3","sents":[{"ar":"هل هم يتعقبون المسافرين الأوائل؟ قال الأمير الصغير.","zh":"他们是在追赶第一批旅客吗？小王子质问道。","t":[103,5394]}]},{"id":"ch22p14","audio":"ch22p14.mp3","sents":[{"ar":"هم لا يبحثون عن شيء على الإطلاق، يقول عامل الإشارة.","zh":"他们根本无所追寻，扳道工说。","t":[103,5447]},{"ar":"في القاطرة، يغفو بعضهم، أو إذا لم يغفو، فيتمنعون من السعال.","zh":"他们在车厢里昏昏欲睡，或者若非沉睡，便在打哈欠。","t":[5447,12632]},{"ar":"فقط الأطفال يضعون أنوفهم على زجاج النوافذ.","zh":"只有孩子们才把鼻子贴在窗玻璃上。","t":[12632,16369]}]},{"id":"ch22p15","audio":"ch22p15.mp3","sents":[{"ar":"فقط الأطفال يعرفون ما يبحثون عنه، يقول الأمير الصغير.","zh":"只有孩子知道他们在寻找什么，小王子说。","t":[103,5789]},{"ar":"هم يضيعون الوقت في الدمى، التي تصبح لهم مهمة جدًا؛ إذا ما أُخذت منها، يبكون…","zh":"他们把时间浪费在布娃娃身上，那对它们来说变得极其重要；要是有人把它夺走，他们就会哭鼻子……","t":[5789,13224]}]},{"id":"ch22p16","audio":"ch22p16.mp3","sents":[{"ar":"هم محظوظون، قال عامل الإشارة.","zh":"他们是幸运的，扳道工说。","t":[103,2971]}]}]},{"id":"ch23","title_ar":"الفصل الثالث والعشرون","title_en":"Chapter XXIII","title_zh":"第 23 章","paras":[{"id":"ch23p00","audio":"ch23p00.mp3","sents":[{"ar":"صباح الخير، قال الأمير الصغير","zh":"早上好，小王子说。","t":[103,2971]}]},{"id":"ch23p01","audio":"ch23p01.mp3","sents":[{"ar":"صباح الخير، قال رجل الأعمال","zh":"早上好，商人说。","t":[103,2642]},{"ar":"هذا رجل الأعمال يبيع حبوبًا تُساعد على الإشباع","zh":"这是一位售卖解渴药丸的商人。","t":[2642,6353]},{"ar":"فإن ابتلع المرء حبة مرة في الأسبوع، لم يعد بحاجة إلى شرب أي شيء آخر","zh":"只需每周吞下一颗药丸，便无需再饮任何东西。","t":[6353,12721]}]},{"id":"ch23p02","audio":"ch23p02.mp3","sents":[{"ar":"لماذا تبيع هذه الحبوب؟ سأل الأمير الصغير","zh":"“你为何卖这种药？”小王子问道。","t":[103,4710]}]},{"id":"ch23p03","audio":"ch23p03.mp3","sents":[{"ar":"لأنها توفر الكثير من الوقت، قال رجل الأعمال","zh":"“因为这样可以节省大量时间，”商人说。","t":[103,4024]},{"ar":"لقد قام الخبراء بتحليل ذلك","zh":"专家们已做过计算。","t":[4024,6366]},{"ar":"فكل أسبوع، هذه الحبوب تساعدك على توفير خمس وثلاثين دقيقة","zh":"每周，这些药丸能为你节省五十三分钟。","t":[6366,12339]}]},{"id":"ch23p04","audio":"ch23p04.mp3","sents":[{"ar":"كيف يمكنني استغلال هذه الخمس وثلاثين دقيقة؟","zh":"我该如何利用这五十三分钟？","t":[103,4063]}]},{"id":"ch23p05","audio":"ch23p05.mp3","sents":[{"ar":"ما يحلو لك أن تفعله...","zh":"你喜欢做什么……","t":[103,1826]}]},{"id":"ch23p06","audio":"ch23p06.mp3","sents":[{"ar":"أما بالنسبة لي، قال الأمير الصغير، لو كان لدي خمس وثلاثون دقيقة لأقضيها كيفما أريد، لسار ببطء نحو عين من الماء العذب...","zh":"“至于我，”小王子自言自语道，“若我有五十三分钟可以随心所欲地度过，我便悠然地向一泓清泉走去。”","t":[103,11379]}]}]},{"id":"ch24","title_ar":"الفصل الرابع والعشرون","title_en":"Chapter XXIV","title_zh":"第 24 章","paras":[{"id":"ch24p00","audio":"ch24p00.mp3","sents":[{"ar":"في الصحراء، تحطمت طائرتي بعد ثمانية أيام، وأنا كنت أستمع إلى قصة التاجر وأنا أتناول آخر قطرة من مائي.","zh":"沙漠中我的飞机失事已第八天，我边听商人的故事边饮尽了我最后一滴水。","t":[103,9865]}]},{"id":"ch24p01","audio":"ch24p01.mp3","sents":[{"ar":"أنا: “أوه! ذكرياتك رائعة جدًا، لكن لم أتمكن من إصلاح طائرتي بعد. لم يعد لدي ماء للشرب، وسأكون سعيدًا أيضًا إذا استطعت المشي ببطء شديد نحو عين ماء!”","zh":"“啊，”我对小王子说，“你的这些回忆真是迷人；不过，我的飞机还没修好，水也喝光了；若能悠闲地走向一汪清泉，我也会很快乐的！”","t":[103,15987]}]},{"id":"ch24p02","audio":"ch24p02.mp3","sents":[{"ar":"صديقي الثعلب- قال للأمير الصغير","zh":"我的朋友狐狸——小王子对我说。","t":[103,3419]}]},{"id":"ch24p03","audio":"ch24p03.mp3","sents":[{"ar":"يا الطفل العزيز، هذا لا علاقة له بالثعلب!","zh":"亲爱的孩子，这已与狐狸无关了！","t":[103,3826]}]},{"id":"ch24p04","audio":"ch24p04.mp3","sents":[{"ar":"لماذا لا يمكن؟","zh":"为何不可？","t":[103,1563]}]},{"id":"ch24p05","audio":"ch24p05.mp3","sents":[{"ar":"لأنني سأموت بالعطش...","zh":"因为我即将渴死……","t":[103,2129]}]},{"id":"ch24p06","audio":"ch24p06.mp3","sents":[{"ar":"لم يفهم كلامي، ولكن أجاب:","zh":"他并未理解我的话，却回答道：","t":[103,2787]}]},{"id":"ch24p07","audio":"ch24p07.mp3","sents":[{"ar":"حظيت بصديق، حتى ولو كنت على حافة الموت، فهذا أمر جيد.","zh":"有了一位朋友，即便是在命悬一线之际，也是一件好事。","t":[103,6947]},{"ar":"أنا سعيد جدًا بوجود ثعلب كصديق...","zh":"我很高兴能有一位狐狸作为朋友……","t":[6947,10158]}]},{"id":"ch24p08","audio":"ch24p08.mp3","sents":[{"ar":"لم يكن يستطيع التخيل خطورة الخطر.","zh":"他无法想象危险的严重。","t":[103,4158]},{"ar":"لم يكن قد جرب طعم الجوع أو العطش.","zh":"他从未尝过饥饿或口渴的滋味。","t":[4158,8039]},{"ar":"يحتاج إلى القليل من ضوء الشمس فقط……","zh":"他只需一点阳光便足矣……","t":[8039,10881]}]},{"id":"ch24p09","audio":"ch24p09.mp3","sents":[{"ar":"نظر إلي واستجاب لأفكاري.","zh":"他凝视着我，对我的想法回应道：","t":[103,2510]}]},{"id":"ch24p10","audio":"ch24p10.mp3","sents":[{"ar":"أنا أيضًا عطشان...","zh":"我也渴了……","t":[103,2474]},{"ar":"لنذهب ونبحث عن بئر……","zh":"让我们去找一口井……","t":[2474,4408]}]},{"id":"ch24p11","audio":"ch24p11.mp3","sents":[{"ar":"رفعت يدي بلفظ تعب","zh":"我打了个倦怠的手势。","t":[103,1866]},{"ar":"البحث عن بئر في وسط الصحراء العريضة هو أمر سخيف للغاية.","zh":"在沙漠的浩瀚中随意寻找一口井，实在荒谬至极。","t":[1866,7724]},{"ar":"ومع ذلك، نحن قد انطلقنا.","zh":"然而，我们还是出发了。","t":[7724,10421]}]},{"id":"ch24p12","audio":"ch24p12.mp3","sents":[{"ar":"نمضي بلا حديث لعدة ساعات، تنزلق الظلام، وتبرز النجوم ببطء.","zh":"我们默默前行数小时，夜幕降临，星辰渐次闪烁。","t":[103,7105]},{"ar":"العطش جعلني أتحرق قليلاً، ونظرت إليها كأنني في حلم.","zh":"干渴让我微微发烧，我望着它们，仿佛置身梦境。","t":[7105,13513]},{"ar":"الأمير الصغير آخر كلماته تتدفق على ذاكرتي كالرياح الموجية","zh":"小王子的最后几句话如潮水般涌回我的记忆：","t":[13513,18907]}]},{"id":"ch24p13","audio":"ch24p13.mp3","sents":[{"ar":"هل أنت جاف أيضًا؟ سألت مرة أخرى.","zh":"你也渴了吗？我追问。","t":[103,4105]}]},{"id":"ch24p14","audio":"ch24p14.mp3","sents":[{"ar":"لم يرد على سؤالي.","zh":"但他并未回答我的问题。","t":[103,2684]},{"ar":"قال لي:","zh":"他只是对我说：","t":[2684,3447]}]},{"id":"ch24p15","audio":"ch24p15.mp3","sents":[{"ar":"الماء يُساعد القلب أيضًا...","zh":"水对心灵亦有益……","t":[103,2208]}]},{"id":"ch24p16","audio":"ch24p16.mp3","sents":[{"ar":"لم أفهم معناه، ولكني لم أتحدث.","zh":"我不解其意，却缄口不言。","t":[103,4250]},{"ar":"أعلم أنني لا أستطيع سؤاله.","zh":"我深知无法对他进行质询。","t":[4250,6592]}]},{"id":"ch24p17","audio":"ch24p17.mp3","sents":[{"ar":"هو مرهق للغاية.","zh":"他疲惫不堪。","t":[103,2724]},{"ar":"هو جلس","zh":"他坐了下来。","t":[2724,3434]},{"ar":"أنا أجلس بجانبه.","zh":"我坐在他身边。","t":[3434,5947]},{"ar":"النجوم جميلة لأنها تحمل وردة لا يمكن رؤيتها.","zh":"星星之所以美丽，是因为有一朵看不见的花。","t":[5947,10461]}]},{"id":"ch24p18","audio":"ch24p18.mp3","sents":[{"ar":"أجبت: “بالطبع، هذا صحيح.” ثم صمت، ونظرت إلى الكثبان الرملية تحت ضوء القمر بصمت.","zh":"我答道：“没错，正是如此。”然后默默无言，凝视着月光下绵延的沙丘。","t":[103,8234]}]},{"id":"ch24p19","audio":"ch24p19.mp3","sents":[{"ar":"الصحراء جميلة، قال الأمير الصغير.","zh":"沙漠真美，小王子补充道。","t":[103,3155]}]},{"id":"ch24p20","audio":"ch24p20.mp3","sents":[{"ar":"هذا صحيح بالفعل.","zh":"这倒是真的。","t":[103,2605]},{"ar":"الصحراء، أنا أحبها دائمًا.","zh":"沙漠，我始终钟爱。","t":[2605,6211]},{"ar":"يُجلس على قمة تل في الصحراء، لا يرى شيئًا ولا يسمع شيئًا.","zh":"坐在沙漠沙丘上，无所见，无所闻。","t":[6211,12342]},{"ar":"في الصمت، ماذا ينبض، يلمع...","zh":"寂静中，有何物跳动，闪烁……","t":[12342,15250]}]},{"id":"ch24p21","audio":"ch24p21.mp3","sents":[{"ar":"البحراء لكونه يحتوي على بئر مخفية في زاوية منه.","zh":"沙漠之所以美丽，是因为它某个角落隐藏着一口井。","t":[103,4669]}]},{"id":"ch24p22","audio":"ch24p22.mp3","sents":[{"ar":"فجأةً، أدركت أسرار اللمعان الغامض للصحراء.","zh":"我猛然领悟到沙漠那神秘闪烁的奥秘。","t":[103,4974]},{"ar":"كنت صغيرًا أعيش في بيت قديم، يُقال فيه أن هناك كنزًا مدفونًا هناك.","zh":"我年幼时曾住在一座古老的大屋中，传说那里埋藏着一笔宝藏。","t":[4974,11961]},{"ar":"بالطبع، لا يعرف أحد كيف يجدها؛ ربما لم يكن أحد قد حاول البحث عنها من قبل.","zh":"确实，无人知晓如何找到它；或许无人曾试图寻找过。","t":[11961,20092]},{"ar":"لكن ذلك البيت قد تم تعطيله بالسحر.","zh":"但那座房子被施了魔法。","t":[20092,24211]},{"ar":"ديارى خفية بعمق قلوبى تحمل سرًا...","zh":"我的家在心底深处藏着一个秘密……","t":[24211,27500]}]},{"id":"ch24p23","audio":"ch24p23.mp3","sents":[{"ar":"نعم، قلت للأمير الصغير.","zh":"“是的，”我对小王子说。","t":[103,3500]},{"ar":"المنزل، النجوم، الصحراء - تمنحها الجمال ما لا يمكن رؤيته بالعين.","zh":"房子、星星、沙漠——赋予它们美丽的是肉眼无法看见的东西。","t":[3500,10040]}]},{"id":"ch24p24","audio":"ch24p24.mp3","sents":[{"ar":"قال بابتسامة: “سعيد، أنت موافق على ثعالبى.”","zh":"他笑着说：“很高兴，你赞同我的狐狸。”","t":[103,4484]}]},{"id":"ch24p25","audio":"ch24p25.mp3","sents":[{"ar":"الأمير الصغير نام، وقلت له في حضني، وأنا أبدأ في رحلتي مرة أخرى.","zh":"小王子入睡，我把他抱在怀里，再次踏上了旅程。","t":[103,7658]},{"ar":"قلبي يتأثر بعمق، يتحرك بامتنان.","zh":"内心深受触动，波澜起伏。","t":[7658,12184]},{"ar":"أنا أحمل كنزًا هشًا جدًا كأنما يُمسى بيدٍ خفيفة.","zh":"我仿佛抱着一件极其脆弱的珍宝。","t":[12184,17395]},{"ar":"في هذا الأرض، لا يوجد شيء أكثر هشاشة منه.","zh":"在这片大地上，似乎再无比他更脆弱之物。","t":[17395,22447]},{"ar":"في ضوء القمر هذا، أنظر إليه بجبينه الأبيض، عينيه المغلقة، شعره الداكن الذي يهتز مع الريح، وأنا أقول لنفسي: \"ما أراه ليس إلا جسدًا.\"","zh":"在这月光下，我凝视着他苍白的额头、紧闭的双眼、随风轻颤的鬈发，心中自语道：“我所看到的，不过是一具躯壳。”","t":[22447,35316]},{"ar":"أهمها، ما لا يرى العين……","zh":"最重要的，是肉眼看不见的……","t":[35316,37552]}]},{"id":"ch24p26","audio":"ch24p26.mp3","sents":[{"ar":"في شفتيهما النصفين، يتشابك ابتسامة مشككة بابتسامة خفيفة، وأقول لنفسي مرة أخرى: \"ما يلفت انتباهي هو ولاء هذا الصغير الأمير للورود التي تخلد في ذاكرته كنار في الظلام، حتى أثناء نومه...\" يصبح شعوره بالضعف واضحًا أكثر.","zh":"在这半张的嘴唇上，带着一丝怀疑的微笑微微张开，我再次对自己说：“打动我的，正是这位在此沉睡的小王子对一朵花的忠诚——玫瑰的影像在他整个生命中如灯焰般闪耀，即便在他入睡时……”我愈发觉得他显得更加脆弱。","t":[103,21658]},{"ar":"أشعر بحاجتي لحمايته، وكأنه نار يمكن أن تُطفأ بباد خفيف……","zh":"我感到需要保护他，仿佛他自身就是一丝微风就能吹灭的火焰……","t":[21658,27408]}]},{"id":"ch24p27","audio":"ch24p27.mp3","sents":[{"ar":"الفجر يلوح في الأفق، وجدت البئر.","zh":"曙光初露，我找到了那口井。","t":[103,3406]}]}]},{"id":"ch25","title_ar":"الفصل الخامس والعشرون","title_en":"Chapter XXV","title_zh":"第 25 章","paras":[{"id":"ch25p00","audio":"ch25p00.mp3","sents":[{"ar":"يستقيم الناس في رحلة، يركبون السيارات السريعة، وهم لا يعرفون ما يبحثون عنه.","zh":"人们踏上旅程，乘坐快车，却不知他们在寻找什么。","t":[103,8053]},{"ar":"هم يسرعون في الحركة، متحمسين، يدورون في حلقات...","zh":"他们忙乱地四处奔走，激动不已，团团打转……","t":[8053,12987]}]},{"id":"ch25p01","audio":"ch25p01.mp3","sents":[{"ar":"قال: \"هذا العناء لا يستحق.\"","zh":"他接着说：“这番忙碌实在不值得。”","t":[103,2642]}]},{"id":"ch25p02","audio":"ch25p02.mp3","sents":[{"ar":"نحن لم نجد بئرًا مثل بئر الصحراء العادية.","zh":"我们找到的井与撒哈拉沙漠的井大不相同。","t":[103,4382]},{"ar":"بئر الصحراء، ليست إلا حفرة في الرمل.","zh":"撒哈拉之井，不过是沙中浅洞。","t":[4382,8618]},{"ar":"هذه البئر تشبه بئر القرية.","zh":"这口井宛如村中的井。","t":[8618,11974]},{"ar":"لكن لا يوجد قرية هنا، وبدأت أشكك في أنني أنام في حلم.","zh":"然而此处并无村落，我疑心自己是在梦中。","t":[11974,17369]}]},{"id":"ch25p03","audio":"ch25p03.mp3","sents":[{"ar":"هذا غريب، قلت للأمير الصغير.","zh":"这真奇怪，我对小王子说。","t":[103,3908]},{"ar":"كل الأدوات جاهزة: العصا، الحوض، الحبل……","zh":"一切用具俱备：辘轳、水桶、绳子……","t":[3908,8316]}]},{"id":"ch25p04","audio":"ch25p04.mp3","sents":[{"ar":"ابتسم، لمس الحبل، وأطلق العنان للبكرة.","zh":"他笑着，轻触绳索，启动了辘轳。","t":[103,5197]},{"ar":"عجلة البكرة تغني كأنها طير قديم قد نسى أنه طير.","zh":"辘轳哀鸣，宛如久被遗忘的老风信鸡。","t":[5197,10092]}]},{"id":"ch25p05","audio":"ch25p05.mp3","sents":[{"ar":"أسمع، قال الأمير الصغير.","zh":"你听，小王子说。","t":[103,3355]},{"ar":"نحن أيقظنا هذا الديكور، هو يغني الآن...","zh":"我们唤醒了这口井，它正在歌唱……","t":[3355,7066]}]},{"id":"ch25p06","audio":"ch25p06.mp3","sents":[{"ar":"لا أريد أن يشعر بالتعب من سحب الحبل.","zh":"我不愿他因拉绳而劳累。","t":[103,3129]}]},{"id":"ch25p07","audio":"ch25p07.mp3","sents":[{"ar":"أنا سأقوم بذلك.","zh":"让我来吧。","t":[103,2684]},{"ar":"هذا العمل يصعب عليك كثيرًا.","zh":"这份工作对你来说太沉重了。","t":[2684,5395]}]},{"id":"ch25p08","audio":"ch25p08.mp3","sents":[{"ar":"أرفع الحوض ببطء إلى حافة الديكور، ووضعه هناك بينما كنت متعبًا، لكن سعيدًا بإنجازي.","zh":"我缓缓将水桶提到井边，放置其间——尽管疲惫，但为我的成就而喜悦。","t":[103,9000]},{"ar":"أغنية البكرة تظل ترن في أذني، وأرى ضوء الشمس يلمع في الماء الثابت.","zh":"辘轳之歌仍在耳畔回响，我看见阳光在静止摇曳的水面闪烁。","t":[9000,14947]}]},{"id":"ch25p09","audio":"ch25p09.mp3","sents":[{"ar":"أنا أبحث عن مثل هذه المياه، يقول الأمير الصغير.","zh":"我渴望的就是这样的水，小王子说。","t":[103,5224]},{"ar":"دعني أشرب بعضًا منها...","zh":"让我喝上几口……","t":[5224,7197]}]},{"id":"ch25p10","audio":"ch25p10.mp3","sents":[{"ar":"فهمت ما كان يبحث عنه.","zh":"我明白了他在寻找什么。","t":[103,2155]}]},{"id":"ch25p11","audio":"ch25p11.mp3","sents":[{"ar":"أرفع القارورة إلى شفتيه.","zh":"我举桶至他唇边。","t":[103,3289]},{"ar":"يُغلق عينيه ويُمتص.","zh":"他闭目啜饮。","t":[3289,6237]},{"ar":"كحلوى عيد الميلاد.","zh":"宛如节日佳肴般甘甜。","t":[6237,8658]},{"ar":"هذه الماء هي شيء مختلف تمامًا عن الغذاء العادي","zh":"这水确是不同于寻常的滋养。","t":[8658,12513]},{"ar":"السير تحت نجوم الليل، وأغاني البكرة، وشدتي، هي التي أنبتت عذوبة هذا الماء.","zh":"星光下的漫步、辘轳的歌声与我的臂力，孕育了这水的甘甜。","t":[12513,20711]},{"ar":"كهدية، تدفأت القلوب.","zh":"宛如礼物，温暖了心房。","t":[20711,23921]},{"ar":"كانت أضواء شجرة الميلاد، وموسيقى قداس منتصف الليل، وطيبة الوجوه الباسمة، تشكل نور الهدايا التي تلقيتها عندما كنت صغيرًا.","zh":"儿时，圣诞树上的灯光、子夜弥撒的乐音、微笑脸庞的温柔，构成了我所收到的礼物的光辉。","t":[23921,35263]}]},{"id":"ch25p12","audio":"ch25p12.mp3","sents":[{"ar":"\"الرجال في بلادكم،\" يقول الأمير الصغير، \"يزرعون خمسًا ألف وردة في الحديقة ويبحثون عن شيء لا يجدونه هناك.\"","zh":"“你们那里的男人，”小王子说，“在同一花园里培育了五千朵玫瑰——却在那里找不到他们所寻找的东西。”","t":[103,9550]}]},{"id":"ch25p13","audio":"ch25p13.mp3","sents":[{"ar":"لم يجدوا.","zh":"他们并未找到。","t":[103,1076]}]},{"id":"ch25p14","audio":"ch25p14.mp3","sents":[{"ar":"في وردة واحدة أو في قطرة ماء، ما يبحثون عنه يمكن العثور عليه.","zh":"在一朵玫瑰或一滴水中，他们所寻之物便可觅得。","t":[103,5971]}]},{"id":"ch25p15","audio":"ch25p15.mp3","sents":[{"ar":"نعم، هذا صحيح بالفعل.","zh":"是的，这确实如此。","t":[103,2497]}]},{"id":"ch25p16","audio":"ch25p16.mp3","sents":[{"ar":"الأمير الصغير يضيف:","zh":"小王子又补充道：","t":[103,1958]}]},{"id":"ch25p17","audio":"ch25p17.mp3","sents":[{"ar":"لكن العيون عمياء.","zh":"但眼睛是盲的。","t":[103,2684]},{"ar":"لا بد من النظر بعمق...","zh":"必须用心去看……","t":[2684,4632]}]},{"id":"ch25p18","audio":"ch25p18.mp3","sents":[{"ar":"لقد شربت هذا الماء.","zh":"我饮了这水。","t":[103,2671]},{"ar":"تنفسوا بسهولة.","zh":"呼吸顺畅了。","t":[2671,5118]},{"ar":"في وقت الشروق، تتألق الرمال بلون العسل.","zh":"日出时分，沙地泛着蜜色。","t":[5118,9711]},{"ar":"هذا العسل الأصفر يسر قلبي.","zh":"这蜜色也让我心情愉悦。","t":[9711,13145]},{"ar":"ما الذي يجعل قلبي يتعذب؟","zh":"那又是什么，让我心生哀愁？","t":[13145,15408]}]},{"id":"ch25p19","audio":"ch25p19.mp3","sents":[{"ar":"أنت واجبك أن تلتزم بالوعد، قال الأمير الصغير بعمق، وجلست إلى جواري مرة أخرى.","zh":"你务必遵守诺言，小王子轻声说，再次坐到我身边。","t":[103,7418]}]},{"id":"ch25p20","audio":"ch25p20.mp3","sents":[{"ar":"ما الوعده؟","zh":"什么诺言？","t":[103,971]}]},{"id":"ch25p21","audio":"ch25p21.mp3","sents":[{"ar":"تعرفين - أرسم لشعيري قناعًا...","zh":"你知道——给我的绵羊画一个口罩……","t":[103,4039]},{"ar":"أنا مسؤول عن هذه الزهرة...","zh":"我负责这朵花……","t":[4039,6066]}]},{"id":"ch25p22","audio":"ch25p22.mp3","sents":[{"ar":"أخرجت الرسم من جيبي.","zh":"我从口袋里掏出草图。","t":[103,2842]},{"ar":"الأمير الصغير نظر حوله ثم ضحك.","zh":"小王子打量了一番，笑着说：","t":[2842,5881]}]},{"id":"ch25p23","audio":"ch25p23.mp3","sents":[{"ar":"شجرة القردة الخاصة بك - إنها تشبه إلى حد ما البروكلي.","zh":"你的猴面包树——它们有点像卷心菜。","t":[103,4984]}]},{"id":"ch25p24","audio":"ch25p24.mp3","sents":[{"ar":"أوه!","zh":"哦！","t":[103,629]}]},{"id":"ch25p25","audio":"ch25p25.mp3","sents":[{"ar":"أنا فخور بما رسمته من شجرة المانديب!","zh":"我对自己画的猴面包树颇为自豪！","t":[103,3313]}]},{"id":"ch25p26","audio":"ch25p26.mp3","sents":[{"ar":"هذا الثعلب——أذنيه تشبه القرون قليلاً، وهي طويلة جدًا.","zh":"你的狐狸——它的耳朵有点像角，而且太长了。","t":[103,5668]}]},{"id":"ch25p27","audio":"ch25p27.mp3","sents":[{"ar":"ابتسم مرة أخرى.","zh":"他又笑了。","t":[103,1840]}]},{"id":"ch25p28","audio":"ch25p28.mp3","sents":[{"ar":"أنت غير عادل، يا الأمير الصغير، قلت.","zh":"你这不公平，小王子，我说。","t":[103,4605]},{"ar":"أعرف فقط رسم الترسان الخارجية والترسان الداخلية.","zh":"我只懂得画外部的蟒蛇和内部的蟒蛇。","t":[4605,8763]}]},{"id":"ch25p29","audio":"ch25p29.mp3","sents":[{"ar":"أوه، لا يهم، قال، سيفهمون ذلك الأطفال.","zh":"哦，那没关系，他说，孩子们会理解的。","t":[103,4629]}]},{"id":"ch25p30","audio":"ch25p30.mp3","sents":[{"ar":"ثم، رسمت رسمة بالأقلام البيضاء لوجه الغنم بكمامة.","zh":"于是，我画了一张绵羊口罩的铅笔草图。","t":[103,5987]},{"ar":"قلبى قد تفتقده عند تسليمه له.","zh":"我的心在交付给他时撕裂了。","t":[5987,8802]}]},{"id":"ch25p31","audio":"ch25p31.mp3","sents":[{"ar":"أنت تبحث عن شيء، وأنا لا أعلم ما هو","zh":"你有所图，我却不晓。","t":[103,3655]}]},{"id":"ch25p32","audio":"ch25p32.mp3","sents":[{"ar":"لم يرد عليّ","zh":"但他没有回答我。","t":[103,1195]},{"ar":"ثم التفت إليّ وقال","zh":"他转而对我说：","t":[1195,3037]}]},{"id":"ch25p33","audio":"ch25p33.mp3","sents":[{"ar":"أنت تعلم——إنني هبطت على الأرض……","zh":"你知道——我降临到地球……","t":[103,3974]},{"ar":"غدًا هو عيد ميلاده","zh":"明天就是它的周年纪念日。","t":[3974,5710]}]},{"id":"ch25p34","audio":"ch25p34.mp3","sents":[{"ar":"ثم توقف للحظة، ثم استأنف قائلاً","zh":"然后，沉默片刻，他又继续说道：","t":[103,3550]}]},{"id":"ch25p35","audio":"ch25p35.mp3","sents":[{"ar":"إنني هبطت هنا، قريبًا جدًا من هنا","zh":"我降落得离这里很近。","t":[103,3366]}]},{"id":"ch25p36","audio":"ch25p36.mp3","sents":[{"ar":"وجهه بدأ يتألق بالأحمر","zh":"他的脸泛起了红晕。","t":[103,2537]}]},{"id":"ch25p37","audio":"ch25p37.mp3","sents":[{"ar":"ولكن لا أعلم لماذا، شعرت بقلق غريب","zh":"又不知为何，我心中涌起一股莫名的哀愁。","t":[103,3971]},{"ar":"وفي نفس الوقت، بدأت تسألني في رأسي","zh":"然而，一个问题浮现在我的脑海中：","t":[3971,7261]}]},{"id":"ch25p38","audio":"ch25p38.mp3","sents":[{"ar":"في صباح ذلك اليوم، قبل أسبوعين، لماذا كنت وحيدًا في هذا الصحراء البعيدة؟","zh":"那天早上，我们初次相遇——一周前——你独自一人，在这远离人烟的沙漠中漫步，这并非偶然？","t":[103,7474]},{"ar":"هل أنت ذاهب بعيدًا عن مكان هبوطك؟","zh":"你正背对着你的降落点走去？","t":[7474,10474]}]},{"id":"ch25p39","audio":"ch25p39.mp3","sents":[{"ar":"أعادت وجهه إلى اللون الأحمر","zh":"小王子再次涨红了脸。","t":[103,2432]}]},{"id":"ch25p40","audio":"ch25p40.mp3","sents":[{"ar":"أكملت بقليل من التردد","zh":"我带着几分犹豫，补充道：","t":[103,2313]}]},{"id":"ch25p41","audio":"ch25p41.mp3","sents":[{"ar":"ربما بسبب العيد الميلادي؟","zh":"或许是因为周年纪念吧？","t":[103,2261]}]},{"id":"ch25p42","audio":"ch25p42.mp3","sents":[{"ar":"أعاد وجهه إلى اللون الأحمر","zh":"小王子脸颊再次泛红。","t":[103,2208]},{"ar":"هو لا يرد على الأسئلة - لكن إن تحمر وجه شخص، فهذا يعني 'نعم'، أليس كذلك؟","zh":"他从不回答问题——但一个人脸红，难道不是就意味着“是”吗？","t":[2208,9615]}]},{"id":"ch25p43","audio":"ch25p43.mp3","sents":[{"ar":"أقول له: 'يا إلهي، أشعر بالخوف' -","zh":"“啊，”我对他说，“我有点害怕——”","t":[103,3655]}]},{"id":"ch25p44","audio":"ch25p44.mp3","sents":[{"ar":"تدخلت لي","zh":"他打断了我。","t":[103,1156]}]},{"id":"ch25p45","audio":"ch25p45.mp3","sents":[{"ar":"الآن يجب أن تعمل","zh":"现在你必须工作了。","t":[103,1747]},{"ar":"يجب أن تعود إلى محركك","zh":"你必须回到你的引擎旁。","t":[1747,3774]},{"ar":"أنت هنا أنا أنتظر","zh":"我在这儿等你。","t":[3774,5168]},{"ar":"تعود غدًا مساءً","zh":"明天晚上再来……","t":[5168,6629]}]},{"id":"ch25p46","audio":"ch25p46.mp3","sents":[{"ar":"لكن لم أستطع الشعور بالأمان","zh":"但我并未感到安心。","t":[103,2471]},{"ar":"تذكرت الثعلب","zh":"我记起了那只狐狸。","t":[2471,3721]},{"ar":"إن البكاء يصبح أمرًا محتملاً إن سمحت لنفسك أن تصبح معروفًا","zh":"若有人让自己被驯服，难免会流下几滴泪……","t":[3721,9076]}]}]},{"id":"ch26","title_ar":"الفصل السادس والعشرون","title_en":"Chapter XXVI","title_zh":"第 26 章","paras":[{"id":"ch26p00","audio":"ch26p00.mp3","sents":[{"ar":"على جانب البئر، كانت هنالك بقايا جدار حجري قديم.","zh":"井边，一堵古老的石墙残垣断壁。","t":[103,5776]},{"ar":"في الليلة ذاتها، عند عودتي من العمل، رأيت من بعيد الأمير الصغير جالسًا على الجدار المتحطم، قدميه معلقتان.","zh":"当晚我下班归来，远远望见小王子坐在断壁之上，双脚悬空。","t":[5776,16711]},{"ar":"سمعتُ يقول:","zh":"我听见他这么说：","t":[16711,18053]}]},{"id":"ch26p01","audio":"ch26p01.mp3","sents":[{"ar":"ثم، لا تتذكر؟","zh":"那么，你不记得了。","t":[103,2921]},{"ar":"ليس هذا المكان المحدد.","zh":"这不是确切的地方。","t":[2921,4921]}]},{"id":"ch26p02","audio":"ch26p02.mp3","sents":[{"ar":"صوت آخر لابد وأن يستجيب له، لأنه قال:","zh":"另一个声音定然回应了他，因为他对此反驳道：","t":[103,4024]}]},{"id":"ch26p03","audio":"ch26p03.mp3","sents":[{"ar":"صحيح! صحيح!","zh":"没错！没错！","t":[103,3316]},{"ar":"هذا اليوم، وليس هذا المكان.","zh":"正是这一天，但不是这个地方。","t":[3316,5947]}]},{"id":"ch26p04","audio":"ch26p04.mp3","sents":[{"ar":"أستمررت في السير باتجاه الجدار.","zh":"我继续朝墙走去。","t":[103,3618]},{"ar":"لم أر أي أحد ولا سمعت أحدًا.","zh":"我从未见过或听到过任何人。","t":[3618,7303]},{"ar":"الأمير الصغير رد على ذلك:","zh":"小王子却再次反驳道：","t":[7303,9750]}]},{"id":"ch26p05","audio":"ch26p05.mp3","sents":[{"ar":"صحيح!","zh":"没错。","t":[103,1711]},{"ar":"ستشاهدين حيث تبدأ أثر قدمي في الرمال","zh":"你将看到我的足迹在沙地上起始之处。","t":[1711,4987]},{"ar":"انتظرني هناك.","zh":"你只需在那里等我。","t":[4987,7197]},{"ar":"سأكون هناك الليلة وأنت انتظريني.","zh":"今夜我会在那儿等你。","t":[7197,10250]}]},{"id":"ch26p06","audio":"ch26p06.mp3","sents":[{"ar":"أنا على بعد عشرون مترًا من الجدار، ومع ذلك لا أرى شيئًا.","zh":"我离墙仅有二十米，却仍一无所见。","t":[103,5155]}]},{"id":"ch26p07","audio":"ch26p07.mp3","sents":[{"ar":"بعد صمت قليل، بدأ الأمير الصغير يتحدث.","zh":"沉默片刻后，小王子又开口了。","t":[103,3984]}]},{"id":"ch26p08","audio":"ch26p08.mp3","sents":[{"ar":"هل لديك سُمّ؟","zh":"你有毒药吗？","t":[103,2184]},{"ar":"هل أنت متأكدة من أنه لن يجعلني أعاني وقتًا طويلاً جدًا؟","zh":"你能否肯定不会让我遭受太久痛苦？","t":[2184,7132]}]},{"id":"ch26p09","audio":"ch26p09.mp3","sents":[{"ar":"توقفت دون أن أتحرك، قلبي قد تكسر؛ ومع ذلك لم أستطع أن أفهم.","zh":"我止步不前，心碎如裂；然而我依旧不解。","t":[103,6169]}]},{"id":"ch26p10","audio":"ch26p10.mp3","sents":[{"ar":"الآن اذهب، يقول الأمير الصغير.","zh":"现在你走吧，小王子说。","t":[103,3934]},{"ar":"أريد أن أنزل من الجدار.","zh":"我想要从墙上下来。","t":[3934,5987]}]},{"id":"ch26p11","audio":"ch26p11.mp3","sents":[{"ar":"انحنيت نحو قدمي الجدار... ثم ألقيت بنفسي في الهواء.","zh":"我低头看向墙脚——然后纵身跃起。","t":[103,6447]},{"ar":"الثعبان الأصفر يرفع رأسه نحو الأمير الصغير، هذا الثعبان يمكن أن يأخذ حياتك في ثوانٍ معدودة.","zh":"黄蛇昂首面对小王子，这种蛇只需三十秒就能夺走人的生命。","t":[6447,15566]},{"ar":"أخرجت المسدس وأسرعت بالتراجع.","zh":"我掏枪入袋，同时快步后退。","t":[15566,19250]},{"ar":"لكن في ضجيجي، أنزلت السنّة كأنها نافورة ميتة، تسيل على الرمال بسهولة، تختفي بلا عجلة وسط الصخور، تطلق صوتاً معدنياً خفيفاً.","zh":"但在我制造的噪音中，那条蛇像喷泉般垂死的喷泉一样，在沙地上轻松地流淌，不慌不忙地消失在石头之间，发出轻微的金属声响。","t":[19250,31579]}]},{"id":"ch26p12","audio":"ch26p12.mp3","sents":[{"ar":"لقد وصلت في الوقت المناسب وألهمسته صغره بين يدي، ووجهه أبيض كالثلج.","zh":"我及时赶到，将他小小的身躯紧紧抱在怀中，他的脸庞白得如雪。","t":[103,6642]}]},{"id":"ch26p13","audio":"ch26p13.mp3","sents":[{"ar":"ماذا يعني ذلك؟","zh":"我追问：“这是什么意思？”","t":[103,2434]},{"ar":"لماذا تتحدث إلى الثعبان؟","zh":"你为何与蛇交谈？","t":[2434,4763]}]},{"id":"ch26p14","audio":"ch26p14.mp3","sents":[{"ar":"أزلت القميص الذهبي الذي كان يرتديه دائمًا.","zh":"我解开了他始终佩戴的金色围巾。","t":[103,4763]},{"ar":"أراحته جبينه وأعطيته بعض الماء للشرب.","zh":"我湿润了他的太阳穴，并给他喝了一些水。","t":[4763,9132]},{"ar":"لن أتجرأ على طرح المزيد من الأسئلة.","zh":"我再也不敢问他更多问题了。","t":[9132,13145]},{"ar":"يرى بجدية ويعلق يديه حول عنقي.","zh":"他严肃地望着我，将双臂环抱住我的脖子。","t":[13145,17566]},{"ar":"قلبُه يتردد كأنه طائرُ صغيرُ مصابُ بالرصاص، يتردد بسرعة.","zh":"他的心跳如中枪濒死的小鸟般急促。","t":[17566,23250]}]},{"id":"ch26p15","audio":"ch26p15.mp3","sents":[{"ar":"قال بفرح: \"لقد عثرت على مشكلة الطائرة، وأنا سعيد جداً.\"","zh":"他高兴地说：“你找到了飞机的问题，我很欣慰。”","t":[103,5576]},{"ar":"الآن يمكنك العودة إلى بيتك","zh":"现在你可以回家了——","t":[5576,8353]}]},{"id":"ch26p16","audio":"ch26p16.mp3","sents":[{"ar":"كيف تعرفين هذا الأمر؟","zh":"你怎会知道那事？","t":[103,1932]}]},{"id":"ch26p17","audio":"ch26p17.mp3","sents":[{"ar":"كنت أحتاج أن أخبره بأن عملي قد نجح، بدرجة تفوقت على كل توقعاتي.","zh":"我正要告诉他，我的工作已经成功，超出了我敢想象的任何程度。","t":[103,6734]}]},{"id":"ch26p18","audio":"ch26p18.mp3","sents":[{"ar":"لم يرد على سؤالي، بل أضاف: \"أنا سأعود إلى بيتي...\"","zh":"他未对我的问题作答，却补充道：“我也要回家去了……”","t":[103,5208]}]},{"id":"ch26p19","audio":"ch26p19.mp3","sents":[{"ar":"عندئذ، قال بحنان وحنين: \"ذلك يبعد أكثر بكثير...\"","zh":"那时，他黯然神伤地说：“那还要远得多……”","t":[103,6237]},{"ar":"... هذا أكثر صعوبة...","zh":"这还更加艰难……","t":[6237,7855]}]},{"id":"ch26p20","audio":"ch26p20.mp3","sents":[{"ar":"أفهم، هذا ليس أمرًا عاديًا.","zh":"我明白，这绝非寻常之事。","t":[103,3829]},{"ar":"ألتمسكناه كأنه طفل صغير؛ ولكن، شعرت بأنه يسقط نحو الهاوية، وأنا لا أستطيع تثبيته……","zh":"我紧紧地抱住他，如同抱住一个小孩；然而，我感觉他正一头冲向深渊，而我却无法阻止他……","t":[3829,12474]}]},{"id":"ch26p21","audio":"ch26p21.mp3","sents":[{"ar":"عيناه شديدتي الجدية كأنهما غارقتان في مكان بعيد.","zh":"他的目光非常严肃，仿佛迷失在遥远之地。","t":[103,5050]}]},{"id":"ch26p22","audio":"ch26p22.mp3","sents":[{"ar":"لدي خروفك.","zh":"我有你的绵羊。","t":[103,2342]},{"ar":"أمتلك صندوقًا للخروف.","zh":"我有羊的箱子。","t":[2342,5487]},{"ar":"أنا مازلت أملك ماسكته...","zh":"我还有它的口罩……","t":[5487,7644]}]},{"id":"ch26p23","audio":"ch26p23.mp3","sents":[{"ar":"ابتسم ببرود.","zh":"他凄然一笑。","t":[103,1523]}]},{"id":"ch26p24","audio":"ch26p24.mp3","sents":[{"ar":"أنتظرت لفترة طويلة.","zh":"我等待了许久。","t":[103,3171]},{"ar":"استأنف في الحياة تدريجيًا.","zh":"他渐渐恢复了生机。","t":[3171,5447]}]},{"id":"ch26p25","audio":"ch26p25.mp3","sents":[{"ar":"يا بنتي الحبيبة، قلت: \"تخافين...\"","zh":"亲爱的孩子，我说道，“你害怕了……”","t":[103,3406]}]},{"id":"ch26p26","audio":"ch26p26.mp3","sents":[{"ar":"لم يكن هناك أي شيء يمكن أن يشكك فيه.","zh":"他害怕，这毫无疑问。","t":[103,4500]},{"ar":"ابتسم بابتسامة خفيفة.","zh":"他轻轻地笑了。","t":[4500,6789]}]},{"id":"ch26p27","audio":"ch26p27.mp3","sents":[{"ar":"...ليلة هذا اليوم سأكون خائفاً أكثر...","zh":"今夜我会更加害怕……","t":[103,3090]}]},{"id":"ch26p28","audio":"ch26p28.mp3","sents":[{"ar":"أنا مرة أخرى أتجمّد من شعور لا يمكن تعويضه.","zh":"我又一次被那无法挽回的感觉冻结了。","t":[103,5171]},{"ar":"لا أستطيع تحمل أن أسمع أبدًا صوت الضحك ذاك.","zh":"我无法忍受再想永远听不到那笑声。","t":[5171,9908]},{"ar":"بركة ماء عذبة في الصحراء","zh":"沙漠中的一股清泉。","t":[9908,12211]}]},{"id":"ch26p29","audio":"ch26p29.mp3","sents":[{"ar":"يا صغيري، أريد سماع ضحكتك مجددًا.","zh":"小家伙，我想再听到你的笑声。","t":[103,3708]}]},{"id":"ch26p30","audio":"ch26p30.mp3","sents":[{"ar":"قال لي:","zh":"他对我说：","t":[103,866]}]},{"id":"ch26p31","audio":"ch26p31.mp3","sents":[{"ar":"الليلة، سيكون ذكرى السنة الأولى...","zh":"今夜，它将是一周年……","t":[103,4145]},{"ar":"نجمي، الآن هو في نفس المكان الذي هبط فيه على الأرض قبل عام……","zh":"我的星星，现在就在我一年前降落到地球的那个地方上方……","t":[4145,9579]}]},{"id":"ch26p32","audio":"ch26p32.mp3","sents":[{"ar":"يا صغيري، أخبرني، هذا الأمر حول الثعبان واللقاء والنجوم هو مجرد كابوس……","zh":"小家伙，告诉我，这关于蛇、约会和星星的事，只是一场噩梦……","t":[103,6813]}]},{"id":"ch26p33","audio":"ch26p33.mp3","sents":[{"ar":"لم يرد على دعائي.","zh":"但他并未回应我的哀求。","t":[103,2658]},{"ar":"قال: - أما أنا فأقول لك","zh":"他转而对我说：","t":[2658,5105]}]},{"id":"ch26p34","audio":"ch26p34.mp3","sents":[{"ar":"ذلك المهم، هو الذي لا يمكن رؤيته بالعين العادية……","zh":"那重要的东西，是肉眼无法看见的……","t":[103,4708]}]},{"id":"ch26p35","audio":"ch26p35.mp3","sents":[{"ar":"نعم، أعلم…","zh":"是的，我知道……","t":[103,1589]}]},{"id":"ch26p36","audio":"ch26p36.mp3","sents":[{"ar":"كذلك هو الأمر بالنسبة للورود.","zh":"它对花儿来说也是如此。","t":[103,3763]},{"ar":"إذا أحببت وردًا ينمو على نجم، فإن النظر إلى السماء في الليل سيكون حلوًا جدًا.","zh":"若你爱上了一朵生长在星星上的花，那么在夜晚仰望星空便显得格外甜蜜。","t":[3763,11158]},{"ar":"نجوم زاهرة، الزهور تزهر في السماء","zh":"繁星似锦，花开满空","t":[11158,14671]}]},{"id":"ch26p37","audio":"ch26p37.mp3","sents":[{"ar":"نعم، أعلم…","zh":"是的，我知道……","t":[103,1589]}]},{"id":"ch26p38","audio":"ch26p38.mp3","sents":[{"ar":"الماء كذلك.","zh":"水亦如此。","t":[103,2263]},{"ar":"لأن ذلك الدلو والخيط، الماء الذي أعطيتني إياه، كالموسيقى.","zh":"因为那辘轳和绳子，你给我的水，如同音乐。","t":[2263,8382]},{"ar":"هل تتذكرُـنـاها؟ كان الزمنُـنـا جميـلًا.","zh":"你记得——那时多么美好。","t":[8382,12513]}]},{"id":"ch26p39","audio":"ch26p39.mp3","sents":[{"ar":"نعم، أعلم…","zh":"是的，我知道……","t":[103,1589]}]},{"id":"ch26p40","audio":"ch26p40.mp3","sents":[{"ar":"في الليل، ستتطلع إلى السماء.","zh":"在夜晚，你会仰望星空。","t":[103,3908]},{"ar":"أنا أعيش في مكان صغير جدًا، لا أستطيع أن أرشدك إلى نجارتي.","zh":"我住的地方一切都很小，无法向你指出我的星星所在之处。","t":[3908,10303]},{"ar":"إذاً كان ذلك أفضل.","zh":"如此更佳。","t":[10303,12974]},{"ar":"نجمي مجرد نجوم من ملايين النجوم، لك.","zh":"我的星星只是万千星辰之一，对你而言。","t":[12974,17750]},{"ar":"لذلك، ستُحب مشاهدة كل النجوم في السماء……","zh":"因此，你将喜欢观看天空中所有的星星……","t":[17750,22526]},{"ar":"ستصبحون أصدقاءً لكم.","zh":"它们都将成为你的朋友。","t":[22526,25526]},{"ar":"إلى جانب ذلك، سأقدم لك هدية……","zh":"此外，我还要送你一份礼物……","t":[25526,28671]}]},{"id":"ch26p41","audio":"ch26p41.mp3","sents":[{"ar":"ابتسم مرة أخرى.","zh":"他又笑了。","t":[103,1840]}]},{"id":"ch26p42","audio":"ch26p42.mp3","sents":[{"ar":"أوه، الأمير الصغير، يا أميري العزيز!","zh":"啊，小王子，我亲爱的王子！","t":[103,4645]},{"ar":"أحب أن أسمع ضحكتك!","zh":"我喜欢听你的笑声！","t":[4645,6605]}]},{"id":"ch26p43","audio":"ch26p43.mp3","sents":[{"ar":"هذا هدئتي","zh":"这是我的礼物。","t":[103,1011]},{"ar":"فقط هذا","zh":"仅此而已。","t":[1011,1721]},{"ar":"سيكون كالماء الذي شربناه معًا","zh":"它将如同我们共饮那水时一般。","t":[1721,4314]}]},{"id":"ch26p44","audio":"ch26p44.mp3","sents":[{"ar":"ماذا تريد أن تعبر عنه؟","zh":"你究竟想表达什么？","t":[103,2195]}]},{"id":"ch26p45","audio":"ch26p45.mp3","sents":[{"ar":"كل قلب يحتوي على نجوم، لكنها تعني أشياء مختلفة للناس المختلفين","zh":"每个人心中都有星星，但对不同的人来说，它们的意义各不相同。","t":[103,6037]},{"ar":"للمسافرين، النجوم هي مرشدين","zh":"对某些旅人来说，星星是向导。","t":[6037,8866]},{"ar":"بالنسبة للبعض، هي مجرد نيران صغيرة في السماء","zh":"对其他人而言，它们不过是天空中微小的灯火。","t":[8866,13050]},{"ar":"بالنسبة للعلماء، هي أسئلة","zh":"对学者来说，它们是问题。","t":[13050,15618]},{"ar":"بالنسبة للتجار، هي ثروة","zh":"对那位商人来说，它们是财富。","t":[15618,18145]},{"ar":"لكن النجوم صامتة","zh":"但这些星星都沉默着。","t":[18145,19763]},{"ar":"أنت——فقط أنت——ستملك نجومًا لا يمكن لأحد آخر امتلاكها——","zh":"你——只有你——将拥有别人无法拥有的星星——","t":[19763,25500]}]},{"id":"ch26p46","audio":"ch26p46.mp3","sents":[{"ar":"ماذا تريد أن تعبر عنه؟","zh":"你究竟想表达什么？","t":[103,2195]}]},{"id":"ch26p47","audio":"ch26p47.mp3","sents":[{"ar":"في نجمة، سأعيش","zh":"在某一颗星星上，我将居住。","t":[103,1839]},{"ar":"في تلك النجمة، سأضحك","zh":"在那颗星星上，我会笑着。","t":[1839,3853]},{"ar":"عندما تنظر إلى السماء في الليل، يبدو كأن كل النجوم تضحك","zh":"当你在夜晚仰望星空时，仿佛所有的星星都在欢笑。","t":[3853,8511]},{"ar":"أنت——فقط أنت——ستملك نجومًا تضحك！وضحك مرة أخرى","zh":"你——只有你——将拥有会笑的星星！他再次笑了。","t":[8511,14987]}]},{"id":"ch26p48","audio":"ch26p48.mp3","sents":[{"ar":"عندما تهدأ حزنك (لأن الوقت يهدأ كل الأحزان) ستشعر بالسعادة لمعرفتي بي","zh":"当你的悲伤得到慰藉（时间抚平所有悲伤）时，你将满足于曾认识我。","t":[103,6761]},{"ar":"أنت دائمًا صديقي","zh":"你永远是我的朋友。","t":[6761,8221]},{"ar":"أنت تريد أن تضحك معي","zh":"你愿与我同笑。","t":[8221,10076]},{"ar":"في بعض الأحيان، ستبتسم نافذتك للاستمتاع بذلك","zh":"有时，你也会打开窗子，为了那份快乐……","t":[10076,14382]},{"ar":"أصدقائك سيتفاجأون برؤيتك تضحك بينما تنظر إلى السماء","zh":"你的朋友们会惊讶地看到你仰望星空时竟在欢笑！","t":[14382,19276]},{"ar":"نعم، النجوم تجعلني أضحك دائمًا！سيظنون أنك مجنون","zh":"是的，星星总是让我笑！他们会以为你疯了。","t":[19276,25474]},{"ar":"هذا سيكون لعبة سيئة جدًا ألعبها عليك……","zh":"这将是我在你身上玩的一个非常拙劣的把戏……","t":[25474,29408]}]},{"id":"ch26p49","audio":"ch26p49.mp3","sents":[{"ar":"وضحك مرة أخرى","zh":"他又笑了。","t":[103,1852]}]},{"id":"ch26p50","audio":"ch26p50.mp3","sents":[{"ar":"كأنني أعطيتك الكثير من البوقات الصغيرة التي تستطيع أن تضحك……","zh":"仿佛我给了你无数会笑的小铃铛……","t":[103,5063]}]},{"id":"ch26p51","audio":"ch26p51.mp3","sents":[{"ar":"وضحك مرة أخرى","zh":"他又笑了。","t":[103,1642]},{"ar":"ثم أصبح جادًا","zh":"他很快变得严肃起来：","t":[1642,3076]}]},{"id":"ch26p52","audio":"ch26p52.mp3","sents":[{"ar":"الليلة——أنت تعلم……","zh":"今夜——你知道……","t":[103,3013]},{"ar":"لا تأتِ، يقول الأمير الصغير.","zh":"“别来了，”小王子说。","t":[3013,5579]}]},{"id":"ch26p53","audio":"ch26p53.mp3","sents":[{"ar":"لن أغادر لك.","zh":"我不会离开你。","t":[103,1431]}]},{"id":"ch26p54","audio":"ch26p54.mp3","sents":[{"ar":"سأبدو كأنني أعاني.","zh":"我将显得像是在受苦。","t":[103,2934]},{"ar":"سأبدو كأنني على وشك الموت.","zh":"我将显得像是即将离世。","t":[2934,6197]},{"ar":"هذا هو الوضع.","zh":"它就是这样。","t":[6197,8434]},{"ar":"لا تأتِ لتشاهدي هذا العرض.","zh":"别来看那场戏。","t":[8434,11724]},{"ar":"ليس من المقدار أن أقوم بذلك……","zh":"不值得费这个劲……","t":[11724,14303]}]},{"id":"ch26p55","audio":"ch26p55.mp3","sents":[{"ar":"لن أغادر لك.","zh":"我不会离开你。","t":[103,1431]}]},{"id":"ch26p56","audio":"ch26p56.mp3","sents":[{"ar":"لكن كان قلقه شديداً.","zh":"但他忧心忡忡。","t":[103,2287]}]},{"id":"ch26p57","audio":"ch26p57.mp3","sents":[{"ar":"ذلك لأن السمكة هي السبب.","zh":"这同样是因为那条蛇。","t":[103,3474]},{"ar":"لا يمكن أن تعضك.","zh":"它不能咬你。","t":[3474,6132]},{"ar":"السمكة——هي مخلوقات شريرة.","zh":"蛇——它们是恶毒的生物。","t":[6132,9895]},{"ar":"ربما قد تقوم بضربك بلا سبب……","zh":"这蛇说不定会故意咬你取乐呢……","t":[9895,12658]}]},{"id":"ch26p58","audio":"ch26p58.mp3","sents":[{"ar":"لن أغادر لك.","zh":"我不会离开你。","t":[103,1431]}]},{"id":"ch26p59","audio":"ch26p59.mp3","sents":[{"ar":"لكن فكرة ما ساعدته.","zh":"但一个念头让他得到了安慰：","t":[103,2050]}]},{"id":"ch26p60","audio":"ch26p60.mp3","sents":[{"ar":"الضربة الثانية للسمكة لا تحتوي على سم.","zh":"蛇咬的第二口不再有毒液。","t":[103,3550]}]},{"id":"ch26p61","audio":"ch26p61.mp3","sents":[{"ar":"في تلك الليلة لم أره يبدأ في العودة.","zh":"那晚，我没有看到他踏上归途。","t":[103,3961]},{"ar":"خرج من غير صوت، وسرعان ما اختفى من بين يدي.","zh":"他悄无声息地从我身边溜走。","t":[3961,9092]},{"ar":"عندما وصل إليه، كان يسير بخطوات سريعة ومستقيمة.","zh":"他追上他时，他正迈着迅速而坚定的步伐前行。","t":[9092,15092]},{"ar":"قال لي فقط:.","zh":"他只对我说了这么一句：","t":[15092,16263]}]},{"id":"ch26p62","audio":"ch26p62.mp3","sents":[{"ar":"أوه!","zh":"啊！","t":[103,1526]},{"ar":"أنت هناك……","zh":"你就在那里……","t":[1526,2644]}]},{"id":"ch26p63","audio":"ch26p63.mp3","sents":[{"ar":"أمسك بيدي.","zh":"他握住了我的手。","t":[103,2250]},{"ar":"كان قلقه لا يزال.","zh":"他依旧忧心忡忡。","t":[2250,4105]}]},{"id":"ch26p64","audio":"ch26p64.mp3","sents":[{"ar":"لا يجب أن تأتِ هنا.","zh":"你来得不对。","t":[103,2711]},{"ar":"ستعاني.","zh":"你将受苦。","t":[2711,4605]},{"ar":"سأبدو كأنني ميت، لكن هذا ليس صحيحاً……","zh":"我将看起来像是死了；其实并非如此……","t":[4605,8592]}]},{"id":"ch26p65","audio":"ch26p65.mp3","sents":[{"ar":"لم أستطع أن أجيب.","zh":"我无言以对。","t":[103,1747]}]},{"id":"ch26p66","audio":"ch26p66.mp3","sents":[{"ar":"أنت تعرف…","zh":"你懂得……","t":[103,2079]},{"ar":"المسافة كانت طويلة جدًا","zh":"路途太过遥远。","t":[2079,4224]},{"ar":"لا أستطيع أن أجيب","zh":"我无法带着这具身体离去。","t":[4224,5632]},{"ar":"كان هذا ثقيلًا جدًا","zh":"这太沉重了。","t":[5632,7460]}]},{"id":"ch26p67","audio":"ch26p67.mp3","sents":[{"ar":"لم أستطع أن أجيب","zh":"我无言以对。","t":[103,1747]}]},{"id":"ch26p68","audio":"ch26p68.mp3","sents":[{"ar":"لكن كان كأنه قذيفة قديمة قد تخلصت منها","zh":"却如同褪去的旧壳。","t":[103,3958]},{"ar":"القذيفة القديمة لم تكن تحمل حزنًا…","zh":"旧壳并无悲凉之处……","t":[3958,7195]}]},{"id":"ch26p69","audio":"ch26p69.mp3","sents":[{"ar":"لم أستطع أن أجيب","zh":"我无言以对。","t":[103,1747]}]},{"id":"ch26p70","audio":"ch26p70.mp3","sents":[{"ar":"كان يبدو مكسورًا","zh":"他有些气馁。","t":[103,1366]},{"ar":"لكنه حاول مرة أخرى:","zh":"但他又试了一次：","t":[1366,3431]}]},{"id":"ch26p71","audio":"ch26p71.mp3","sents":[{"ar":"أنت تعرف، سيكون هذا جميلًا جدًا","zh":"你懂得，这会非常美好。","t":[103,3234]},{"ar":"أنا سأنظر إلى السماء أيضًا","zh":"我也会仰望星空。","t":[3234,5313]},{"ar":"النجوم كأنها بركة من الماء قد جففت، والسحاب قد تآكل منه","zh":"繁星如井，辘轳生锈。","t":[5313,10576]},{"ar":"النجوم ستكون كأنها تبرز لي من الماء","zh":"繁星将为我涌出清泉解渴。","t":[10576,13892]}]},{"id":"ch26p72","audio":"ch26p72.mp3","sents":[{"ar":"لم أستطع أن أجيب","zh":"无言以对。","t":[103,1747]}]},{"id":"ch26p73","audio":"ch26p73.mp3","sents":[{"ar":"سيكون هذا ممتعًا جدًا!","zh":"那将非常有趣！","t":[103,3224]},{"ar":"ستكون لديك خمسمئة مليون صافرة صغيرة، وأنا سأملك خمسمئة مليون عين من الماء…","zh":"你将拥有五亿个小铃铛，而我将拥有五亿股清泉……","t":[3224,10816]}]},{"id":"ch26p74","audio":"ch26p74.mp3","sents":[{"ar":"لم يكن لديه ما يقوله، لأن عيناه قد ملأت من الدموع","zh":"他默默无言，只因泪水盈眶。","t":[103,4852]}]},{"id":"ch26p75","audio":"ch26p75.mp3","sents":[{"ar":"هذا هو المكان","zh":"这里就是了。","t":[103,1300]},{"ar":"دعني أستمر بنفسي","zh":"让我自己继续吧。","t":[1300,2984]}]},{"id":"ch26p76","audio":"ch26p76.mp3","sents":[{"ar":"جلست لأنه كان خائفًا","zh":"他坐下来，因为他害怕了。","t":[103,2168]},{"ar":"ثم قال:","zh":"他又说道：","t":[2168,3064]}]},{"id":"ch26p77","audio":"ch26p77.mp3","sents":[{"ar":"هل تعلم… زهري…","zh":"你可知——我的花儿……","t":[103,3539]},{"ar":"أنا مسؤول عنها","zh":"我为她负责。","t":[3539,4829]},{"ar":"كانت ضعيفة جدًا","zh":"她如此脆弱！","t":[4829,6276]},{"ar":"كانت صغيرة جدًا","zh":"她如此天真！","t":[6276,7789]},{"ar":"كانت لديها أربع شوك صغيرة لا تستطيع حمايتها من العالم","zh":"她仅有四根刺，毫无用处，却用来抵御整个世界的侵害。","t":[7789,12856]}]},{"id":"ch26p78","audio":"ch26p78.mp3","sents":[{"ar":"جلست لأنني لم أستطع أن أستمر واقفًا","zh":"我也坐了下来，因为我已无法再站立。","t":[103,3432]}]},{"id":"ch26p79","audio":"ch26p79.mp3","sents":[{"ar":"ذلك كافٍ……","zh":"那便足够了……","t":[103,1181]}]},{"id":"ch26p80","audio":"ch26p80.mp3","sents":[{"ar":"ثم تردد قليلاً، ثم وقف","zh":"他犹疑片刻，然后站起身来。","t":[103,2655]},{"ar":"استعد لخطوة واحدة","zh":"他迈出一步。","t":[2655,4471]},{"ar":"لم أستطع الحركة","zh":"我动弹不得。","t":[4471,6011]}]},{"id":"ch26p81","audio":"ch26p81.mp3","sents":[{"ar":"على ركبتيه، مرت فوضى من الضوء الأصفر","zh":"踝边，一抹黄光掠过。","t":[103,3339]},{"ar":"ثم بقي ثابتاً في مكانه","zh":"他瞬间僵立不动。","t":[3339,5511]},{"ar":"لم يصرخ","zh":"他没有呼喊。","t":[5511,6142]},{"ar":"كشجرة تسقط بسهولة","zh":"他如树般轻轻倒下。","t":[6142,8392]},{"ar":"لم يكن هناك حتى صوت السكران، بسبب الرمل","zh":"连沙沙声也没有，因为沙子的缘故。","t":[8392,12379]}]}]},{"id":"ch27","title_ar":"الفصل السابع والعشرون","title_en":"Chapter XXVII","title_zh":"第 27 章","paras":[{"id":"ch27p00","audio":"ch27p00.mp3","sents":[{"ar":"ست سنوات قد مضت...","zh":"六载光阴，已然逝去……","t":[103,2050]}]},{"id":"ch27p01","audio":"ch27p01.mp3","sents":[{"ar":"لم أذكر هذه القصة لأحد.","zh":"这故事，我从未对人提起。","t":[103,3434]},{"ar":"عادت إليهم وأجدتهم سعداء برؤيتي على قيد الحياة.","zh":"重逢的伙伴们见到我安然无恙，心中皆感欣慰。","t":[3434,8711]},{"ar":"أنا حزين، ولكنني أخبرتهم: \"أنا متعب جدًا.\"","zh":"我心情沉重，却对他们说：“我累得要命。”","t":[8711,13171]}]},{"id":"ch27p02","audio":"ch27p02.mp3","sents":[{"ar":"تخففت من حزني قليلاً.","zh":"我的哀愁得以稍慰。","t":[103,3013]},{"ar":"هذا يعني - لم يكن كاملاً.","zh":"这也就是说——并未完全。","t":[3013,6566]},{"ar":"لكني أعلم أنه عاد إلى كوكبه الخاص، لأنني لم أجد جسده عند الفجر.","zh":"但我深知他已返回自己的星球，因为天亮时我没有找到他的遗体。","t":[6566,13618]},{"ar":"جثمانه لم يكن ثقيلاً...","zh":"他的遗体并不沉重……","t":[13618,16684]},{"ar":"لقد انحصرت في الليل، وأنا أحب الاستماع إلى همسات النجوم.","zh":"夜幕降临，我偏爱聆听星辰的低语。","t":[16684,22579]},{"ar":"كأنها خمسمئة مليون جرس صغير...","zh":"它们宛如五亿个小铃铛……","t":[22579,25658]}]},{"id":"ch27p03","audio":"ch27p03.mp3","sents":[{"ar":"...ومع ذلك، هناك أمر غير اعتيادي...","zh":"然而，有一件不同寻常的事……","t":[103,4408]},{"ar":"رسمت كمامة للأمير الصغير، ونسيت أن أضيف الحزام.","zh":"为小王子画了口罩，却忘了添上皮带。","t":[4408,10026]},{"ar":"لا يمكنه أبدًا ربطها حول رقبة الأغنام.","zh":"他永远无法将它系在绵羊的脖子上。","t":[10026,14526]},{"ar":"أنا دائمًا ما أفكر: ماذا حدث على كوكبه؟","zh":"我始终在思索：他的星球上究竟发生了什么？","t":[14526,19237]},{"ar":"ربما أكلت الحمل الزهرة...","zh":"或许绵羊已经吃掉了那朵花……","t":[19237,21263]}]},{"id":"ch27p04","audio":"ch27p04.mp3","sents":[{"ar":"بالطبع، لن يكون كذلك!","zh":"当然，不会吧！","t":[103,3395]},{"ar":"الأمير الصغير يخفي زهرته في كرة الزجاج كل ليلة ويهتم بشغله الشعبي…… لذا، شعرت بالراحة.","zh":"小王子每晚都将他的花儿藏进玻璃球中，他精心照看着他的绵羊……于是，我便安心了。","t":[3395,13487]},{"ar":"النجوم تضحك بابتسامة، وتجد في ذلك حلاوة.","zh":"星光笑意中，自有甜蜜。","t":[13487,17619]}]},{"id":"ch27p05","audio":"ch27p05.mp3","sents":[{"ar":"ومع ذلك، أحياناً أقول لنفسي: لا بد أن يغفل المرء أحياناً، هذا كافٍ!","zh":"然而，有时我会对自己说：人难免会疏忽大意，这就足够了！","t":[103,7816]},{"ar":"في تلك الليلة، نسي كرة الزجاج، أو سرت الأغنام بصمت، ثم أصبحت تلك الجرسونات دموعًا……","zh":"那天晚上，他忘了玻璃球，或者绵羊悄无声息地溜出了，然后那些小铃铛就变成了泪水……","t":[7816,16013]}]},{"id":"ch27p06","audio":"ch27p06.mp3","sents":[{"ar":"هذه معضلة غير محلولة.","zh":"这是一桩不解之谜。","t":[103,3408]},{"ar":"للذين منكم يحبون الأمير الصغير مثلي، إذا كان في زاوية من الكون، هناك خروف لم نره من قبل يأكل وردة، هل هذا ممكن؟ فإن كل شيء في الكون سيختلف…","zh":"对于你们这些也喜爱小王子的人，还有我，若在宇宙的某个角落，有一只我们从未见过的绵羊——真的吗？——吃掉了一朵玫瑰，那么，宇宙间的一切都将不再相同……","t":[3408,17790]}]},{"id":"ch27p07","audio":"ch27p07.mp3","sents":[{"ar":"أنظر إلى السماء","zh":"仰望星空。","t":[103,1300]},{"ar":"اسألوا أنفسكم: هل أكل الخروف الزهرة؟ نعم أو لا؟","zh":"请自问：是，还是否？","t":[1300,7461]},{"ar":"هل أكل الأغنام الزهرة؟","zh":"绵羊是否吞食了那朵花？","t":[7461,10197]},{"ar":"ستلاحظون كيف تتغير الأمور...","zh":"你们便会察觉万物如何变幻。","t":[10197,12869]}]},{"id":"ch27p08","audio":"ch27p08.mp3","sents":[{"ar":"لا يمكن للبالغين أبدًا فهم مدى أهمية هذا السؤال!","zh":"大人永远无法明白，这个问题有多么重要！","t":[103,4300]}]},{"id":"ch27p09","audio":"ch27p09.mp3","sents":[{"ar":"هذا، بالنسبة لي، أجمل وأحزن مناظر الأرض في العالم.","zh":"这，于我而言，是世上最美丽又最悲伤的风光。","t":[103,6171]},{"ar":"كما في الصفحة السابقة، لكنني رسمته ثانية لكي أعمق انطباعكم به.","zh":"与前页相同，但我再次绘制它，是为了加深你们的印象。","t":[6171,12855]},{"ar":"الأمير الصغير هو من هبط هنا على الأرض ومن هنا غاب.","zh":"小王子便是在此地降临地球，又在此地消失。","t":[12855,17131]}]},{"id":"ch27p10","audio":"ch27p10.mp3","sents":[{"ar":"أنظروا بعناية لتتمكنوا من التعرف عليه إذا ما سافرتم إلى الصحراء في أفريقيا.","zh":"仔细端详，以便有朝一日你在非洲沙漠旅行时能认出它。","t":[103,7329]},{"ar":"إذا مررتم هنا، لا تتسرعوا في السير.","zh":"若你途经此地，请勿匆匆赶路。","t":[7329,11526]},{"ar":"انتظروا قليلاً تحت النجوم.","zh":"在星光下稍作等待。","t":[11526,14763]},{"ar":"إذا رأيتم طفلاً يضحك بفرح، بأسنان ذهبية، لا يستجيب لأسئلتكم، إنه هو.","zh":"若有个孩童笑逐颜开，金发披肩，对问话不答，你便识得他是谁了。","t":[14763,23158]},{"ar":"إذا حدث ذلك، فأرجوكم أن تهدئوا من روعكم.","zh":"若此成真，请安慰我。","t":[23158,28211]},{"ar":"أخبروني أنه قد عاد.","zh":"请告知我他已归来。","t":[28211,30144]}]},{"id":"ch27p11","audio":"ch27p11.mp3","sents":[{"ar":"سان إكزوبيري: سيرة.","zh":"圣埃克苏佩里：简传","t":[103,2090]}]},{"id":"ch27p12","audio":"ch27p12.mp3","sents":[{"ar":"أصدقاؤه يطلقون عليه اسم سان إكزوبيري.","zh":"他的朋友们称他为圣埃克苏佩里。","t":[103,4329]},{"ar":"في الواقع، اسمه أنطوان دو سانت إكزوبيري.","zh":"实际上，他名叫安东尼·德·圣埃克苏佩里。","t":[4329,8882]},{"ar":"هو من أبرز الكتاب الفرنسيين العظماء.","zh":"他是法国最伟大的作家之一。","t":[8882,12868]},{"ar":"وهو أيضًا من رواد صناعة الطيران.","zh":"他也是航空业的先驱之一。","t":[12868,16684]},{"ar":"هذه قصته.","zh":"这是他的故事。","t":[16684,17935]}]},{"id":"ch27p13","audio":"ch27p13.mp3","sents":[{"ar":"ولد سان إكزوبيري في عام 1900 في ليون.","zh":"圣埃克苏佩里于1900年出生于里昂。","t":[103,4895]},{"ar":"في شبابه، كان يحلم بال مغامرة.","zh":"早年，他梦想着冒险。","t":[4895,8829]},{"ar":"كان يطمح إلى أن يصبح ضابطًا بحريًا.","zh":"他最大的愿望是成为一名海军军官。","t":[8829,12855]},{"ar":"لكي يصبح ضابطًا بحريًا، كان عليه أن يPASS امتحانًا شديد الصعوبة.","zh":"为了成为一名海军军官，必须通过一场极其艰难的考试。","t":[12855,19224]},{"ar":"لم يتمكن سان إكزوبيري من اجتياز الإمتحان...","zh":"圣埃克苏佩里应试未果...","t":[19224,23658]},{"ar":"لحسن الحظ، كان هناك حل آخر - الطيران.","zh":"幸而，还有另一种解决办法——航空。","t":[23658,29013]},{"ar":"في ذلك الوقت كان الطيران خطيرًا.","zh":"那时，航空极为危险。","t":[29013,32697]},{"ar":"الخطورة، المخاطرة - هذا ما كان يبحث عنه سان إكزوبيري.","zh":"危险，风险——这正是圣埃克苏佩里所渴望的。","t":[32697,38842]},{"ar":"خلال فترة خدمته، تعلم قيادة الطائرة.","zh":"在服役期间，他学会了驾驶飞机。","t":[38842,43592]},{"ar":"كان في قلبه فكرة واحدة فقط: الطيران.","zh":"圣埃克苏佩里心中只有一个念头：飞翔。","t":[43592,47710]}]},{"id":"ch27p14","audio":"ch27p14.mp3","sents":[{"ar":"بعد انتهاء خدمته، أعرب سان إكزوبيري عن رغبته في أن يصبح طيارًا لمدير شركة طيران.","zh":"服役结束后，他向一家航空公司经理表达了自己想成为一名飞行员的愿望。","t":[103,8500]},{"ar":"قال المخرج له: 'افعل كما يفعل الآخرون'.","zh":"导演对他说：“就像别人一样做吧。”","t":[8500,13132]},{"ar":"أولاً، يجب أن تتعلم أن تكون ميكانيكيًا.","zh":"首先，你得学会做一名机械师。","t":[13132,17026]}]},{"id":"ch27p15","audio":"ch27p15.mp3","sents":[{"ar":"عمل سان إكزوبيري بجد لكي يصبح ميكانيكيًا.","zh":"圣埃克苏佩里努力成为一名机械师。","t":[103,4868]},{"ar":"1927، وقد تحققت له الأهداف أخيرًا","zh":"1927年，他终于实现了目标。","t":[4868,9974]},{"ar":"كان طيارًا في الفريق","zh":"他是编队中的飞行员。","t":[9974,11303]},{"ar":"أكمل مهمات طيران خطيرة فوق البحر الأبيض المتوسط والصحراء الكبرى","zh":"他在地中海、撒哈拉上空完成了危险的飞行任务。","t":[11303,16750]},{"ar":"واجه العديد من الحوادث في وسط الصحراء","zh":"他在沙漠中央遭遇了许多事故。","t":[16750,19750]},{"ar":"بعد ذلك، أصبح مديرًا لشركة الطيران الخاصة به في أمريكا الجنوبية","zh":"后来，他成为南美自己航空公司的总监。","t":[19750,25316]},{"ar":"وفي ذلك المكان، أكمل العديد من المهمات الخطيرة فوق جبال الأنديز","zh":"在那儿，他也在安第斯山脉上空完成了许多危险的任务。","t":[25316,31092]}]},{"id":"ch27p16","audio":"ch27p16.mp3","sents":[{"ar":"بالنسبة لسانت إكزوبيري، كان الطيران أكثر من مجرد قيادة الطائرة","zh":"对圣埃克苏佩里而言，飞行不仅仅是驾驶飞机。","t":[103,5695]},{"ar":"بل كان أيضًا التأمل والتفكير","zh":"也在沉思，在反思。","t":[5695,7984]},{"ar":"خلال تنفيذ المهمات، التفكير بعمق في مفاهيم الوحدة، الصداقة، معنى الحياة، الظروف البشرية والحرية","zh":"在执行任务期间，圣埃克苏佩里深刻思考着孤独、友谊、生命的意义、人的境遇和自由。","t":[7984,17500]},{"ar":"نشر تفكيره","zh":"他发表了反思。","t":[17500,18605]},{"ar":"أصبحت كتبه ناجحة فور صدورها","zh":"他的书籍立刻大获成功。","t":[18605,21763]}]},{"id":"ch27p17","audio":"ch27p17.mp3","sents":[{"ar":"للأسف، كانت شركة الطيران التي يعمل فيها سانت إكزوبيري تواجه أزمة مالية خطيرة","zh":"不幸的是，圣埃克苏佩里供职的航空公司正面临严重的财务困境。","t":[103,7484]},{"ar":"كان عليه مغادرة الشركة","zh":"圣埃克苏佩里不得不离开公司。","t":[7484,9576]},{"ar":"أصبح صحفيًا","zh":"他成为一名记者。","t":[9576,10866]},{"ar":"سافر إلى إسبانيا وروسيا وألمانيا","zh":"他游历过西班牙、俄罗斯和德国。","t":[10866,13721]},{"ar":"كان يطير في كل فرصة يواجهها","zh":"他一有机会就飞行。","t":[13721,16458]}]},{"id":"ch27p18","audio":"ch27p18.mp3","sents":[{"ar":"في عام 1939، اندلعت الحرب بين فرنسا وألمانيا","zh":"1939年，法国与德国开战。","t":[103,6261]},{"ar":"انضم سانت إكزوبيري فورًا إلى الجيش","zh":"圣埃克苏佩里立刻应征入伍。","t":[6261,9050]},{"ar":"بدأت الهزيمة تلوى","zh":"败局随之而至。","t":[9050,10576]},{"ar":"سقطت فرنسا في أيدي جيش هتلر","zh":"法国沦陷于希特勒的军队之手。","t":[10576,13340]}]},{"id":"ch27p19","audio":"ch27p19.mp3","sents":[{"ar":"لم يرض سانت إكزوبيري بالهزيمة","zh":"圣埃克苏佩里不接受失败。","t":[103,2550]},{"ar":"قرر مغادرة فرنسا","zh":"他决定离开法国。","t":[2550,4261]},{"ar":"استقر في أمريكا وواصل الكتابة","zh":"他在美国定居，继续写作。","t":[4261,6866]},{"ar":"في نيويورك، نشر كتابه 'الصغير'، وهو من أشهر أعماله","zh":"在纽约，他出版了《小王子》，这是他最著名的作品之一。","t":[6866,11932]}]},{"id":"ch27p20","audio":"ch27p20.mp3","sents":[{"ar":"في عام 1942، غزت القوات الأمريكية شمال أفريقيا","zh":"1942年，美军在北非登陆。","t":[103,6432]},{"ar":"قرر سانت إكزوبيري الانضمام إلى الجيش الأمريكي","zh":"圣埃克苏佩里决定加入美国军队。","t":[6432,10089]},{"ar":"في عمر أربع وثلاثين، التحق بصفوف الطيارين التطوعيين","zh":"四十二岁时，他志愿成为了一名飞行员。","t":[10089,15158]},{"ar":"أخبروه أن عمره كبير جدًا","zh":"他被告知自己年纪太大。","t":[15158,17671]},{"ar":"كان يبذل جهداً مستمراً","zh":"他坚持不懈。","t":[17671,19592]},{"ar":"أخيرًا، حصل على ما يرضيه","zh":"终于，他得到了满足。","t":[19592,22026]},{"ar":"حصل على طائرة","zh":"他得到了一架飞机。","t":[22026,23382]},{"ar":"أكمل العديد من المهمات فوق فرنسا المحتلة","zh":"他在被占领的法国上空完成了许多任务。","t":[23382,27013]}]},{"id":"ch27p21","audio":"ch27p21.mp3","sents":[{"ar":"في 31 يوليو 1944، شارك أنطوان دو سانت إكزوبيري في مهمته الأخيرة","zh":"1944年7月31日，圣埃克苏佩里踏上他最后的使命。","t":[103,9395]},{"ar":"تم تدمير طائرته فوق بحر الأبيض المتوسط من قبل الألمان","zh":"他的飞机在地中海上空被德国人摧毁。","t":[9395,14197]},{"ar":"في ذلك اليوم، لم يعد سانت إكزوبيري……","zh":"那天，圣埃克苏佩里未能归来……","t":[14197,18382]},{"ar":"في الفضاء العظيم، بحث عن المخاطرة والموت والشرف","zh":"在辽阔的天际，他觅得风险、死亡与荣耀。","t":[18382,23158]}]}]}]};